window.__D("text/keter-shem-tov/c000",{"p":[[300010004,"הסכמה\n\n<b>וישא</b> אהרן את ידיו להניף את חזה התנופה, מחזה שדי יחזה מזה בן מזה והוציא אור החכמה ושמש תפארת עוזה מנרתיקה, להראות השרים הם החכמים את יפיה בהראותו את עושר כבוד החכמה ואת יקר תפארת גדולת הבינה, הרואה אומר ברקאי האיר והבריק השחר, הנותן אמרי שפר, והם דברי קדשו של הרב רבינו הקדוש הבעש\"ט זלה\"ה אשר בספרי קדש של תלמידו הרב הגאון מו' יעקב יוסף הכהן אב\"ד (ד\"ק) [דק'] פולנאי זלה\"ה ומשאר ספרים וכתבים. והנה אף שלא נחשדו ישראל לעבור על ארור מסיג גבול כו', אעפ\"כ באתי כמזכיר שחלילה לכל בר ישראל להדפיס הספר כתר שם טוב תוך משך עשר שנים, וגם שלא יוסיפו המדפיסים להדפיס בשעת הדפוס ואח\"כ מיום כלות הדפוס של הרבני מוהר\"ר אהרן במוהר\"ר צ\"ה כהן (מ\"ק) [מק'] אפטא, וחוקה חקקתי גזירה גזרתי בא\"ח להיות כל הדפוסין אסורין במתכונתו לא יעשו כמוהו בלתי רשות מו' אהרן הנ\"ל, והעובר על דברי חכמים יהי' הנחש כרוך על עקיבו, ואשר יביט אל הנחש וחי, ד' יריק לו ברכה עד בלי די. הכ\"ד העומד על התורה ועל העבודה:\n<b>הק' מנחם מענדל חופ\"ק ליסקא יע\"א</b>\n<b>הק' שלמה מקאַרלין ולע\"ע בק' לאדמיר</b>\n<b>הק' אברהם משה מפּרשוואָרסק</b>"],[300010005,"צוואה\n\n<b>צוואה מהבעש\"ט זלה\"ה</b>\n<b>א'</b> להיות תמים בעבודתו ית' עבודה תמה, <span data-k=\"sm\">[ועיקר שלא לשכוח הדברים]</span> ללמוד בכל יום שיעור מוסר הן רב הן מעט. ולראות תמיד לדבק את עצמו במדות טובות והנהגות ישרות, ושלא להניח שום יום מעשיות מצוה בו הן קלה הן חמורה, וסימנך הוי זהיר במצוה קלה כבחמורה, פי' זהיר מלשון והמשכילים יזהירו &lt;כזוהר&gt;, ר\"ל הנשמה תאיר ותזהיר ממצוה קלה כבחמורה, כי רחמנא לבא בעי. וז\"ש <span data-k=\"sm\">[נ\"א:</span> <span data-k=\"sm\">וסימנך. ועוד נ\"א: וזהו פירוש]</span> שומר מצוה לא ידע דבר רע, שומר מלשון ואביו שמר את הדבר, היינו מצפה, כן צ\"ל ממתין ומצפה מבוקר עד ערב אולי יזדמן לו איזה מצוה, וסימנך חסד אל כל היום<i>[ftnref_1_א]</i>.\n<b>ב'</b> לדקדק בק\"ש בכל תיבה ותיבה, והוא דבר גדול, הגם שא\"א לו להתפלל בלי מחשבה זרה, ירגיל עצמו בק\"ש בלי מ\"ז, וסימנך כל הקורא ק\"ש מזיקין בדילין ממנו, הן היזק הגוף הן היזק הנפש.\n<b>ג'</b> לעשות טבילה כל מה שיוכל, ובפרט בעת הצורך.\n<b>ד'</b> לשמור שבת כהלכתו בכל דקדוקיו ופרטיו, וסימנך תשב אנוש עד דכא, תשב אותיות שבת, ודרז\"ל אנוש פי' אפי' עע\"ז כדור אנוש מוחלין לו.",[["","","----- מקורות ומראה מקומות -----\n<b>לקו</b><b>\"י יז, א (סי' קצח) [צוה</b><b>\"ר סי' א, יז-יט]</b>\n<i>עבודה תמה</i> – יומא כד, א. <i>הוי זהיר כו'</i> – אבות פ\"ב מ\"א. <i>והמשכילים גו'</i> – דניאל יב, ג. <i>רחמנא ליבא בעי</i> – זח\"ב קסב, ב. סנהדרין קו, ב. <i>שומר מצוה גו'</i> – קהלת ח, ה. <i>ואביו שמר גו'</i> – וישב לז, יא. <i>חסד גו'</i> – תהלים נב, ג. <i>כל הקורא כו'</i> – ברכות ה, א. <i>תשב גו'</i> – תהלים צ, ג. <i>ודרז\"ל כו'</i> – שבת קיח, ב.\n----- שולי הגליון -----\n[ftn_1_א]) <i>בצוה\"ר מוסיף כאן</i>: היינו שבכל יום ויום צריך לעשות חסד לאל ית'.\n----- הערות וציונים -----\n<i>א. וללמוד שיעור מוסר</i> – ראה צוה\"ר סי' קיז. לקו\"ת לאדה\"ז פ' תבוא מג, ג. מאה שערים כ, ב ד\"ה נידון שאלתכם (ועיי\"ש נה, א בהערות כ\"ק אדמו\"ר זי\"ע). וראה עוד הל' ת\"ת לאדה\"ז פ\"ב ה\"ב וה\"ט ושם פ\"ג ה\"ד. ועיין יערות דבש ח\"ב דרוש יב. דבש לפי להחיד\"א מערכת ת סי' מא.\n<i>ושלא להניח שום יום</i> כו' – להעיר מזח\"א קכט, א ושם רכד, א.\n<i>פי' זהיר</i> כו' – ראה של\"ה, מס' שבועות (הובא לקמן סי' שיט ד\"ה וז\"ש הנחמדים). וראה לקמן בהוספות סי' צו ובהערות שם (ובאורך יותר בספר השיחות קייץ ה'ש\"ת ע' 22). תניא אגה\"ק סס\"י ז.\n<i>רחמנא לבא בעי</i> – ראה לקו\"י סי' קו. להעיר מזח\"ב קסב, ב.\n<i>שומר מלשון</i> כו' – ראה הקדמת ס' חרדים בתנאי המצוות התנאי הי\"ג, וראה מדל\"י סי' קכב (קלא). ולהעיר מזח\"ב פט, סע\"א וזח\"ג פב, סע\"א.\n<i>ב. לדקדק בק\"ש</i> כו' – להעיר מתנחומא פ' קדשים ו. ועיין פע\"ח שער ק\"ש פי\"א ופכ\"ה, ושם שער קשעה\"מ רפי\"א.\n<i>ג. לעשות טבילה</i> כו' – ראה צוה\"ר סי' טו, ולקמן סי' ריט. וראה בסוף הקדמות הרח\"ו לס' ע\"ח, ערך השגת החכמה (וכ\"ה בריש שער רוה\"ק לו, א ובשו\"ע האריז\"ל בהלכות ביהכ\"נ).\n<i>ד. לשמור שבת</i> כו' – ראה ס' חרדים מצות התשובה פ\"ז ד\"ה סגולה שנית.\n<i>תשב אותיות שבת</i> – ראה תניא אגה\"ת ספ\"י, ובכ\"מ. וראה יפה תואר לבר\"ר ספכ\"ב. ולקמן בהוספות סי' רלז.\n<i>אפילו עע\"ז כו'</i> – מבואר במדל\"י סי' קכג (קלב)."]]],[300010006,"א\n\n<b>כתר שם טוב</b>\n<b>העתק האגרת שכתב הרב הקדוש ר' ישראל בעש\"ט זלה\"ה לארץ הקדושה</b><i>[ftnref_1_ב]</i>\n<b>בר\"ה</b> שנת תק\"ז עשיתי השבעת עליית הנשמה כידוע לך, וראיתי דברים נפלאים במראה מה שלא ראיתי עד הנה מיום עמדי על דעתי, ואשר ראיתי ולמדתי &lt;בעלותי&gt; <span data-k=\"sm\">[בהעלות]</span> לשם בלתי אפשרי לספר ולדבר אפי' פה אל פה, אך בחזירתי לג\"ע התחתון וראיתי כמה נשמות החיים והמתים, הידועים לי ושאינם ידועים לי, בלי שיעור ומספר, ברצוא ושוב, לעלות מעולם לעולם דרך העמוד הידוע ליודעי חן, בשמחה רבה וגדולה אשר ילאה הפה לספר וכבד אוזן הגשמי משמוע, וגם רשעים רבים חזרו בתשובה ונמחל להם עונותיהם, באשר שהי' עת רצון גדול שגם בעיני יפלא מאד שכמה וכמה נתקבלו בתשובה, שגם אתה ידעת אותם, והיה ביניהם ג\"כ שמחה רבה עד מאד ועלו ג\"כ בעליות הנ\"ל. וכולם כאחד בקשו ממני &lt;והפצירו&gt; <span data-k=\"sm\">[והרצו]</span> בי עד בוש באמרם, לרום מעלת כבוד תורתך חננך ד' בבינה יתירה להשיג ולדעת מענינים האלה, עמנו תעלה להיות לנו לעזר ולסעד. ומחמת השמחה הגדולה שראיתי ביניהם, אמרתי לעלות עמהם. <span data-k=\"sm\">[וראיתי במראה כי הס\"א עלה לקטרג בשמחה גדולה אשר לא היה כמוהו, ופעל פעולותיו גזירות שמד על כמה נפשות שיהרגו במיתות משונות, ואחזתני פלצות ומסרתי ממש נפשי]</span>, ובקשתי ממורי ורבי שלי שילך עמי, כי סכנה גדולה לילך ולעלות לעולמות העליונים, כי מיום היותי על עמדי לא עליתי בעליות גדולות כמוהו.\n<b>ועליתי</b> מדריגה אחר מדריגה, עד שנכנסתי להיכל משיח ששם לומד משיח תורה עם כל התנאים והצדיקים וגם עם שבעה רועים, ושם ראיתי שמחה גדולה עד מאד, ואיני יודע לשמחה זו מה הוא עושה, והייתי סובר שהשמחה הזו ח\"ו על פטירתי מהעוה\"ז, והודיעו לי אח\"כ שאיני נפטר עדיין כי הנאה להם למעלה כשאני מייחד יחודים למטה ע\"י &lt;תורתם&gt; <span data-k=\"sm\">[תורותיהם]</span> הקדושה, אבל מהות השמחה איני יודע עד היום הזה.\n<b>ושאלתי</b> את פי משיח, אימת אתי מר, והשיב לי, בזאת תדע, בעת שיתפרסם למודך ויתגלה בעולם ויפוצו מעיינותיך חוצה מה שלמדתי אותך והשגת, ויוכלו גם המה לעשות יחודים ועליות כמוך, ואז יכלו כל הקליפות ויהיה עת רצון וישועה.\n<b>ותמהתי</b> ע\"ז, והי' לי צער גדול באריכות הזמן כל כך מתי זה אפשר להיות. אך ממה שלמדתי בהיותי שם שלשה דברים סגולות ושלשה שמות הקדושים, והם בנקל ללמוד ולפרש, ונתקרר דעתי, וחשבתי אפשר שעי\"ז יוכלו גם אנשי גילי לבוא למדרגה ובחינה כמותי, דהיינו בהיותם יכולים לעליות נשמות וילמדו וישיגו כמו אני. ולא נתנה רשות כל ימי חיי לגלות זאת. ובקשתי עבורך ללמד אותך ולא הורשיתי כלל, ומושבע ועומד אני על זה.\n<b>אך</b> זאת אני מודיעך והשם יהיה בעזרך לנכח ה' דרכך ואל יליזו, <span data-k=\"sm\">[ובפרט בארץ הקדושה]</span>, בעת תפלתך ולימודך וכל דיבור ודיבור ומוצא שפתיך תכוין לייחד שם, כי בכל אות ואות יש עולמות ונשמות ואלהות, ועולים ומתקשרים ומתייחדים זה עם זה, ואח\"כ מתקשרים ומתייחדים האותיות &lt;ונעשה&gt; <span data-k=\"sm\">[ונעשים]</span> תיבה ומתייחדים יחוד אמיתי באלהות, ותכלול נשמתך עמהם בכל בחינה ובחינה מהנ\"ל, ומתייחדים כל העולמות כאחד ועולים, &lt;ונעשה&gt; <span data-k=\"sm\">[ונעשים]</span> שמחה ותענוג גדול לאין שיעור, בהבינך בשמחת חתן וכלה בקטנות וגשמיות, וכ\"ש במעלה העליונה כזאת. ובודאי ה' יהיה בעזרך ובכל אשר תפנה תצליח ותשכיל, תן לחכם ויחכם עוד.",[["","","----- מקורות ומראה מקומות -----\n<b>בן פורת יוסף, בסופו, קכז, ג-ד</b>\n----- שולי הגליון -----\n[ftn_1_ב]) בסוף ההוספות הובאה כל האגרת כמו שהיא בסו\"ס בן פורת יוסף.\n----- הערות וציונים -----\n<i>עשיתי השבעת עליית הנשמה</i> – רג\"כ סי' קסה. ועיין לקמן בהוספות סי' שכג.\n<i>לעלות </i>. .<i> דרך העמוד כו'</i> – ראה זח\"א פא, א.\n<i>ובקשתי ממורי ורבי שלי</i> – ה\"ה אחי' השילוני, כדלקמן סי' קמג ובהוספות סי' רפא.\n<i>עם שבעה רועים</i> – ע\"פ מיכה ה, ד ורש\"י שם. סוכה נב, ב ורש\"י שם.\n<i>ושאלתי את פי משיח כו'</i> – ראה דמ\"א פ' בשלח סד\"ה ובני ישראל יוצאים ביד רמה. ועיין לקמן בהוספות סי' שמה.\n<i>כי יש בכל אות כו'</i> – ראה צוה\"ר סי' עה (כמעט כלשונו וכתבו כאן).\n<i>עולמות ונשמות ואלקות</i> – ראה לקמן בהוספות סי' רכב."]]],[300010007,"ב\n\n<b>כוונת המקוה מהבעש\"ט זלה\"ה</b>\n<b>מקודם</b> יכוון סוד הנזכר בגמרא שש מעלות במקואות, ועל פי סוד כזה: יה\"ו חסד, יו\"ה נצח, הו\"י גבורה, הי\"ו הוד, וי\"ה ת\"ת, וה\"י יסוד, <span data-k=\"sm\">[והם השמות הכתובים בכוונת הלולב, כמ\"ש האריז\"ל טעמם ונימוקם שם בכוונת הלולב]</span>. והמים שבמקוה הם ט' יודין דע\"ב ס\"ג מ\"ה ב\"ן גימטריא מים, וכולם נמשכין משם ע\"ב, שהוא הראשון שהוא חסד גי' ע\"ב, והוא בחי' מים, לכן הם מ' סאה נגד ד' יודין דע\"ב. גם מקוה גי' קנ\"א, כמנין אהי\"ה במילוי ההי\"ן, שהוא בסוד הבינה, שהוא בית קיבול לקס\"א קמ\"ג.\n<b>והנה</b> בנין הגוף הוא ע\"י שם קנ\"א, &lt;כמ\"ש&gt; <span data-k=\"sm\">[כמבואר בכתבי]</span> האריז\"ל <span data-k=\"sm\">[בכוונת ליל הוש\"ר]</span>, והגוף <span data-k=\"sm\">[הנגוף]</span> הוא כלי חרס ואין לו טהרה במקוה, כי כלי חרס שבירתן זהו טהרתן. והענין הוא שקודם כניסתו למקוה צריך לשבור לבו בקרבו, ומקבל עליו עול מלכות שמים לעזוב פשעיו, ומעתה מוכן לעבוד באהבה חסד, ויראה גבורה, בכדי שיוכל השי\"ת להתפאר, תפארת, בו, כמ\"ש <span data-k=\"sm\">[הכתוב]</span> ישראל אשר בך אתפאר, וימסור א\"ע על קדושתו, ועי\"ז ינוצח, נצח, &lt;החטא&gt; <span data-k=\"sm\">[הס\"א]</span> בבטחונו בהש\"י שישיב את נדחו, וצריך להודות, הוד, לו שניצול ממצולת ים, ואז הוא נכלל בכלל צדיק יסוד עולם, ואז עי\"ז יתגדל ויוכר כבוד מלכותו, מלכות, &lt;ש\"ש&gt; <span data-k=\"sm\">[ית\"ש וית']</span> לעולם ועד.\n<b>ועוד</b> יכוין בהיותו במקוה, כי שם אדנ\"י, מלכות, הוא סוד הדיבור, ושם הוי' הוא ז\"א, סוד הקול, ושם אהי\"ה סוד המחשבה. ובמקוה הגג של המקוה נגד שם אהי', והד' רוחות של המקוה נגד ד' אותיות הוי', וקרקעית המקוה נגד שם אדני, והג' שמות <span data-k=\"sm\">[הנ\"ל]</span> הם גי' יב\"ק, הוא סוד יחוד ברכה קדושה. ויכוין שנכנס לבקש מהשי\"ת טהרה וקדושה למחשבתו ולקולו ולדיבורו, ואז ע\"י כוונת הנ\"ל אף שבע יפול צדיק וקם, אף אם ירד שבע מעלות אחורנית ירפאהו הש\"י, ויכרות ברית חדש אשר לא תופר, ואז יאיר על נשמתו קומה הרוחניות, אותיות מקוה.\n<b>סאה</b> גי' אדני, ס\"ה, וא' שבסאה הוא סוד חכמה שהוא י' ראשונה דשם הוי', י' במילוי כזה יו\"ד מרמז הו' לששה קבין שבסאה, ר\"ל לו' מעלות שבמקוה כנ\"ל, ששורש מילוים דע\"ב ס\"ג מ\"ה גי' ק\"ב, ו' פעמים ק\"ב גי' ברית, לתקן הפגם של הברית קודש, וד' של מילוי יו\"ד רומז לד' לוגין, כי יה\"ו במילוי אלפין גי' לוג. ועי\"ז יזכה לעבודת הש\"י.\n<b>ויאמר</b> פסוק זה עם הכונה, מקוה ישראל ה' מושיעו בעת צרה, ויכוין ר\"ת מקוה ישראל הוא מי, הוי' מושיעו הוא ר\"ת ים, שה\"ס השכינה <span data-k=\"sm\">[שממנה מתגלים הדינים בעוה\"ז, ומיתוק הדינים הוא ע\"י שמעלה אותם לשרשם שהוא יסוד הבינה]</span>, שממנה מתערין הדינים שבה שם אל\"ף ה\"ה יו\"ד ה\"ה כנ\"ל שהוא גי' מקוה, ושם נמתקים בסוד הלידה ע\"י המים שבמקוה, דהיינו ט' יודין דע\"ב ס\"ג מ\"ה ב\"ן שעולים גי' צ' כמנין מים, ועל ידי ד' יודין דע\"ב שהם מ' סאה. כי גילוי הגבורות הוא סוד שם אגל\"א, ר\"ל שמתגלים הה' גבורות שהם שורש כל הגבורות, ומתגלים בשכינה תתאה, סוד אדנ\"י, אמנם כשמתעלים הגבורות לשרשם, שהוא סוד מ\"י שנק' בינה, ונמתקים שם בסוד הלידה חדשה, נרמז שם הנ\"ל שמספרו אל\"ד. לכן יכוון כששוחה ראשו לתוך המים לטבול, &lt;יכוין&gt; בשם אהי\"ה אל\"ד בשילוב כזה אאהליד\"ה.\n<b>ועוד</b> יכוין ויצייר אלו הד' שמות בהיותו בתוך המקוה כזה, אל\"ד אהי\"ה הוי\"ה אדנ\"י, ויכוין הא' משם אל\"ד רומז לכתר עליון שהוא אלף, אותיות פל\"א, ול' רומז לג' קוין, קו ימין חכמה חסד נצח, קו שמאל בינה גבורה הוד, קו אמצעי דעת תפארת יסוד, וד' רומזת למל', סוד אדני.\nע\"כ העתקתי אות באות מדברי &lt;קדש של&gt; <span data-k=\"sm\">[האלהי]</span> הבעש\"ט זלה\"ה.",[["","","----- מקורות ומראה מקומות -----\n<b>לקו</b><b>\"י – יד</b><b>\"א כז, סע</b><b>\"ד (יד</b><b>\"א פמ</b><b>\"ב)</b>\n<i>שש מעלות כו'</i> – מקואות פ\"א מ\"א. <i>יה\"ו חסד כו'</i> – ר' זח\"ג יז, א. תקו\"ז טו, סע\"א ואילך. <i>כמ\"ש האריז\"ל </i>– פע\"ח שער הלולב פ\"ג. <i>חסד גי' ע\"ב </i>– תקו\"ז תכ\"א נה, ב. שם ח, סע\"ב. י, ריש ע\"ב. זח\"ב קעה, ב. ועוד. <i>והוא בחי' מים </i>– זח\"ג מא, רע\"א. שם רנה, א. <i>אהי' </i>. .<i> בסוד הבינה </i>– זח\"ג קח, ב. ע\"ח שט\"ז רפ\"ג. <i>בכתבי האריז\"ל</i> – פע\"ח שער הלולב פ\"ד. <i>כלי חרס ואין לו טהרה במקוה</i> – שבת פד, סע\"א. ספרא ורש\"י לשמיני יא, לג. <i>שבירתן זהו טהרתן </i>– כלים פ\"ב מ\"א. ספרא שם. <i>באהבה חסד ויראה גבורה</i> – תקו\"ז י, ב. <i>ישראל אשר גו'</i> – ישעי' מט, ג. <i>שם אד' מלכות</i> – זח\"ג יא, א. <i>סוד הדיבור</i> – זח\"ג רכח, א. תקו\"ז ב, סע\"ב. <i>שם הוי' הוא ז\"א</i> – זח\"ג קכט, א. <i>סוד הקול</i> – זח\"ג רכח, א. תקו\"ז ב, ב. <i>ושם אהי' סוד המחשבה</i> – זח\"ג רכט, א. <i>והג' שמות </i>. .<i> יב\"ק</i> – זח\"ג ריז, רע\"א. שם רכט, א. <i>סוד יחוד ברכה קדושה</i> – ראה זח\"ג רטז, ב. תקזו\"ח קי, רע\"א. <i>שבע יפול גו'</i> – משלי כד, טז. <i>קומה </i>. .<i> מקוה</i> – תקו\"ז תי\"ט לט, א. <i>וא' </i>. .<i> סוד חכמה</i> – זח\"א כו, ב. <i>שהוא י' כו'</i> – זח\"ב קכג, ב. זח\"א לא, א.<i> מקוה ישראל גו' </i>– ירמי' יד, ח. שם יז, ג. <i>ים שה\"ס השכינה</i> – ראה זח\"ג נח, א. <i>שממנה מתגלים כו'</i> – זח\"ג קיד, ב. <i>ומיתוק הדינים הוא כו'</i> – ע\"ח שי\"ג פי\"א. פע\"ח שער השופר פ\"א. <i>שממנה מתערין כו'</i> – זח\"ג סה, א. <i>גילוי הגבורות הוא כו'</i> – זח\"ג שז, סע\"א. <i>מי שנק' בינה</i> – זח\"ב קיז, א. <i>הא' </i>. .<i> לכ\"ע</i> – תקו\"ז תכ\"א נט, א. שם תס\"ט קטו, א. <i>אלף אותיות פל\"א</i> – זח\"ג קצג, ב. תקו\"ז ת\"ע קלה, א. <i>וד' רומזת למל'</i> – זח\"ג רנז, א.\n----- הערות וציונים -----\n<i>כוונת המקוה</i> – לכו\"כ ענינים בסימן זה יש להעיר מסוד הטבילה אשר בפע\"ח שער השבת פ\"ג עיי\"ש.\n<i>והד' של מילוי יו\"ד רומז לד' לוגין</i> – כלומר לד' לוגין שיש בקב.\n<i>מקוה ישראל ה' מושיעו בעת צרה</i> – יש כאן הרכבת שני פסוקים (ירמי' יד, ח ושם יז, יג). וכן הובא בסוף תקו\"ז סת\"ה קמג, ב, ועיי\"ש בכסא מלך אות ת.\n<i>שם אגל\"א</i> – ראה זח\"ג שז סע\"א (והובא בזו\"ח ר\"פ תרומה מב, א).\n<i>שם אל\"ד</i> – שם העשירי משם ע\"ב כמובא בזח\"ב ער, א."]]],[300010008,"ג\n\n<b>&lt;מהבעש\"ט.</b> ביאור&gt; <span data-k=\"sm\">[שמעתי בשם </span>מורי<span data-k=\"sm\"> פירוש המדרש]</span> הלואי אותי עזבו ותורתי שמרו, &lt;פי'&gt;, <span data-k=\"sm\">[ביאור ע\"פ הלצה, כי גנבא אמחתרתא רחמנא קריא, וזה שאמרו הלואי אותי עזבו, שלא לקרא אותי ולא יגנוב, ואז תורתי שמרו, וק\"ל.</span>\n<b>עוד</b> <span data-k=\"sm\">ביאר]</span>, כי &lt;תכלית&gt; הידיעה שלא נדע, אמנם יש ב' סוגי שלא נדע, א' מיד, שאינו נכנס לחקור ולידע מאחר דא\"א לידע, ב' שחוקר ודורש עד שידע שא\"א לידע. וההפרש בין זה לזה &lt;מלה\"ד&gt;, שנים שרוצים לידע את המלך, וא' נכנס בכל חדרי המלך ונהנה מאוצרי והיכלי המלך, ואח\"כ לא יוכל לידע המלך, והשני אמר, מאחר שא\"א לידע המלך, לא נכנס כלל לחדרי המלך ולא נדע מיד.\n<b>ובזה</b> יובן ודאי בשני סוגים הנ\"ל, אותי עזבו מלידע, שא\"א, מ\"מ הלואי אותי עזבו מתוך החקירה והידיעה אחר שתורתי שמרו <span data-k=\"sm\">[ודפח\"ח]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>בפ</b><b>\"י, ב, א (כב, א)</b>\n<i>הלואי אותי כו'</i> – ירוש' חגיגה פ\"א ה\"ז. איכ\"ר פתיחתא ב. <i>גנבא כו'</i> – ברכות סג, א (גי' הע\"י). <i>תכלית הידיעה כו'</i> – בחינת עולם יג, מה. ס' העיקרים מ\"ב ספ\"ל. של\"ה מס' שבועות קצא, א (לז, ג).\n----- הערות וציונים -----\nראה לקו\"י סי' צט. ולהעיר מלקמן סי' רו-ב.\n<i>מתוך החקירה והידיעה</i> – ראה חובה\"ל שער היחוד פ\"ג. כוזרי מ\"ה סכ\"ב. רמב\"ם הל' יסוה\"ת פ\"א ומו\"נ ח\"ג פנ\"א."]]],[300010009,"ד\n\n<b>&lt;מהבעש\"ט&gt;</b> כל אחד צריך להתנהג עפ\"י מדריגתו, משא\"כ התופס מדריגה &lt;של חבירו&gt; <span data-k=\"sm\">[שאינה שלו]</span>, זה וזה לא נתקיימה בידו. וז\"ש הרבה עשו כרשב\"י ולא עלתה בידם, ר\"ל שלא היו בבחינה זו רק שעשו כרשב\"י שראו אותו בבחי' זו, ולכך לא עלתה בידם. <span data-k=\"sm\">[וכן שמעתי </span>ממורי<span data-k=\"sm\"> סברא זו, ודפח\"ח.]</span>",[["","","----- מקורות ומראה מקומות -----\n<b>בפ</b><b>\"י, הקדמה ה, ב (לו, א)</b>\n<i>הרבה עשו כו'</i> – ברכות לה, ב.\n----- הערות וציונים -----\n<i>זה וזה לא נתקיימה בידו</i> – להעיר מסוטה ט סע\"א. זח\"ג קעו סע\"א. וראה משנת ר\"א פי\"ח.\n<i>הרבה עשו כרשב\"י כו'</i> – ביאור זה הובא כ\"פ בס' תוי\"י. וראה שם פ' וישלח (כז, א) שעשו כרשב\"י לעשות כמוהו ולא מהלב. ושם פ' מצורע (פה, רע\"א) שעשו כרשב\"י לא מצד בחירתן רק שרוצה לעשות כמו שעשו אחרים ובזה נשאר קרח מכאן ומכאן כי מדריגתו אבד ומדריגת אחרים לא השיג והגיע (ועד\"ז שם פ' מקץ לא, א). השוה צוה\"ר סי' מז, ושם כדי שיבואו למדרגת רשב\"י, ולכך לא עלתה בהם."]]],[300010010,"ה\n\n[<b>דאיתא</b> <span data-k=\"sm\">בש\"ס]</span> &lt;מבעש\"ט פי' הש\"ס&gt; יצא ב\"ק ואמר כל העולם ניזון בשביל חנינא בני כו', . . . <span data-k=\"sm\">[</span>וממורי<span data-k=\"sm\"> שמעתי]</span> כי שביל הוא צנור, שפתח צנור ושביל השפע. וז\"ש בשביל חנינא בני <span data-k=\"sm\">[ודפח\"ח]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>בפ</b><b>\"י, הקדמה ח, רע</b><b>\"ג (מד, ב)</b>\n<i>יצא ב\"ק כו'</i> – ברכות יז, ב.\n----- הערות וציונים -----\nראה לקמן סי' רנו, והובא כ\"פ בספרי התוי\"י. ולהעיר שביאור זה כבר נמצא בשל\"ה, פ' וישב, בדרוש צאן יוסף (כז, ג. ובדפ\"י רצט, ב). וראה עוד מש\"כ כאן בבפ\"י לפני פירוש הבעש\"ט בשם האלשיך ויקרא כג, לג, ושם פ' ויחי פ, ד מס' יד יוסף."]]],[300010011,"ו\n\n<b>והדבר</b> אשר יקשה מכם תקריבון אלי. &lt;פי' הבעש\"ט&gt; . . . <span data-k=\"sm\">[דשמעתי </span>ממורי<span data-k=\"sm\">]</span> בשם הרמב\"ן, שצוה לבנו, אם יסתפק לך באיזה דבר <span data-k=\"sm\">[מצוה]</span> איך לעשותו כשיש בו דרכים לצדד לכאן ולכאן, או שיש לך ספק אם הוא מצוה או לאו ואם יש לעשותו או למנוע ממנו, &lt;והדבר שיש לאדם הנאה ממנו יכוין למצוא ראי' להתיר האסור, ע\"כ&gt; אז תראה קודם כל לסלק מעסק דבר זה הנאת עצמך או כבודך, ואח\"כ תראה לצדד לכאן ולכאן, אז השי\"ת יודיעך האמת ותלך לבטח, <span data-k=\"sm\">[ודפח\"ח]</span>. . .\n<b>&lt;וז\"ש&gt;</b> <span data-k=\"sm\">[ובזה יובן]</span> והדבר אשר יקשה מכם, <span data-k=\"sm\">[ר\"ל הדבר אשר יקשה]</span> שאינכם יודעים איך לעשותו או למנוע <span data-k=\"sm\">[כלל, אם הוא מצוה או לאו]</span>, הספק נולד מכם, שיש בו הנאתכם, <span data-k=\"sm\">[כמו לך לכם להנאתכם]</span>, &lt;ע\"כ תסלקו מדבר זה&gt; <span data-k=\"sm\">[משא\"כ אם תסלקו מהדבר]</span> הנאתכם <span data-k=\"sm\">[וכבודכם]</span> ותקרבון אלי, <span data-k=\"sm\">[שהוא יותר פנימי מן לי]</span> והכוונה שיהי' <span data-k=\"sm\">[רק]</span> לשם שמים בלי שום פניה והנאה, אז ושמעתיו, &lt;אתן לו הבנה&gt; איך יתנהג, וק\"ל.",[["","","----- מקורות ומראה מקומות -----\n<b>בפ</b><b>\"י, הקדמה ט, ד (נו, א)</b>\n<i>והדבר אשר גו' ושמעתיו</i> – דברים א, יז.\n----- הערות וציונים -----\nענין זה הובא ג\"כ בקו\"א דס' בפ\"י (קכו, ד): ושמעתי ממורי בשם הרמב\"ן כי דבר שיש לאדם הנאה ממנו אז יכול למצוא ראיה להתיר האסור, על כן צריך תחילה להסיר כל הנאתו מזה וכו' כי תיבת אין יש לו ב' משמעות וכו' (ראה לקמן סי' ז וסי' יג). ורג\"כ בתוי\"י פ' שפטים (קפא, ב).\n<i>הספק נולד מכם</i> – להעיר מירושלמי פאה פ\"א ה\"א עה\"פ כי לא דבר רק הוא מכם.\n<i>כמו ל\"ך כו'</i> – ראה רש\"י לך לך יב, א.\n<i>לכ\"ם להנאתכם</i> – ראה פסחים כב, סע\"א ושם סח, ב."]]],[300010012,"ז\n\n[<b>דכתבתי</b> <span data-k=\"sm\">במ\"א ששמעתי </span>ממורי<span data-k=\"sm\">]</span> &lt;מבעש\"ט פי' ע\"פ&gt; נשיו הטו לבבו, שאין לך שום תיבה בתורה שאינו סובל ב' משמעות שהוא בחי' דכר ונוק' כו', <span data-k=\"sm\">[יעו\"ש]</span>. א\"כ אין לך שום דבר נברא בעולם שלא יהי' כלול מהכל, והבחירה נתונה לו להטות לאיזה בחינה שירצה, לכך נשיו הטו לבבו.",[["","","----- מקורות ומראה מקומות -----\n<b>בפ</b><b>\"י, בראשית יד, ג (עז, א)</b>\n<i>נשיו הטו לבבו</i> – מ\"א יא, ד.\n----- הערות וציונים -----\nראה לקמן סי' כא. להעיר שבתוי\"י פ' ראה (קעו, סע\"ג) הביא דוגמה לזה."]]],[300010013,"ח\n\n<b>&lt;מבעש\"ט</b> ז\"ל&gt; <span data-k=\"sm\">[בשם </span>מורי<span data-k=\"sm\"> זלה\"ה]</span> יפקוד ה' איש אשר יוציאם ואשר יביאם. כי ראש הדור יוכל להעלות כל הדיבורים והסיפורים של אנשי דורו, לקשר הגשמי ברוחני, כמו הנהו תרי בדחי כו', <span data-k=\"sm\">[ודפח\"ח]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>בפ</b><b>\"י, בראשית טז, א (פב, א)</b>\n<i>יפקוד ה' גו' יביאם</i> – פנחס כז, טז-יז. <i>הנהו תרי בדחי</i> – תענית כב, א.\n----- הערות וציונים -----\nהשוה מש\"כ בדמ\"א ר\"פ ואתחנן בשם הבעש\"ט כשיש צדיק בעולם אזי מייחד כל דברי העולם הגשמיים כו'. ולהעיר ממש\"כ שם פ' בלק ד\"ה כעת יאמר.\n<i>כמו הנהו תרי בדחי</i> – ראה לקמן סי' לז, נח, צג-ג, ערב, שעה."]]],[300010014,"ט-א\n\n<b>מי</b> שהוא חכם לב יקח מצות &lt;פירש&gt; <span data-k=\"sm\">[ויראה בכל אחד מתרי\"ג מצות]</span> לקשר מעשי המצוה שעושה, שנק' מצוה תתאה, לייחדה אל מצוה עליונה, שהיא המחשבה והכוונה של המצוה. וזהו &lt;שאומרים על מצוה א'&gt; אשר קדשנו במצותיו. . .",[["","","----- מקורות ומראה מקומות -----\n<b>בפ</b><b>\"י, בראשית טז, סע</b><b>\"ב (פג, א)</b>\n<i>חכם לב גו'</i> – משלי י, ח.\n----- הערות וציונים -----\n<i>וזהו </i>. .<i> אשר קדשנו כו'</i> – להעיר מפע\"ח שער הברכות ספ\"ג, הובא ומבואר באורך בבפ\"י טו, ד."]]],[300010015,"ט-ב\n\n<b>&lt;ומהבעש\"ט&gt;</b> ע\"פ <span data-k=\"sm\">[סוד וע\"פ ששמעתי </span>ממורי<span data-k=\"sm\"> פסוק]</span> ויהי ערב ויהי בוקר יום אחד<i>[ftnref_1_ג]</i> &lt;וכו'&gt;.\n<b>&lt;הענין&gt;</b> <span data-k=\"sm\">[והעולה ממה שכתבתי, דכתב היעב\"ץ]</span> כי אהרן ע\"י שקר שאמר &lt;כמה חבירך מתחרט ושלחני אצלך כו', כמ\"ש במדרש, עי\"ז&gt; עשה שלום, כי רופא מומחה ע\"י סמים הממיתים רשאי להשתמש בהם כדי להחיות הנפשות <span data-k=\"sm\">[וכו']</span>.\n<b>&lt;וזהו&gt;</b> בש\"ס דחולין האמנם אלם צדק תדברון, יכול יגיס דעתו שהוא בניחותא ע\"ש.",[["","","----- מקורות ומראה מקומות -----\n<i>ע\"פ</i> . . <i>אחד</i>: <b>בפ</b><b>\"י, בראשית טז, רע</b><b>\"ג (פג, ג). </b><i>והעולה</i> . . <i>הנפשות וכו'</i>: <b>שם שלהי ע</b><b>\"ג (פד, א). </b><i>ש\"ס דחולין כו'</i>: <b>שם (לפני \"והעולה\")</b>\n<i>ויהי ערב גו'</i> – בראשית א, ה. <i>דכתב היעב\"ץ</i> – פי' למס' אבות פ\"א מי\"ב. <i>כי אהרן כו'</i> – אבדר\"נ יב, ג. <i>ש\"ס דחולין</i> – חולין פט, א. <i>האמנם גו'</i> – תהלים נח, ב.\n----- שולי הגליון -----\n[ftn_1_ג]) <i>זוהי הכותרת לפן ב' שם, וה</i>\"וכו'\"<i> קאי על ההמשך שם</i>.\n----- הערות וציונים -----\n<i>והעולה ממה שכתבתי כו'</i> – להעיר מצ\"פ פ' ויקהל קיח, רע\"א: כי צריך הצדיק להתלבש לפעמים במדת הרשעים לש\"ש, כמש\"כ במ\"א בשם מורי ומה בין תלמידיו של בלעם הרשע לתלמידיו של אברהם אבינו וכו' יעו\"ש (ראה לקמן סי' סג וסי' סח); ובמ\"א ביארתי זאת אומרת בני החי ובנך המת וכו' העולה משם שצריך הצדיק להתלבש במדת שקר וכזב כדי לעשות שלום כמו אהרן וכיו\"ב כמו כעס וריתחא דרבנן, ואז נעשה היצה\"ר והרשע עי\"ז כסא ויד אל הקדושה כמש\"כ לעיל בשם מורי ביאור משנה ד' מדות בנותני צדקה וכו' (ראה לקמן סי' קפח) וכו'."]]],[300010016,"י\n\n<b>הקב\"ה</b> נקרא איש, שהוא איש מלחמה, וישראל נקראין אשה. וז\"ש האשה נקנית לבעלה, שיהיו נקראין אשתו כביכול, בג' דרכים, א' בכסף, בחי' חסד, ימי החסד שהקב\"ה מסייעו בחסדו הגדול בתחלה ואז כוסף וחושק ומתלהב בתורתו ועבודתו ית', וזה נק' גדלות ראשון. ואח\"כ נסתלק זה, ונק' ימי הקטנות, וגם שאינו כוסף וחושק, מ\"מ על צד ההכרח צריך לדבק <span data-k=\"sm\">[את]</span> עצמו בשטר שהם אותיות הכתובים בספר שנק' שטר, בין באותיות התורה בלימודו, ובין בתפלה, כאשר קבלתי <i>ממורי</i> &lt;הבעש\"ט&gt; זלה\"ה זה שיש סגולה כו', עד שיחזור אח\"כ להתענג בו <span data-k=\"sm\">[ית']</span> ע\"י שבאו המוחין בתורה ותפלה שנק' בביאה, שהוא זווג ב' הנ\"ל.",[["","","----- מקורות ומראה מקומות -----\n<b>בפ</b><b>\"י, בראשית טז, סע</b><b>\"ד (פו, א)</b>\n<i>הקב\"ה נקרא איש</i> – במ\"ר ט, מה. <i>איש מלחמה</i> – בשלח טו, ג. <i>וישראל נקראין אשה</i> – במ\"ר ט, מה. <i>האשה נקנית כו'</i> – קידושין ב, א.\n----- הערות וציונים -----\n<i>כאשר קבלתי ממורי זלה\"ה זה שיש סגולה וכו'</i> – ראה לקמן סי' צד וסי' קסד, ומכתב הבעש\"ט לבעל תוי\"י אשר הועתק לקמן בסוף ההוספות."]]],[300010017,"יא\n\n[<b>שהתחלת</b> <span data-k=\"sm\">התורה הי' להראות סתירת כת המאמינים בקדמות העולם וכו' כי מוכח שיש בורא עולם שחידש העולם מאין ליש, וכמו שהתחיל]</span> בספר עץ חיים, כשעלה ברצונו הפשוט לברוא העולם וכו'. <span data-k=\"sm\">[יעו\"ש]</span>. וראי' מוכרחת לזה מאדם המחדש בתורה, שחידש יש מאין, ובתחלה לא חידש ועכשיו השכל מוליד ונתחדש דבר יש מאין.\n<b>&lt;מהבעש\"ט</b> ז\"ל&gt; <span data-k=\"sm\">[ושמעתי </span>ממורי<span data-k=\"sm\">]</span> שיש בשכל אדם עשר ספירות, כי אבא ואמא הם המולידים דבר שנתחדש בתורה נקרא אבא ואמא, ובתחלה נק' חסד כשנתחדש הדבר שמתפשט לאין תכלית שהוא בחי' חסד כנודע, ואח\"כ צריך בחי' גבורה, סוד הצמצום, שיוכל לתפוס לאומרו בפני אחרים, והכל ע\"י קו האמצעי וכו', ואח\"כ צריך האמנה כמ\"ש בש\"ס דמכות בא חבקוק והעמידן על אחת וצדיק באמונתו יחי', ובחינת האמנה הם תרי סמכי קשוט נצח והוד, ואח\"כ התענוג שיש לו במה שחידש נק' יסוד שהוא אבר התענוג, ונתגלה ע\"י הדיבור שהוא מלכות <span data-k=\"sm\">[ודפח\"ח]</span>. . .\n[<b>אמנם</b>] באמת כי קודם הי' הקב\"ה בורא עולמות עליונות ע\"י עסקו בתורה ברזין סתימין, ואחר כך בעסקו בתורה בנגלה נבראו עולמות אלו הנגלין.",[["","","----- מקורות ומראה מקומות -----\n<i>שהתחלת</i> . . <i>ודפח\"ח</i>: <b>בפ</b><b>\"י, בראשית יז, א (פז, ב).</b> <i>אמנם כו'</i>: <b>שם יז, ב (פח, א)</b>\n<i>בספר ע\"ח</i> – שער הכללים רפ\"א. <i>שמתפשט כו' חסד</i> – זח\"ב מג, ב. <i>בא חבקוק כו'</i> – מכות כד, א. <i>וצדיק גו'</i> – חבקוק ב, ד. <i>תרי סמכי קשוט נו\"ה</i> – תקו\"ז יז, ב. <i>הדיבור שהוא מלכות</i> – זח\"א קמה, סע\"א. זח\"ג רכח, א. תקו\"ז תס\"ט קה, א.\n----- הערות וציונים -----\n<i>שיש בשכל אדם עשר ספירות כו'</i> – ראה לקמן סי' פח ורנז. ועייג\"כ סי' רלד, תח ותכח.\n<i>ובחינת האמונה הם תרי סמכי קשוט נו\"ה</i> – ראה או\"ת סי' שא, ושם סי' שמא (לקו\"י סי' רל). לקו\"י סי' סד. תניא, אגה\"ק סי' א. ועיין היטב באוה\"א כד רע\"א ד\"ה נו\"ה נק' רגלים ע\"ש כל מי שאין לו אמונה כו', ושם לב, א ד\"ה בחי' דדים כידוע כי האמונה נק' רגלים כו' עיי\"ש."]]],[300010018,"יב\n\n<b>כי</b> ביה ה' צור עולמים . . . עולם הזה נברא בה\"א שנאמר אלה תולדות השמים והארץ בהבראם, ועולם הבא נברא ביו\"ד מפני שצדיקים שבו מועטין. והענין, שמעתי <i>ממורי</i> &lt;הבעש\"ט&gt;, שהראו לו, כשהוליכהו תחת עץ הדעת טוב ורע היו עמו אנשים הרבה מישראל, ואח\"כ שהעבירו אותו תחת עץ החיים היו מועטין, ואח\"כ שהכניסו אותו בג\"ע הפנימי נתמעט עוד, עד שנשארו מעט מזעיר <span data-k=\"sm\">[ודפח\"ח]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>בפ</b><b>\"י, בראשית יז, ג (פח, ב)</b>\n<i>כי בי</i>-<i>ה גו'</i> – ישעי' כו, ד. <i>עוה\"ז כו' עוה\"ב כו'</i> – מנחות כט, ב. <i>אלה תולדות גו'</i> – בראשית ב, ד.\n----- הערות וציונים -----\n<i>כשהוליכוהו תחת עץ הדעת כו'</i> – ראה שבחי הבעש\"ט (הוצאת תלפיות, ת\"א תשכ\"א, ע' נג): שאמר הבעש\"ט . . פעם א' הלכתי לג\"ע והלכו עמי עם רב מישראל, ומה שנתקרבתי יותר לג\"ע נתמעטו האנשים עד שבאתי לעץ החיים נשארו עמי מעט מזעיר."]]],[300010019,"יג\n\n<b>ורוח</b> אלהים מרחפת, &lt;דהיינו רוחו של אדם&gt; <span data-k=\"sm\">[דהיינו נשמת אדם שבקרבו]</span>, שירחף על פני המים, היא התורה, <span data-k=\"sm\">[שיתבודד ויעסוק בתורה להיות מתון ו]</span>אז ויאמר ה' יהי אור, ר\"ל שיאיר ה' עיניו ע\"י אור התורה <span data-k=\"sm\">[אם לעשותו או לאו, וכמו שכתבתי במקום אחר –]</span>",[["","","----- מקורות ומראה מקומות -----\n<b>בפ</b><b>\"י, בראשית יח, ד (צד, א)</b>\n<i>ורוח גו'</i> – בראשית א, ב. <i>רוחו של אדם</i> – בר\"ר ח, א (בהוצ' תיאודור). ילק\"ש בראשית רמז ד. מדרש תהלים קלט, ה. <i>המים היא התורה</i> – ב\"ק יז, א. תענית ז, א. <i>ויאמר ה' גו'</i> – בראשית א, ג. <i>ויהי כחצות גו'</i> – בא יא, ד. <i>שהספק הוא כו'</i> – רש\"י על הפסוק. <i>אם פגע כו'</i> – סוכה נב, ב.\n----- הערות וציונים -----\n<i>שיאיר ה' עיניו כו'</i> – ראה לקמן סי' צו.\n<i>כחצות כו' שהספק כו'</i> – ראה לעיל סי' ו ובהערות שם."]]],[300010020,"(יד)\n\n<b>ויהי</b> כחצות הלילה, שהספק הוא כחצות לכאן ולכאן, אז אני ה' יוצא בתוך מצרים, במיצר שלו, להאיר עיניו <span data-k=\"sm\">[וכו'. וכעין זה שמעתי ביאור אם פגע בך מנוול זה משכהו לבית המדרש וכו']</span>.",[["","","----- מקורות ומראה מקומות -----\nראה מקבילות לעיל סימן יג.\n----- הערות וציונים -----\nראה הערות וציונים לעיל סימן יג."]]],[300010021,"טו\n\n<b>&lt;מהבעש\"ט&gt;</b> ג' חינות הן, חן מקום על יושביו וכו'. &lt;ביאור&gt; <span data-k=\"sm\">[דשמעתי בשם </span>מורי<span data-k=\"sm\"> ביאר]</span> ש\"ס דחולין, קיפל כל א\"י תחתיו, הארץ אשר אתה שוכב עליה לך אתננה, &lt;פי'&gt; שלא יצטרך לנסוע ממקום למקום לברר ניצוצין שלו, כי יבררם במקומו <span data-k=\"sm\">[ודפח\"ח . . . ובזה יובן]</span> ונח מצא חן &lt;כו'&gt; <span data-k=\"sm\">[בעיני ה', שיברר במקומו מקליפות נגה, גימטריא חן, והוא מצד שמצא חן בעיני ה']</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>בפ</b><b>\"י, בראשית יח, סע</b><b>\"ד (צה, א)</b>\n<i>ג' חינות הן</i> – סוטה מז, א. <i>קיפל כו'</i> – חולין צא, ב. <i>הארץ אשר גו'</i> – ויצא כח, יג. <i>ונח מצא חן גו'</i> – בראשית ו, ח.\n----- הערות וציונים -----\nראה לקמן בהוספות סי' יג. בארוכה בס' כתונת פסים פ' בהעלותך (לה, ב ואילך), ובקיצור בצ\"פ פ' תרומה קיא, ריש ע\"ד."]]],[300010022,"טז\n\n<b>&lt;מבעש\"ט</b> ז\"ל&gt; <span data-k=\"sm\">[בשם </span>מורי<span data-k=\"sm\">]</span>, כי מבשרי אחזה <span data-k=\"sm\">[אלוה]</span>, כמו בזווג הגשמי אינו מוליד כ\"א המשמש באבר חי וחשק ושמחה, כך בזווג הרוחני, הוא הדבור בתורה ובתפלה, כשהוא באבר חי, בשמחה ותענוג, אז הוא מוליד כו'.",[["","","----- מקורות ומראה מקומות -----\n<b>בפ</b><b>\"י, נח יט, סע</b><b>\"ד (צט, א)</b>\n<i>מבשרי גו'</i> – איוב יט, כו.\n----- הערות וציונים -----\nבמקורו יש המשך: אם כן זה העוסק בתורה ובעבודת ה' לשם שמים לעשות נח\"ר להש\"י בלי שום תשלום שכר, אז זוכה לטעום מתיקות ועריבות ותענוג בתורה ובעבודת ה' ועי\"ז הוא מוליד ברוחני כמו בזווג כשהוא בתענוג ובשמחה, משא\"כ העוסק בתורה ובעבודת ה' שלא לש\"ש ואין לו נחת ותענוג אינו מוליד. וראה לקמן סי' שסב, ובהערות שם."]]],[300010023,"יז\n\n<b>משנה</b> <span data-k=\"sm\">[דקידושין]</span> כל העושה מצוה א' מטיבין לו. <span data-k=\"sm\">[וכו', וביאר משנה פרק ז' דשבת אבות מלאכות ארבעים חסר אחת וכו' דהוי ליה למימר ל\"ט. דכתב בחסד לאברהם נהר מד וז\"ל התפלה שהיא עבודה שבלב היא בב' מיני אדם, א' הוא סוד המשכת השפע למלכות וקישוטיה, ולפי מעלת שורש נשמתו משם מתעורר השפע להחיות בספירות על ידו ע\"י צינור נשמתו וכו', ותדבק השכינה בו, כי הוא צינור במקום צדיק יסוד עולם וכו']</span> ועיקר הכונה שצריך המכוון להמשיך הרוחניות ממדריגות עליונות אל האותיות <span data-k=\"sm\">[שהוא מזכיר]</span> כדי שיוכלו האותיות לעלות עד המדריגה עליונה לעשות שאלתו <span data-k=\"sm\">[וכו']</span> עוד ראוי לכוין בדבריו ובשמות וכנויים לעצם הספירות ואל הרוחניות הפנימי הנעשה לבוש אל עצמות המתפשט מאור א\"ס המיוחד בתכלית היחוד <span data-k=\"sm\">[וכו' יעו\"ש]</span>.\n<b>אם</b> כן צריך האדם להתבונן בעוסקו בתורה ותפלה שאותיות התורה והתפלה הם כלים כמו הגוף, וצריך להמשיך בתוכה הרוחניות, ובתוכו אור הא\"ס שהוא אחדות האמיתי כמו הנשמה <span data-k=\"sm\">[המחיה]</span> לגוף. ופשיטא במעשה המצות שהוא גשמי וכלי שצריך להמשיך בו הרוחניות ואחדות א\"ס.\n<b>וז\"ש</b> כל העושה מצוה אחת, דייקא, מטיבין לו, משא\"כ ל\"ט מלאכות, שהם כנגד הקליפות לברר משם ניצוץ הקדושה, והקליפות הם חסר אחת, כי מעולם הפירוד המה, והבן.\n<b>אמנם</b> יש עוד כלל א' גדול, שצריך לדבק עצמו, דהיינו פנימי' התורה והמצוה, לקשר מחשבתו ונשמתו אל שורש התורה והמצוה אשר הוא עושה, דאם לא כן עושה ח\"ו קצוץ ופירוד בנטיעות, וכאשר &lt;שמעתי&gt; <span data-k=\"sm\">[קבלתי]</span> <i>ממורי</i> &lt;הריב\"ש&gt;.\n<b>וכן</b> <span data-k=\"sm\">[מצאתי]</span> בחסד לאברהם <span data-k=\"sm\">[נהר י\"ד וזה לשונו]</span>, כי הנשמה היא מעצם הבינה והתורה הוא מה שנשפע מהבינה ולמטה בת\"ת כו', וכאשר מקשר ומייחד נשמתו במקורה במקום התורה, ישיג משם דברים סתומים ונעלמים <span data-k=\"sm\">[וכו' יעו\"ש]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>בפ</b><b>\"י, נח כא, א (קה, ב)</b>\n<i>כל העושה כו'</i> – קידושין לט, ב. <i>אבות מלאכות כו'</i> – שבת עג, א. <i>דכתב בחסד לאברהם</i> – מעיין ב נהר מד.<i> מצאתי בחסד לאברהם</i> – מעיין ב נהר יד.\n----- הערות וציונים -----\n<i>כל העושה כו'</i> – כל הענין מבואר בארוכה בהקדמת תוי\"י ב, סע\"ד.\n<i>שאותיות כו' הם כלים כמו הגוף</i> – ראה זח\"א טו, ב. תקו\"ז יב, ב. זו\"ח שה\"ש עג, ג. ועיין בהקדמת תוי\"י קרוב לסופה (ו, סע\"א): וכמו שיש באדם חומר וצורה כך יש באותיות התורה חומר וצורה כי גוף האותיות הוא החומר ורוחניות הספירות עם אוא\"ס שבתוכו המחי' הוא הצורה ונשמה אל האותיות, ואל זה יכוין האדם בתורתו ותפלתו, וכמ\"ש בחסד לאברהם נהר מ\"ג (צ\"ל: מעין ב' נהר מד) מפורש, וז\"ל עיקר הכונה (כבפנים בתחילת סימן זה עד \"לעשות שאלתו\").\n<i>ל\"ט מלאכות שהן כנגד הקליפות</i> – להעיר מתקו\"ז יב, א וזח\"ג קצד, א.\n<i>שצריך לדבק עצמו כו'</i> – ראה לקמן סי' רצא. ורג\"כ סי' מד, צד, צו-א ורפד-ב."]]],[300010024,"יח\n\n<b>&lt;מהבעש\"ט&gt;</b> <span data-k=\"sm\">[שמעתי בשם </span>מורי<span data-k=\"sm\"> ש]</span> צריך להתפלל על שונאיו שהם רוחו של צדיק בגלגול כו', וע\"י התפלה נמתק בשרשו ומוציא מהם רוחו והנשאר בהם כלה מאליו <span data-k=\"sm\">[וכו' ודפח\"ח]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>בפ</b><b>\"י, נח כג, ב (קיח, ב)</b>\n----- הערות וציונים -----\nראה לקמן סי' עה, ועיין במאור עינים פ' ויצא ד\"ה הבעש\"ט נבג\"מ פי' הש\"ס דגיטין [ז, א].\n<i>שצריך להתפלל על שונאיו</i> – ראה ברכות י, רע\"א (והובא שם בבפ\"י). וראה תענית כג, ב וסנהדרין לז, א. ועיין מדה\"נ זח\"א קה, א."]]],[300010025,"יט\n\n<b>מה</b> שאומרים לשם יחוד קב\"ה ושכינתיה, הכוונה להביא התפארת למלכות, שיתפאר הקב\"ה עם המלכות, דהיינו המדריגה התחתונה עולם הדבור, שזאת המדריגה מחיה את כל העולמות כמ\"ש בדבר ה' שמים נעשו, ונאמר ואתה מחיה את כולם, והדיבור של הקב\"ה הוא תמיד מחיה את כל העולמות, וכשאדם עושה מצוה, הקב\"ה מתפאר במלכות, דהיינו בדיבור שלו שהוא בתוך העולמות, ואז מביא האדם המלכות אל הקב\"ה, דהיינו שהקב\"ה מתפאר עם עולם הדיבור.\n<b>וזהו</b> יחוד קב\"ה ושכינתיה, שיתפאר הקב\"ה במלכות שהיא בתוך העולמות, ויתגלה מלכותו, דהיינו שיכירו הכל שהוא מלך בעולמות, וזהו תענוג גדול להקב\"ה. ומדת המלכות היא מצדינו ובידינו, דהיינו שאנו מכירים גדולתו ומלכותו, ואז הוא נשלם במדת מלכותו, כי אין מלך בלא עם, שמחמת העם נתגלה המלכות, ויש להקב\"ה תענוג גדול מזה.",[["","","----- מקורות ומראה מקומות -----\n<b>לקו</b><b>\"י ד, ד (סי' סה)</b>\n<i>שאומרים לשם כו'</i> – פע\"ח שער הזמירות ספ\"ה. ועוד. <i>המלכות </i>. .<i> עולם הדיבור</i> – זח\"א קמה, סע\"א. זח\"ג רכח, א. תקו\"ז תס\"ט קה, א. <i>בדבר ה' גו'</i> – תהלים לג, ו. <i>ואתה מחיה גו'</i> – נחמיה ט, ו.<i> אין מלך בלא עם</i> – בחיי וישב לח, ל. כד הקמח ע' רה, ב ד\"ה ועוד במצוה זו. וראה פדר\"א פ\"ג.\n----- הערות וציונים -----\n<i>לשם יחוד כו'</i> – להעיר מזח\"ג פג, א.\n<i>ואתה מחיה גו'</i> – ראה זח\"ב קד, א ושם רכא, א דאת\"ה הוא מלכות. וראה זח\"א טו, ב.\n<i>והדיבור של הקב\"ה תמיד מחי' כו'</i> – ראה לקמן בהוספות סי' עז.\n<i>שיתפאר הקב\"ה עם המלכות כו'</i> – להעיר מצוה\"ר סי' קכג."]]],[300010026,"כ\n\n<b>&lt;מהבעש\"ט&gt;</b> ופרעה הקריב <span data-k=\"sm\">[וכו', דשמעת </span>ממורי<span data-k=\"sm\">]</span> &lt;כי&gt; בצר הרחבת לי, כי ע\"י שיש מצירין מתקרב יותר להש\"י, וזהו הרחבת לי, שיודע שזה חסר בשכינה ומתפלל בעד השכינה אליו ית' ונעשה יחוד קבה&lt;\"ו&gt; <span data-k=\"sm\">[על ידו]</span>, כי צדיקייא אינון שלוחי דמטרוניתא <span data-k=\"sm\">[וכו' ודפח\"ח]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>בפ</b><b>\"י, נח כג, ב (קיט, ב)</b>\n<i>ופרעה הקריב</i> – בשלח יד, י. <i>בצר הרחבת לי</i> – תהלים ד, ב. <i>צדיקייא אינון כו'</i> – זח\"א רמב, א.\n----- הערות וציונים -----\nראה לקמן סי' סא.\n<i>ופרעה הקריב</i> – מביא פסוק זה ע\"פ מחז\"ל (שמ\"ר כא, ה. זח\"ב מז, א) שהקריב את ישראל לתשובה. ראה לקמן סי' קו, קט, רפח ושצו.\n<i>שיודע שזה חסר בשכינה ומתפלל כו'</i> – ראה לקמן סי' סא, פ, פא, קכו, קעו, קפב, רסח, עדר, רפב, רצ, רצו ושצה. ועיין צוה\"ר סי' עג ובהערות שם וש\"נ. וראה תקו\"ז ת\"ו כב, א. ולהעיר מסנהדרין מו, א ותנחומא פ' אחרי יב. שמ\"ר ל, יג. ויק\"ר ט, ג (וש\"נ במהדורת מרגליות). מדרש תהלים ט, יב (וש\"נ בהערות המו\"ל). וראה לקמן בהערות לסי' קכו."]]],[300010027,"כא\n\n[<b>והנה</b> <span data-k=\"sm\">יש בתוך התיבה בחיות שנים זכר ונקבה, דכתבתי במ\"א בשם </span>מורי<span data-k=\"sm\"> זלה\"ה ביאור פסוק לעת זקנותו של שלמה המלך ע\"ה נשיו הטו את לבבו, כי בכל תיבה יש ב' פירושים, א' רחמים בחינת זכר, ב' בחינת דין הנקרא נקבה, וזה שנאמר נשיו הטו את לבבו וכו' ודפח\"ח. ובזה יובן כי בתוך התיבה]</span> שנים שנים איש ואשתו &lt;באו אל התיבה, כי יש&gt; ב' פירושים בכל תיבה, א' בחי' זכר, רחמים, ב' בחי' &lt;נקבה&gt; דין, וצדיקים מהפכים מדה\"ד ל&lt;מידת&gt; רחמים <span data-k=\"sm\">[והבן]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>בפ</b><b>\"י, נח כג, ד (קכב, א)</b>\n<i>לעת זקנת שלמה נשיו גו'</i> – מ\"א יא, ד. <i>שנים שנים גו'</i> – נח ז, ט. <i>זכר רחמים נקבה דין</i> – זח\"ג יד, א. <i>וצדיקים מהפכים כו'</i> – בר\"ר לג, ג.\n----- הערות וציונים -----\n<i>ביאור פסוק לעת זקנותו כו' –</i> ראה לעיל סי' ז.\n<i>וצדיקים מהפכים מדה\"ד כו' – </i>ראה לקמן סי' פז-א<i>-ד</i>"]]],[300010028,"כב\n\n<b>&lt;מהבעש\"ט&gt;</b> <span data-k=\"sm\">[דשמעתי בשם </span>מורי<span data-k=\"sm\"> זלה\"ה]</span> דרש באכסניא של תורה כו', דאי' במס' אבות הלומד מחבירו פרק א' או הלכה אחת או אות אחת כו' שמצינו בדוד המלך <span data-k=\"sm\">[ישראל]</span> &lt;ע\"ה&gt; שלא למד מאחיתופל אלא ב' דברים בלבד כו' ק\"ו הלומד מחבירו פרק א' עאכ\"ו שצריך לנהוג בו כבוד. וקשה מאי קאמר ב' דברים בלבד. ועוד קשה, הל\"ל דיו לבא מן הדין להיות כנדון. ופירש, דכשאדם לומד מרב הגון, התורה היא פרה ורבה אצלו כנודע <span data-k=\"sm\">[וכו']</span>, וכשלומד מרשע אזי אינו פרה ורבה אלא &lt;נשאר&gt; כפשוטו כמו שלמד ממנו. ולזה אמר מה דוד שלמד מאחיתופל <span data-k=\"sm\">[אלא]</span> ב' דברים בלבד, דהי' רשע, ולא &lt;הי'&gt; פרה ורבה רק נשאר ב' דברים לבד כמו שלמד ממנו, &lt;ואפילו הכי&gt; קראו רבו, הלומד מחבירו, דהיינו שניהם צדיקים, דאז התורה פרה ורבה, עאכ\"ו שצריך לנהוג בו כבוד. ובזה מתורץ שפתחו באכסניא של תורה, שהיו כולם צדיקים.",[["","","----- מקורות ומראה מקומות -----\n<b>בפ</b><b>\"י, נח כג, ד (קכב, א)</b>\n<i>דרש באכסניא כו'</i> – ברכות סג, ב. <i>הלומד מחבירו כו'</i> – אבות פ\"ו מ\"ג.<i> דיו לבא כו'</i> – פסחים יח, ב. <i>התורה היא פרה ורבה</i> – על פי חגיגה ג, ב.\n----- הערות וציונים -----\n<i>דכשאדם לומד מרב הגון כו'</i> – ראה לקמן סי' כח-ב. ועיין קו\"א בסו\"ס תוי\"י (רא, ב): והפרש בין הלומד מרבו רשע הוא רק ב' דברים שלא עשתה פירות ונשארו רק בפירוד ב' דברים כו' עפ\"י חקירה משא\"כ אם רבו צדיק עושה פירות שפרה ורבה וכו' וז\"ש מה דוד וכו' הלומד מחבירו שהוא צדיק כמותו על אחת כו\"כ כו' והעולה מדבריו שנתחבר אות של כל א' וכו' ודפח\"ח. וראה לקמן סי' כג."]]],[300010029,"כג\n\n<b>עוד</b> <span data-k=\"sm\">[שמעתי </span>בשמו<span data-k=\"sm\"> קצת]</span> בענין אחר, כי עשרת הדברות כולל כל התורה, כמו שביאר רב<span data-k=\"sm\">[ינו]</span> סעדי' גאון <span data-k=\"sm\">[וכו' יעו\"ש]</span>, וכמו שנכלל כל התורה בי' דברות כך נכלל כל התורה <span data-k=\"sm\">[כולה]</span> בתיבה אחת כו'. וכ\"ז אם נשמת הרב שלומד ממנו שרשו מן עולם האחדות, משא\"כ אם נשמתו מעולם הפירוד גם התלמיד הלומד ממנו מקבל ממנו ג\"כ דברים נפרדים. וז\"ש שלא למד מאחיתופל אלא שני דברים בלבד כו' <span data-k=\"sm\">[ודפח\"ח]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>בפ</b><b>\"י, נח כג, ד (קכב, ב)</b>\n<i>עשרת הדברות כולל כו'</i> – תנחומא קרח יב. במ\"ר יג, טז. זח\"ב צ, ב. שם צג, סע\"ב. שם קנו, ב. <i>כמו שביאר רס\"ג</i> – ס' אזהרות לרס\"ג (בהוספות בסוף סה\"מ לרס\"ג עם פי' הרי\"פ פערלא, ירושלים תשל\"ג, ח\"ג ע' קעא). הובא ברש\"י למשפטים כד, יב. <i>שלא למד מאחיתפל כו'</i> – אבות פ\"ו מ\"ג.\n----- הערות וציונים -----\nראה לקמן סי' מה.\n<i>אם נשמת הרב כו'</i> – עיין לעיל סי' כב ובהערה שם."]]],[300010030,"כד\n\n<b>&lt;מהבעש\"ט&gt;</b> <span data-k=\"sm\">[דשמעתי </span>ממורי<span data-k=\"sm\"> זלה\"ה]</span> בשם רב<span data-k=\"sm\">[ינו]</span> סעדי' גאון כי עיקר בריאת האדם בעולם הזה לשבר מדות רעות &lt;הטבעיות שלו&gt; <span data-k=\"sm\">[שלו, טבעית]</span>, ובזה מעלה <span data-k=\"sm\">[וכו'.]</span> &lt;מדריגה הנק' טבעך, בעולם העליון שנק' עולם לשון העלם ונסתר&gt;.<i>[ftnref_1_ד]</i>\n<b>וזה</b> שנאמר &lt;לך לך מארצך&gt; וממולדתך, דהיינו הטבעי שנולדה עמו, יראה לשבר אותה כנ\"ל. ומבית אביך, כי אביך נק' חכמה, אבא, ובית אביך הוא בינה, עולם המחשבה, והכוונה שיראה לתקן המחשבות הרעות <span data-k=\"sm\">[ע\"ד שביאר </span>מורי<span data-k=\"sm\"> זלה\"ה וכתבתי מזה במ\"א]</span>, וזה שנאמר ומבית אביך, שידע לברר מה שנפלו המחשבות מן בית אביך, שיחזור להעלותן, ועי\"ז תזכה אל הארץ העליונה אשר אראך, &lt;שאודיע טבעך בעולם&gt;.",[["","","----- מקורות ומראה מקומות -----\n<b>בפ</b><b>\"י, לך לך כז, ב (קלה, ב) [בהוספת כמה מילים מהעמוד לפני זה]</b>\n<i>טבעך בעולם</i> – ע\"פ תנחומא לך ג (הובא ברש\"י לך יב, א). <i>עולם לשון העלם</i> – ס' הבהיר סי' יו\"ד.<i> לך לך גו'</i> – לך יב, א. <i>אביך נק' חכמה אבא</i> – זח\"ג רצ, א. <i>ובית אביך הוא בינה</i> – זח\"א נ, ב. תקזו\"ח קטז, ד. <i>בינה עולם המחשבה</i> – זח\"א רמו, ב. זח\"ג רכט, סע\"ב. זו\"ח יתרו לד, ב.\n----- שולי הגליון -----\n[ftn_1_ד]) <i>הכניס מילים אלו מסוף דרוש הקודם (סוף פן ב') ובשנויים</i>.<i> הלשון במקורו שם</i>: ועוד שאודיע טבעך בעולם, ור\"ל ועוד מעלה נוספת . . . שאודיע טבעך בעולם, ור\"ל לדבק ולהעלות מדריגה תחתונה שלך הנקרא טבעך בעולם העליון שנקרא עולם לשון העלם ונסתר, וז\"ש שאודיע, לשון דביקות, מדריגה תחתונה בעליונה וק\"ל.\n----- הערות וציונים -----\n<i>דשמעתי ממורי זלה\"ה בשם רס\"ג כו'</i> – הובא בהרחבת הביאור בבפ\"י פ' ויחי פה, ב (תב, ב) – אחרי המובא לקמן בסי' סד, עיי\"ש. וראה לקמן סי' שנו."]]],[300010031,"כה\n\n<b>&lt;מהבעש\"ט&gt;</b> כאשר יודע האדם נגעי לבבו שהוא חולי הנפש בסוד הקטנות, אחר שיש לו דעת זה אז ממתיק ע\"י הדעת זה, <span data-k=\"sm\">[כמו שביאר </span>מורי<span data-k=\"sm\">,</span><span data-k=\"sm\"> . . </span><span data-k=\"sm\">.]</span> וזה רפואתו. משא\"כ כשהוא בסוד ההסתר, <span data-k=\"sm\">[כמו שביאר </span>מורי<span data-k=\"sm\">]</span> &lt;ע\"פ&gt; ואנכי הסתר אסתיר <span data-k=\"sm\">[וכו']</span>, שאינו יודע שהוא חולי ברוחני, אז אין לו רפואה למכתו האנושה.",[["","","----- מקורות ומראה מקומות -----\n<b>בפ</b><b>\"י, לך לך כח, ג (קמב, ב)</b>\n<i>ואנכי הסתר גו'</i> – וילך לא, יח. <i>למכתו האנושה</i> – ע\"פ ירמיה טו, יח.\n----- הערות וציונים -----\nראה לקמן סי' פה, קפד, ובהוספות סי' מב. וראה עוד לקמן סי' קלט ורעא."]]],[300010032,"כו\n\n<b>&lt;מהבעש\"ט</b> ז\"ל&gt; <span data-k=\"sm\">[דשמעתי </span>ממורי<span data-k=\"sm\"> זלה\"ה]</span> מאחר שהשכינה כוללת כל העולמות דצח\"מ וכל הנבראים טובים ורעים, והיחוד האמיתי היא השכינה, ואיך כוללת ב' הפכים בנושא אחד, טוב ורע שהם ב' הפכים, והיא היחוד. אבל באמת אתי שפיר, כי הרע הוא כסא להטוב, כמו ופרעה הקריב כו'. או ע\"י שרואה מעשי הרשעים יש לו הנאה שהוא צדיק ויש לו הנאה ותענוג <span data-k=\"sm\">[ונעשה זה בכל העולמות התענוג]</span> ע\"י הרע, וכמעט שעי\"ז יש לרע ג\"כ עליה, רק כשעולה משם יתפרדו כל פועלי און. וכן מחשבה רעה הוא כסא ע\"ד הנ\"ל וכו' <span data-k=\"sm\">[ודפח\"ח]</span>.\n<b>&lt;וכן</b> אמר&gt; <span data-k=\"sm\">[וכיוצא בזה שמעתי </span>ממנו<span data-k=\"sm\">]</span> שניצוץ נשמה מן אצילות יורד בעשיה לפעמים ורואה איך מקילין בכבוד המלך מלכו של עולם, ומצטער על כבוד המלך שהם מקילין בו, ואח\"כ יש לו תענוג שאינו מהם <span data-k=\"sm\">[וכו' ודפח\"ח]</span>.\n<b>ובזה</b> יובן ויאמר ה' אל אברם, ר\"ל אל הנשמה שנק' אברם כמ\"ש בזוהר. <span data-k=\"sm\">[לך לך מארצך וממולדתך וגו', ר\"ל]</span> לך לך מארצך, היינו מאצילות לבריאה, וממולדתך, היינו מבריאה ליצירה, ומבית אביך, מיצירה לעשיה, שהיא הארץ אשר אראך. והכוונה אשר אראך, שתראה שם מעשי אנשי עולם העשי' איך מקילין בכבודו ית' &lt;ותוכיחם&gt;.",[["","","----- מקורות ומראה מקומות -----\n<b>בפ</b><b>\"י, לך לך כט, א (קמה, א)</b>\n<i>ופרעה הקריב</i> – בשלח יד, י. <i>יתפרדו גו'</i> – תהלים צב, י.<i> ויאמר ה' אל אברם</i> – לך יב, א. <i>הנשמה שנק' אברם כו'</i> – זח\"א עו, סע\"ב. שם קכב, ב. <i>וילך אברם גו' </i>– לך יב, ד. <i>ויהי רעב בארץ</i> – לך יב, י. <i>כמו שאיתא בזוהר</i> – ראה זח\"א פ, א. <i>וירד אברם מצרימה</i> – לך יב, י. <i>ויעל אברם גו' הנגבה</i> – לך יג, א. <i>ולוט הוא היצה\"ר</i> – זח\"א עט, א. שם פ, א. <i>ואברם כבד גו'</i> – לך יג, ב. <i>שהוציא ניצוצי קדושה</i> – לקו\"ת וס' הליקוטים להאריז\"ל פ' לך לך. <i>וילקט יוסף גו'</i> – ויגש מז, יד.\n----- הערות וציונים -----\n<i>מאחר </i>. .<i> ע\"ד הנ\"ל ודפח\"ח</i> – ראה לקמן סי' ע.\n<i>שהשכינה כוללת כל העולמות כו'</i> – ראה זח\"ג רלט, א. תקוזו\"ח קב, סע\"ד ושם קיא, ב.\n<i>טובים ורעים</i> – ראה דמ\"א פ' כי תצא רד\"ה כי יקרא: ששמעתי מאא\"ז זללה\"ה שהשכינה היא מעילא לתתא עד סוף כל המדריגות, וזהו סוד ואתה מחיה את כולם, שאפילו כשאדם עושה עבירה ח\"ו אזי ג\"כ השכינה מתלבשת בו, כי בלא היא לא היה בו כח לעשות זאת ולהניע בשום אבר כי היא המחי' אותו ונתנה בו כח וחיות, וזהו כביכול גלות השכינה וכו' עיי\"ש.\n<i>הרע הוא כסא להטוב כמו ופרעה הקריב</i> – ראה לעיל סי' כ, ולקמן סי' ע, קו, קפח (עיי\"ש בהערות), רפח, שצו.\n<i>כענין וילקט יוסף כו'</i> – ראה מדל\"י סס\"י קב (קיא). וראה אוה\"ח לזח\"א קצו, סע\"א."]]],[300010033,"(כז)\n\n[<b>וילך</b> <span data-k=\"sm\">אברם כאשר דיבר אליו ה' וגו']</span> ויהי רעב בארץ, ראה שהם חסירי מהימנותא כמו שאיתא בזוהר, דהיינו שמקילין בכבודו ית', ולכך וירד אברם מצרימה, שהי' מיצר על כבודו ית' שמקילין בו עולם העשיה. אמנם עי\"ז ויעל אברם ממצרים, להתענג יותר בעבודת הש\"י, כי יש יתרון האור מן החשך על שאינו כאחד מהם. ולכך ולוט, הוא היצר הרע, עמו הנגבה, שע\"י הרע מתענג יותר בעבודת הש\"י ונעשה כסא ונכנע שמאל בימין.\n<b>ואברם</b> כבד מאד במקנה בכסף ובזהב . . . &lt;פי' שהוציא ניצוצי קדושה, כענין וילקט יוסף את כל הכסף&gt;.",[["","","----- מקורות ומראה מקומות -----\nראה מקבילות לעיל סימן כו.\n----- הערות וציונים -----\nראה הערות וציונים לעיל סימן כו."]]],[300010034,"כח-א\n\n<b>נודע</b> מ\"ש בס' עץ חיים <span data-k=\"sm\">[שער כ\"ב . . .]</span> ענין מצות המילה וחשמ\"ל <span data-k=\"sm\">[וכו' ובספר פע\"ח יעו\"ש]</span>. ונ\"ל להלביש הדברים, &lt;שזה&gt; <span data-k=\"sm\">[שמצות מילה]</span> שייך בין בתורה בין בתפלה בין בעסק המצות, וז\"ס חשמ\"ל. דקבלתי <i>ממורי</i> &lt;הבעש\"ט&gt; <span data-k=\"sm\">[זלה\"ה]</span>, סוד הכנעה והבדלה והמתקה שצריך בכל עסק תורה ותפלה <span data-k=\"sm\">[וכתבתי מזה במקום אחר בקיצור נמרץ כי לא ניתן רשות להרחיב בזה כי הוא מובן ממילא ודפח\"ח]</span>. וזה סוד ח\"ש מ\"ל, שצריך לחשות עד שמל וכורת הקליפות, אז ימלל וידבר למתק הדינין בשרשן, שהוא סוד התפלה שביאר <i>מורי</i> בשם רבו, ולכך נקראו מחצדי חקלא <span data-k=\"sm\">[כמבואר במקובלים]</span>, ולכך &lt;צריך&gt; <span data-k=\"sm\">[יזהר]</span> להפריד ממחשבתו מחשבות זרות ועי\"ז גורם להבדיל ולפרוש מהשכינה הקליפות <span data-k=\"sm\">[וכמו שכתב בראשית חכמה דף פא ע\"ב ודף קל יעו\"ש]</span>, ולכך תיבת מל סובל ב' פירושים, א' דיבור ב' כריתה והבדלה, וזה נמשך מזה <span data-k=\"sm\">[כאמור]</span>. וזה סוד ח\"ש מ\"ל, שצריך להכרית הקליפות ואח\"כ מל דיבור בעסק תורה ותפלה שהיא הבדלה והמתקה.",[["","","----- מקורות ומראה מקומות -----\n<b>בפ</b><b>\"י, לך לך כט, ג (קמח, ב)</b>\n<i>בס' עץ חיים</i> – שכ\"ב פ\"ב ושם של\"ג פ\"ג. <i>ובספר פע\"ח</i> – שער התפלה ספ\"ב ופ\"ג.<i> ח\"ש מ\"ל שצריך לחשות </i>. .<i> ימלל</i> – ראה חגיגה יג, ב. <i>למתק הדינין בשרשן</i> – ע\"ח שי\"ג פי\"א. פע\"ח שער השופר פ\"א. <i>מחצדי חקלא כמבואר במקובלים</i> – ראה בהערות וציונים.\n----- הערות וציונים -----\n<i>סוד הכנעה והבדלה והמתקה</i> – ראה לקמן סי' קס ושב-א. ועיין לקמן סי' קפח ובהערות שם.\n<i>סוד התפלה שביאר מורי בשם רבו</i> – ראה לקמן סי' פז-א-פז-ד.\n<i>נק' מחצדי חקלא</i> – \"קריאת שם זה נמצא בזוהר פעמים הרבה\" (לשון ס' שער מאמרי רשב\"י, בריש פירוש האדרא רבא קדישא, קפו, ב), וראה בהערה הסמוכה.\n<i>כמבואר במקובלים</i> – ראה שער מאמרי רשב\"י שם לאד\"ר קכז, ב. לקו\"ת ושער המצות להאריז\"ל, פ' בהר, קרוב לסופו בביאור סוד הקצירה. וראה פירוש הרמ\"ק באוה\"ח לזח\"א קנו, א ושם זח\"ב לז, א וזח\"ג קו, א ועוד. הגהות דרך אמת לזח\"א קנו, א ורטז, א."]]],[300010035,"כח-ב\n\n<b>אם</b> הרב דומה למלאך, <span data-k=\"sm\">[ה' צבאות וכו', ור\"ל שיהיה מלאך, כי]</span> &lt;הם&gt; אותיות כאל\"ם <span data-k=\"sm\">[דומה למלא\"ך]</span> להיות <span data-k=\"sm\">[ח\"ש]</span> מ\"ל, שהוא חש עד שכורת ומל הקליפות ליזהר &lt;מפני החיצונים&gt; <span data-k=\"sm\">[מפניה חיצונית]</span>, אז תורה יבוקש מפיהו, כי אז נכנס בלב השומע ופרה ורבה <span data-k=\"sm\">[בו, כמו ששמעתי </span>ממורי<span data-k=\"sm\"> זלה\"ה מה דוד שלא למד מאחיתופל אלא שתי דברים בלבד וכו']</span>. . .\n<b>ובזה</b> יובן לך לך מארצך <span data-k=\"sm\">[וממולדתך ומבית אביך]</span>, שיתרחק מן ג' בחינות <span data-k=\"sm\">[נגד ג' בחינות]</span> הנ\"ל הכנעה הבדלה והמתקה שביאר <i>מורי</i> זלה\"ה, כי מצד &lt;ארציות ועכירות החומר והקליפות&gt; <span data-k=\"sm\">[ארציות חומר ועכירות הקליפות]</span> נמשך גסות הרוח, לכך הזהירו לך לך מארצך ויבוא להכנעה, וממולדתך שהוא תרח עע\"ז שורש הקליפות ויש כח האב בבן, כמ\"ש הראב\"ד בס' יצירה כי כח הבנאי בבנין <span data-k=\"sm\">[וכו']</span>, ולכך צריך הבדלה להפריש ולהבדיל הקליפות שמצד האב המולידו, ומבית אביך שהי' בחרן כמ\"ש וימת תרח בחרן ודרז\"ל עד אברהם הי' חרון אף של מקום, שהוא דין וגבורה, ואברם בחי' חסד ימתיק הדין בשורש החסד שיש בגבורה והדין ההוא, כמ\"ש במ\"א בשם <i>מורי</i> זלה\"ה איך למתוק הדין בשורשו, ואחר המתקה אז תשיג בחינת הארץ אשר אראך, והבן.",[["","","----- מקורות ומראה מקומות -----\n<b>בפ</b><b>\"י, לך לך כט, ד (קנ, א)</b>\n<i>אם הרב כו'</i> – מו\"ק יז, א. <i>פרה ורבה בו</i> – ראה חגיגה ג, ב. <i>מה דוד כו'</i> – אבות פ\"ו מ\"ג. <i>לך לך גו'</i> – לך יב, א. <i>תרח עע\"ז</i> – בר\"ר לח, יג. <i>כמ\"ש הראב\"ד בס' יצירה</i> – בסוף הקדמתו ד\"ה הנתיב הד'. <i>וימת תרח גו'</i> – נח יא, לב. <i>ודרז\"ל כו'</i> – פרש\"י שם. <i>ואברם בחי' חסד</i> – זח\"ג שב, א. ועוד.\n----- הערות וציונים -----\n<i>אם הרב דומה כו'</i> – ראה לעיל סי' כב ובהערות שם.\n<i>הכנעה הבדלה כו'</i> – ראה לעיל סי' כח-א.\n<i>מצד כו' נמשך גסות הרוח</i> – להעיר מתקו\"ז תכ\"ד סט, ב.\n<i>תרח עע\"ז</i> – ראה מדרש אגדה נח יא, כח ומקורו בזח\"א קיג, ריש ע\"ב.\n<i>בחרן כו' ודרז\"ל</i> כו' – להעיר מזח\"א קמז, א. שם בס\"ת עח, ב.\n<i>איך למתוק הדין כו'</i> – ראה לקמן סי' לג וסי' פז-א-פז-ד."]]],[300010036,"כט\n\n<b>&lt;מהבעש\"ט&gt;,</b> <span data-k=\"sm\">[דשמעתי בשם </span>מורי<span data-k=\"sm\">]</span> אתה הוא ה' &lt;אלהינו&gt;, &lt;פי'&gt; כשסובר האדם שהוא נוכח ה', תואר אתה, אז הוא רחוק מהשם, תואר הוא נסתר, משא\"כ כשסובר שהוא נסתר ורחוק מהשם, תואר הוא, אז הוא קרוב ונוכח ה', תואר <span data-k=\"sm\">[אתה]</span> &lt;ה' אלקינו&gt;. <span data-k=\"sm\">[ודפח\"ח]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>בפ</b><b>\"י, וירא לא, רע</b><b>\"א (קנד, ב)</b>\n<i>אתה הוא גו'</i> – ירמיה יד, כב.\n----- הערות וציונים -----\nראה לקמן סי' ל וסי' נה.\nוהנה בבפ\"י כאן יש המשך: וכן שמעתי משל מהרה\"מ מוהר\"ם משל סולם הסובב כשהוא למטה רואה המלך למעלה, וכשעולה למעלה וכו' ודפח\"ח. ולהעיר שעיקר משל זה מהבעש\"ט, כדאיתא באו\"ת להרה\"מ ר\"פ עקב (סי' קנט): ור\"י בע\"ש זלה\"ה אמר משל לזה אחד הולך במסיבה שקורין שווינדל-טרעפ, כשהוא למטה רואה את האור שלמעלה, ואח\"כ כשהולך להלאה והולך בצד אינו רואה. ועיי\"ע לקמן בהוספות סי' נג.\nוראה בדמ\"א פ' דברים ד\"ה ואלה הדברים: דהנה איתא בשם אא\"ז זללה\"ה כל הדר בא\"י דומה כמי שיש לו אלוקי, היינו מי שדומה בעיניו שדר בארץ העליונה שקרוב לקוב\"ה דומה לו כמי שיש לו אלוקי ובאמת אין לו; ומי שדר בחו\"ל, היינו שדומה לו שעדיין לא נכנס בארץ העליונה בזה דומה כמי שאין לו אלוקי אבל באמת יש לו.\n<i>ה' אלקינו</i> – המחבר כתב זה ע\"פ הגירסא בתוי\"י ס\"פ קדשים (צט, ד): ומי שסובר הוא אז אלקינ\"ו."]]],[300010037,"ל\n\n<b>&lt;מהבעש\"ט&gt;</b> <span data-k=\"sm\">[ששמעתי משל בשם </span>מורי<span data-k=\"sm\"> ו]</span> ביאור פסוק הלוך ילך ובכה <span data-k=\"sm\">[נשא משך הזרע בא יבא ברנה]</span>, &lt;פי'&gt; שאם חושב להליכה ובוכה ומצטער על הליכתו מעבודת הש\"י, אז סופו נושא משך הזרע. משא\"כ מי שחושב לעצמו לביאה, וז\"ש בא יבא, ומכח זה הוא ברנה ושמחה, לבסוף נושא אלומותיו בלי זרע <span data-k=\"sm\">[ודפח\"ח]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>בפ</b><b>\"י, וירא לב, ד (קסג, א)</b>\n<i>הלוך ילך גו'</i> – תהלים קכו, ו.\n----- הערות וציונים -----\nראה לעיל סי' כט ובהערות שם. ולהעיר מלקמן סי' נה וסי' קנה, ובהוספות סי' עט. וראה ג\"כ לקו\"י סי' עב (באו\"ת סי' רמב)."]]],[300010038,"לא\n\n<b>ועתה</b> ישראל מה ה' אלהיך שואל <span data-k=\"sm\">[מעמך כי אם ליראה]</span>, &lt;פי' שיהי' עניו ומדריגת מה, ועי\"ז יראה יהי' מלתא זוטרתי כמו למרע\"ה, וז\"ש כ\"א ליראה&gt; <span data-k=\"sm\">[ר\"ל מדת ענוה שהי' במשה שנאמר ונחנו מה, מדה זו הי' שואל מעמך, ואז כשיזכו למדה זו שהיא מדת ענוה, אז יראת ה' זוטרתי היא לגבי ישראל ג\"כ כמו במשה, שנאמר עקב ענוה יראת ה', ושפיר קאמר הפסוק כי אם ליראה והבן]</span>.\n<b>ובזה</b> יובן ופלגשו, דהיינו ענוה פסולה, ושמה ראומה, כלומר ראו מה, וכוונתו ראו שיש בי בחינת מה, שהיא מדת ענוה, &lt;ותלד את טבח, שעל ידי זה היצר הרע טובח אותו&gt;, ע\"ד שביאר <span data-k=\"sm\">[</span>מורי<span data-k=\"sm\"> זלה\"ה]</span> ראובן שמעון לוי יהודה, כמו שיש שמות השבטים בקדושה כן יש בקליפה, והוא, ראובן ראו שאני בן, שמעון שעושה הטוב כדי שיהי' שמעו בכל &lt;העולם&gt; <span data-k=\"sm\">[הארץ]</span>, לוי שיתחבר לאנשי מעשה &lt;כדי יהודה, פי'&gt; כדי שיודו וישבחו אותו <span data-k=\"sm\">[ודפח\"ח]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>בפ</b><b>\"י, וירא לה, סע</b><b>\"ד (קעט, א)</b>\n<i>ועתה ישראל גו'</i> – עקב י, יב. <i>מלתא זוטרתי כו'</i> – ברכות לג, ב. <i>ונחנו מה</i> – בשלח טז, ז. <i>עקב ענוה גו'</i> – משלי כב, ד. <i>ופלגשו ושמה ראומה גו' טבח</i> – וירא כב, כד.\n----- הערות וציונים -----\n<i>ועתה ישראל </i>. .<i> ומדריגת מה</i> – ראה לקמן סי' קע, שיד ושצא.\n<i>ונחנו מה</i> – ראה חולין פט, א.\n<i>ופלגשו כו'</i> – בקיצור לקמן סי' שטו. וראה לקו\"ת לאדה\"ז פ' בהר מג, א וכן שם פ' תזריע כג, ד.\n<i>טבח </i>. .<i> טובח אותו</i> – ראה בר\"ר ס\"פ וירא [והובא שם בבפ\"י לפני דיבור זה, לה, סע\"ג (קעז, ב)].\n<i>ע\"ד שביאר מורי </i>. .<i> כן יש בקליפה כו'</i> – ראה לקמן סי' תג. וראה צוה\"ר סוף סי' קכד, והשוה שם סי' קלט בנוגע לאבות (וראה לקמן סי' רנח). וראה בתוי\"י וישב (כח, ריש ע\"ב) שם הביא דברי הבעש\"ט עד (ועד בכלל) יהודה וכתב \"ע\"כ שמעתי\" (אף שבסי' תג כלל גם יששכר וזבולון) ואח\"כ הוסיף מדילי' לשאר השבטים (ובנוגע ליששכר וזבולון כתב שם באופן אחר מבסי' תג)."]]],[300010039,"לב-א\n\n<b>&lt;מהבעש\"ט&gt;</b> <span data-k=\"sm\">[דשמעתי בשם </span>מורי<span data-k=\"sm\"> זלה\"ה]</span> דמפסוק <span data-k=\"sm\">[זה]</span> ואבא היום אל העין יצא שם של קפיצת הארץ <span data-k=\"sm\">[וכו' ודפח\"ח]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>בפ</b><b>\"י, חיי שרה מא, ד (רד, א)</b>\n<i>ואבא היום גו'</i> – ח\"ש כד, מב.\n----- הערות וציונים -----\nכן הובא בס' עבודת ישראל להמגיד מקאזניץ פ' חיי שרה. ועיין מש\"כ בענין זה בס' אוהב ישראל להרב מאפטא, בהשמטות (ראה ספר בעל שם טוב פ' חיי שרה אות ה ושם הג' ד)."]]],[300010040,"לב-ב\n\n<b>&lt;גם ביאר&gt;</b> <span data-k=\"sm\">[והנה כתבתי במ\"א ביאור]</span> משנה ראוה מדברת עם אחד בשוק <span data-k=\"sm\">[וכו']</span> ע\"פ <span data-k=\"sm\">[ביאור </span>מורי<span data-k=\"sm\"> זלה\"ה ש\"ס]</span> אין דומה שונה פרקו מאה פעמים לשונה פרקו מאה פעמים וא' <span data-k=\"sm\">[וכו'. . .]</span> &lt;פי' עם הא'&gt;. ובזה יובן ראוה מדברת עם א' בשוק, &lt;פי'&gt; כי גם בשוק שעוסק בעסק עוה\"ז מ\"מ דבורו <span data-k=\"sm\">[הוא]</span> עם א' ע\"י יחודים <span data-k=\"sm\">[וכו']</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>שם</b>\n<i>ראוה מדברת כו'</i> – כתובות יג, א. <i>אין דומה כו'</i> – חגיגה ט, ב.\n----- הערות וציונים -----\n<i>ביאור משנה ראוה מדברת כו'</i> – ראה לקמן סי' שעג. ולהעיר מע\"ח שט\"ז ספ\"ד.\n<i>אין דומה כו'</i> – ראה לקמן סי' קנה."]]],[300010041,"לג\n\n<b>&lt;מהבעש\"ט&gt;</b> ביאור ש\"ס לעולם יהא אדם רגיל לומר כל &lt;מה&gt; דעבדין מן שמיא לטב עבדין, וכההוא מעשה דר' עקיבא <span data-k=\"sm\">[וכו']</span>, ובש\"ס דתעני' דנחום אמר גם זו לטובה. ויש להבין שינוי לשון בין זה לזה. וכתבתי ביאור, למתק דינין בשרשן, <span data-k=\"sm\">[שמעתי </span>ממורי<span data-k=\"sm\"> זלה\"ה]</span> ע\"י שימצא בשורש הדין איזה חסד אז נמתק הדין בשורש חסד זה ונעשה הכל חסד. ולכך נחום איש גם זו מצא החסד בשורש הדין ונעשה מיד חסד, משא\"כ בסתם בני אדם שאינו יודע שורש החסד מ\"מ יהי' רגיל לומר כל דעבדין מן שמיא לטב עבדין מן הסתם גם שאינו יודע <span data-k=\"sm\">[וכו']</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>בפ</b><b>\"י, תולדות מב, ד (רט, א)</b>\n<i>לעולם יהא אדם כו'</i> – ברכות ס, סע\"ב. <i>ובש\"ס דתענית כו'</i> – תענית כא, א. <i>למתק דינין בשרשן</i> – ע\"ח שי\"ג פי\"א.\n----- הערות וציונים -----\n<i>למתק הדינין בשרשן שמעתי כו'</i> – ראה לקמן סי' פז-א-פז-ד."]]],[300010042,"לד\n\n<b>בש\"ס</b> דמנחות, אמר ריש לקיש פעמים שבטולה של תורה זהו יסודה, דכתיב אשר שברת, מלמד דא\"ל הקב\"ה יישר כחך ששברת <span data-k=\"sm\">[וכו']</span>. והוא תמוה, איך אפשר שבטולה &lt;של תורה&gt; זהו יסודה. &lt;ופי' הבעש\"ט, כי&gt; <span data-k=\"sm\">[ונראה דכתבתי במ\"א דשמעתי </span>ממורי<span data-k=\"sm\"> זלה\"ה]</span> והחיות רצוא ושוב, לפי שכל דבר מתלהב לשוב לשרשו, ולכך ע\"י אכילה ושתיה ועסק משא ומתן <span data-k=\"sm\">[מעט שמבטל]</span> &lt;מתבטל&gt; האדם מלימוד &lt;תורה&gt; ועבודת ה', אז נחה הנשמה מהתלהבותה &lt;ומתחזקת לשוב לדביקות יותר עליון&gt; <span data-k=\"sm\">[ונתחזקה וכו']</span>. ובזה <span data-k=\"sm\">[יובן]</span> &lt;ארז\"ל&gt; <span data-k=\"sm\">[אמר ריש לקיש]</span> פעמים שבטולה של תורה זה יסודה, בסוד והחיות רצוא ושוב, והבן.",[["","","----- מקורות ומראה מקומות -----\n<b>בפ</b><b>\"י, תולדות מד, א (ריד, א)</b>\n<i>בש\"ס דמנחות כו'</i> – מנחות צט, סע\"א. <i>אשר שברת</i> – כי תשא לד, א. <i>והחיות רצו\"ש</i> – יחזקאל א, יד.\n----- הערות וציונים -----\nראה לקמן סי' קי-ב, קכא וקעח. רג\"כ סי' שסז.\n<i>שכל דבר מתלהב לשוב לשרשו</i> – להעיר מהל' יסוה\"ת פ\"ד ה\"ב."]]],[300010043,"לה\n\n<b>במדרש</b> <span data-k=\"sm\">[פ' וישלח פע\"ח]</span> משל, פעם א' כעס המלך שבחיות על החיות, ויעצו מי ילך לפייס המלך, אמר השועל אני אלך <span data-k=\"sm\">[עמכם לפייס המלך]</span> שיש לי ג' מאות משלים כו', &lt;ובסוף&gt; אמר השועל ששכח הכל וכל אחד יפייס <span data-k=\"sm\">[את]</span> המלך כפי כוחו . . . וכוונתו הי' שיכנעו למלך <span data-k=\"sm\">[וילכו לפייסו . . .]</span> &lt;ועכ\"א תחילה שיודע, כדי שילכו&gt;. <span data-k=\"sm\">[ואז ע\"י הכנעה זו ישתדל כל אחד בעצמו לפייס המלך]</span> והוא הנכון. &lt;שאמר הבעש\"ט&gt; <span data-k=\"sm\">[כאשר שמעתי </span>ממורי<span data-k=\"sm\"> זלה\"ה]</span> משל על בעלי תפלות בימים נוראים, שלא יסמכו עליהם בני עולם רק ישתדל כל א' להתפלל עבור עצמו, אמר משל &lt;זה&gt;, פעם <span data-k=\"sm\">[א' היו שני מלכים נלחמים יחד, ומלך א' היה אדיר ותקיף שהי' לו גבורי חיל מלובשים בשריון וקשקשים וכו' וזה המלך שכנגדו הלך למצא אנשים גבורים כאלו ולא עלתה לו וכו', עד שאמר לחילו שלא יסמכו על הגיבורים וכו' ודפח\"ח]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>בפ</b><b>\"י, תולדות מד, ב (ריד, ב)</b>\n<i>במדרש כו'</i> – בר\"ר עח, ז.\n----- הערות וציונים -----\nראה לקמן סי' קלג ורסא. ובהוספות סי' רטו."]]],[300010044,"לו\n\n<b>&lt;מהבעש\"ט&gt;</b> לעולם יכנס אדם &lt;לבהכ\"נ&gt; שיעור ב' פתחים <span data-k=\"sm\">[ואח\"כ יתפלל וכו']</span>, &lt;פי'&gt; <span data-k=\"sm\">[וביאר]</span> בזוהר שהם מדות היראה ואהבה <span data-k=\"sm\">[והם שיעור שני פתחים, ושמעתי </span>ממורי<span data-k=\"sm\"> זלה\"ה, כמדומה]</span> בשם הרמב\"ן שא\"א שיהי' אלו ב' מדות יחד כ\"א בעבודת הבורא ית'.",[["","","----- מקורות ומראה מקומות -----\n<b>בפ</b><b>\"י, תולדות מה, סע</b><b>\"ג (רכב, א)</b>\n<i>לעולם יכנס כו'</i> – ברכות ח, א. <i>בזוהר</i> – זח\"ג ח, ב.\n----- הערות וציונים -----\nראה לקמן ריש סי' שמט. מבואר במדל\"י סי' ז (ח) – ונשנית שם סי' רג (ריג) – ושם סי' קי (קכב). ולהעיר שכ\"כ בספרי, ואתחנן פיס' לב."]]],[300010045,"לז\n\n<b>&lt;מהבעש\"ט&gt;</b> <span data-k=\"sm\">[ששמעתי </span>ממורי<span data-k=\"sm\">]</span> ענין מלתא דבדיחותא קודם הלימוד, כי החיות רצוא ושוב, והאדם <span data-k=\"sm\">[הוא]</span> בסוד קטנות וגדלות, וע\"י השמחה ומלתא דבדיחותא יוצא מקטנות לגדלות ללמוד ולדבק בו ית' <span data-k=\"sm\">[וכו', ודפח\"ח]</span>. &lt;וז\"ש&gt;. <span data-k=\"sm\">[וכן שמעתי </span>בשמו<span data-k=\"sm\">]</span> והני תרי בדחי שהיו מפקחין צער האדם על ידי מלתא דבדיחותא, ואז יוכלו לקרבו ולהעלותו <span data-k=\"sm\">[וכו', ודפח\"ח]</span>.\n<b>&lt;וז\"ש</b> ויקח את שני נעריו עמו ואת יצחק בנו, כי ע\"י הצחוק לש\"ש יכול להעלות השנים של נערות ג\"כ עמו&gt;. <span data-k=\"sm\">[ובענין זה שמעתי את יצחק והעלהו לעולה, כי ע\"י הצחוק לשם שמים מעלה כל ימי הצחוק של בחרות ג\"כ למעלה והבן. וכן ויקח את שני נעריו עמו, ר\"ל להעלות שנים של נערות ג\"כ עמו, ודפח\"ח]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>בפ</b><b>\"י, תולדות מט, סע</b><b>\"ב (רלח, א)</b>\n<i>מלתא דבדיחותא כו'</i> – שבת ל, ב. <i>החיות רצו\"ש</i> – יחזקאל א, יד. <i>והני תרי בדחי כו'</i> – תענית כב, א. <i>ויקח את שני גו'</i> – וירא כב, ג. <i>את יצחק גו'</i> – וירא כב, ב.\n----- הערות וציונים -----\n<i>האדם הוא בסוד קטנות וגדלות</i> – ראה לעיל סי' י ולקמן סי' עז, צ, קי-ב, קכא, קכג, קלט, קנב-ב, רב (ובהערות שם), ריז, רעט, שנו, שסו, שצד.\n<i>ומילתא דבדיחותא</i> – ראה לקמן סי' עז ושסו.\n<i>והני תרי בדחי</i> – ראה לקמן סי' נח, צג-ג, ערב ושעה."]]],[300010046,"לח-א\n\n<b>&lt;מהבעש\"ט&gt;</b> <span data-k=\"sm\">[ששמעתי </span>ממורי<span data-k=\"sm\">]</span> כי יראה חיצונית הבא לאדם הוא יד ימינו ית' פשוטה שיתעורר האדם מזה ליראה פנימית, וכאשר ידע האדם שזה חסדו ית' לעוררו כו' נעשה מיראה אהבה שמקבלו באהבה ונפטר מיראה חיצונית <span data-k=\"sm\">[אך אם מכון]</span> וכו' <span data-k=\"sm\">[יעו\"ש]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>בפ</b><b>\"י, תולדות מט, ד (רמא, א)</b>\n<i>יד ימינו ית' פשוטה כו'</i> – פדר\"א ר\"פ מג. זח\"א כג, רע\"א. תקו\"ז תמ\"ז פד, סע\"ב.\n----- הערות וציונים -----\nראה לקמן סי' לח-ב, קעז (נשנה בסי' שסה), קפ, רז-א."]]],[300010047,"לח-ב\n\n[<b>שמעתי</b> ממורי<span data-k=\"sm\"> זלה\"ה]</span> כי בחינת היראה הוא מתפשט בכל הנבראים ובכל העולמות, ושורש כולם היא יראה פנימית, יראת הבורא ית', אמנם גם יראה חיצונית הבא על האדם הוא כדי לעורר אותו אל היראה הפנימית, והוא חסד ה' יד ימינו פשוטה, ושואל ומבקש מהאדם שיתעורר מזה אל יראת ה'. וז\"ש מה ה' שואל מעמך כ\"א ליראה את ה', שהוא יראה פנימית <span data-k=\"sm\">[וכו']</span>.\n<b>והנה</b> אם ידע האדם זה החסד ואהבת הבורא ית' עליו בחמלתו ששלח לו יראה חיצונית כדי לעוררו אל יראה פנימית, אז נעשה מיראה אהבה, שמקבל היראה חיצונית באהבה גמורה, ואז נפטר מיראה חיצונית. אך אם כוונתו בזה כדי לפטור מיראה חיצונית לא מהני כלום <span data-k=\"sm\">[וכו']</span>. ובזה ביאר אין לגבי משה &lt;מלתא&gt; זוטרתי היא, כי מיראת ת\"ח הוא בנקל לבא ליראה את ה' <span data-k=\"sm\">[ודפח\"ח]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>בפ</b>\"<b>י</b>,<b> תולדות נ</b>,<b> א (רמב</b>,<b> ב)</b>\n<i>יד ימינו כו'</i> – נסמן לעיל לח-א. <i>מה ה' גו'</i> – עקב י, יב. <i>אין לגבי משה כו'</i> – ברכות לג, ב.\n----- הערות וציונים -----\n<i>בחינת היראה מתפשט כו'</i> – ראה לקמן סי' קפ.\n<i>יראה חיצונית כו'</i> – ראה לעיל לח-א. וש\"נ."]]],[300010048,"לט\n\n<b>&lt;מהבעש\"ט&gt;</b> <span data-k=\"sm\">[דשמעתי בשם </span>מורי<span data-k=\"sm\"> זלה\"ה]</span> ביאור ש\"ס דברכות <span data-k=\"sm\">[דל\"ג ע\"ב]</span> א\"ר זירא כל האומר שמע שמע משתקין אותו, א\"ל ר' פפא לאביי דלמא מעיקרא לא איכוין דעתיה כו', א\"ל חברותא כלפי שמיא מי איכא, אי לא כוון דעתיה מעיקרא מחינן ליה במרזפתא דנפחא עד דמכוין דעתיה. והקשה <span data-k=\"sm\">[זלה\"ה]</span> דאכתי הקושיא במקומה עומדת, מ\"מ דלמא מעיקרא לא איכוין והשתא בא לצאת ידי שמים ולכוין <span data-k=\"sm\">[וכו']</span>. ועוד קשה למה נקט ר\"ז דוקא האומר שמע שמע ב' פעמים <span data-k=\"sm\">[וכו']</span> ולא פסוק אחר בק\"ש או כיוצא.\n<b>וביאר</b> מה הוא ענין קבלת עול מלכות שמים, והענין כי האדם מחויב להאמין כי מלא כל הארץ כבודו ית', לית אתר פנוי מיניה, וכל המחשבות של האדם יש בו מציאותו ית', וכל מחשבה היא קומה שלימה. וכאשר יעלה במחשבתו של אדם בעת עסקו בתפלה איזה מחשבה רעה וזרה, היא באה אל האדם לתקנה ולהעלותה, ואם אינו מאמין בזה אין זה קבלת עול מלכות שמים שלימה, כי מקצר ח\"ו במציאותו ית'.\n<b>ובזה</b> יובן האומר שמע שמע <span data-k=\"sm\">[וכו']</span>, וקשה למה אמר ב' פעמים, וצ\"ל כי מעיקרא לא איכוין דעתיה, דהיינו שהיה לו איזה מ\"ז, אמנם אם ידע ששם ג\"כ הוא מציאות הש\"י לא הי' צריך לומר ב\"פ שמע. וזהו צחות לשון הש\"ס מחינן ליה במרזפתא דנפחא, הכוונה כי המחשבה עצמה היא מכה את האדם כמו במרזפתא <span data-k=\"sm\">[דנפחא]</span> כדי לתקנו ולהעלותו, ולמה הוא חוזר פעם ב' לומר שמע כאלו ח\"ו בפעם א' לא היה שם מציאות הש\"י, ונמצא הוא מקצר במציאותו ית' ובקבלת עול מלכות שמים. ולכך אמר משתקין אותו, <span data-k=\"sm\">[ודפח\"ח]</span>.\n[<b>ועל</b> <span data-k=\"sm\">פי זה ביאר ש\"ס דבכורות ד\"ח ע\"ב רצוצא דמית (ופירש רש\"י אפרוח שמת בקליפתה) מהיכן נפיק רוחיה, ומשני מהיכא דעייל נפיק. וש\"ס זה צריך ביאור, ואמר ע\"פ ש\"ס דברכות פרק הרואה, הרואה בצים בחלום וכו' נשתברו נעשית בקשתו, הרי כי בחינת ביצה מראה בחינת התפלה. והענין שאין לך מחשבה שלא יהא בה קומה שלמה, אף מחשבה רעה וזרה כשבאה אל האדם היא באה כדי לתקנו ולהעלותו כנ\"ל, ואם האדם דוחה המחשבה ההיא ממנו אז כאילו דוחה והורג קומה שלמה]</span>. אמנם לפעמים יש מחשבה שצריך לדחותה, ואם נפשך לומר במה אדע איזה מחשבה לדחותה ואיזה לקרבה ולהעלותה יתבונן האדם אם בשעה שבא המ\"ז מיד עלה במחשבתו במה לתקנה ולהעלותה, אז יראה לקרבה ולהעלותה, ואם לא יעלה <span data-k=\"sm\">[מיד]</span> במחשבתו במה לתקנה, אז מסתמא באה לבטל את האדם בתפלתו ולבלבל מחשבתו, אז רשות לדחות המחשבה ההיא כי הבא להורגך השכם כו'. <span data-k=\"sm\">[ובזה יובן רצוצא דמית מהיכן נפיק רוחיה, כלומר המחשבה שבאה בשעת תפילה שנקרא ביצה, דמית, דהיינו שדוחה אותה המחשבה וממית אותה, היכי נפיק רוחיה כלומר האיך הוא ממית ודוחה קומה שלימה, ומשני מהיכא דעל נפיק, כמו שעלה המחשבה לבלבל את האדם ולדחותו כך נפיק, רשות לאדם לדחות המחשבה ולהוציא אותה וזהו שאמר מהיכא דעל נפיק, ודפח\"ח.</span>\n<b>ופעם</b> <span data-k=\"sm\">א' שאל השואל </span>למורי<span data-k=\"sm\"> זלה\"ה אם אמר כמה תיבות בק\"ש ובתפלה בלא כוונה אם רשאי לחזור פעם שנית ולאומרם בכוונה, ואמר בזה הלשון: הלא ידוע ומפורסם שאין לך שום דבר שלא יהא בו מציאות השם, אפילו מחשבה חיצונית שם יש ג\"כ ניצוצות קדושות כנודע, וא\"כ]</span> אם אמר כמה תיבות &lt;בק\"ש ו&gt;בתפלה בלא כוונה, לא יאמרם פעם שנית, רק יהרהר במחשבה ובכוונה התיבות שאמר בלא כוונה. כל זה שמעתי <span data-k=\"sm\">[בשם]</span> <i>מורי</i> &lt;הבעש\"ט&gt; זלה\"ה <span data-k=\"sm\">[ודפח\"ח]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>בפ</b>\"<b>י</b>,<b> תולדות נ</b>,<b> ב (רמג</b>,<b> א)</b>\n<i>מלא כל גו'</i> – ישעי' ו, ג. <i>לית אתר כו'</i> – תקו\"ז תנ\"ז צא, סע\"ב.<i> הרואה ביצים כו'</i> – ברכות נז, א. <i>הבא להורגך כו'</i> – ברכות נח, א.\n----- הערות וציונים -----\n<i>כל מחשבה היא קומה שלמה</i> – ראה לקמן סי' רפג. לקו\"י סי' צ. צוה\"ר סי' צב.\n<i>וכאשר יעלה במחשבתו כו' לתקנה ולהעלותה</i> – ראה לקמן סי' צט, קיא-ב, קיב, קסג, רג, רז-א, רז-ב, רכב, רכז, רכח, רמ-א, רנג, רפז, רצה, שסח, שפג, שצה-ב, תו-א, תט.\n<i>בחינת ביצה מראה בחינת תפלה</i> – ראה ב\"י לטואו\"ח סי' תעג: כתב הכלבו (סי' נ) דאמרינן בירושלמי כו' וביצה כלומר בעא רחמנא למפרק יתנא כו'. במאירי לפסחים קיד, ב הובא זה בשם מדרש, והובא בשו\"ע הרב סי' תעג סוף סעיף כ. ובספר מהרי\"ל, סדר ההגדה סעיף ו: וביצה דתרגומו ביעא, דבעא רחמנא עלן ופרקינן.\n<i>לפעמים יש מחשבה שצריך לדחותה כו'</i> – הנה לבד מש\"כ להלן יש להעיר שענין העלאת מ\"ז אינו דבר השוה לכל נפש, והבעש\"ט כבר הזהיר על זה שכבוד אלקים הסתר דבר (לקמן סי' קיא-ב ותט), ובתוי\"י פ' עקב (קעב, א) כתב שהאריכות בזה הוא סכנה והמשכיל ידום. כ\"ק אדה\"ז כותב על זה מפורש: אם נופלים לו הרהורי תאוות ושאר מ\"ז בשעת העבודה בתורה או בתפלה בכוונה אל ישית לב אליהן אלא יסיח דעתו מהן כרגע, וגם אל יהי שוטה לעסוק בהעלאת המדות של המ\"ז כנודע כי לא נאמרו דברים ההם אלא לצדיקים שאין נופלים להם מ\"ז שלהם כ\"א משל אחרים, אבל מי שנופל לו משלו מבחי' הרע שבלבו בחלל השמאלי איך יעלהו למעלה והוא עצמו מקושר למטה (תניא רפכ\"ח. והובאו דבריו בס' דרך פקודיך להרה\"ק הרצ\"א מדינוב, בהקדמה ז אות ו-ח ושם מל\"ת לה חלק המחשבה אות ה, ומל\"ת מא חלק המחשבה אות ד-ה).\nוכן בס' יד\"א פי\"ז (לקו\"י דף כב, ב) האריך בזה: וכלל זה יהיה בידך, שבודאי אתה בעצמך מבין זה רק מחמת שנתגלו כתבים אלו של הקדוש מו\"ה דוב בער ז\"ל הנ\"ל לכמה אנשים, ומועטים הם שיכלו להדמות אליו ולעשות כמעשהו אפילו לנגוע בקצהו, והם רואים שם שכותב בכמה מקומות סגנון זה, דהיינו שמאהבה רעה שבאה לאדם יכול לאחוז באהבת הבורא בחשבו קו\"ח אם רצוני נוטה לאהוב שטות זה שהוא פסולת שנפלה בשבירה קו\"ח לשורשו לאהבת הבורא שממנו נלקח זאת האהבה, וכן ביראה רעה וכן בהתפארות הגרוע וכן בניצוח כו' . . שא\"א ללמוד קו\"ח זה אם לא יהיה מופשט מגשמיות, כי אם הוא דבוק בגשמיות ובתאוות (מכאן ואילך נעתק לקמן בכש\"ט סי' רמ-א עיי\"ש ובהערות לשם).\nרג\"כ לקמן סי' קפח. ועיין היטב בזח\"א קיב, ב. ובאו\"ת להרה\"מ ד\"ה הבנים יוצאים (סי' תפח. ואיתא ג\"כ בלקו\"י סי' קיג), שם הביא המשל אשר בזוהר שם. ועיי\"ע תורת המגיד בלקו\"א המיוחס להרה\"ק הרמ\"מ מוויטעבסק דף כה, סע\"ב ואילך. ולהעיר עוד מלקמן סי' צ, סוף סי' רז, וצוה\"ר סי' קמ (נעתק לקמן בשוה\"ג לסי' רלו).\n<i>אם רשאי לחזור</i> – כבר העיר ע\"ז כ\"ק אדמו\"ר זי\"ע \"השאלה היא <i>הרשאי</i> במקום שאין <i>חיוב</i> (לעכב) בכוונה\"."]]],[300010049,"מ\n\n<b>&lt;מהבעש\"ט&gt;</b> <span data-k=\"sm\">[דשמעתי </span>ממורי<span data-k=\"sm\">]</span> מי שהיה רגיל לדבר שקר אז תשובתו שלא לדבר שקר, גם לעשות שלום, כמו לוקחי ריבית גם מעכו\"ם לא יקבל <span data-k=\"sm\">[ודפח\"ח]</span>.\n<b>&lt;עכ\"א&gt;</b> <span data-k=\"sm\">[תא אחוי לך]</span> בלועי קרח <span data-k=\"sm\">[וכו']</span> משה אמת ותורתו אמת ואנחנו בדאים.<i>[ftnref_1_ה]</i>",[["","","----- מקורות ומראה מקומות -----\n<b>בפ</b>\"<b>י</b>,<b> ויצא נה</b>,<b> סע</b>\"<b>ב (רסח</b>,<b> ב)</b>\n<i>לוקחי ריבית כו'</i> – סנהדרין כה, ב. שו\"ע חו\"מ לד, כט. <i>תא אחוי לך כו'</i> – ב\"ב עד, א.\n----- שולי הגליון -----\n[ftn_1_ה]) <i>במקורו כ\"ז בהיפוך הסדר</i>: \"ביאור ש\"ס תא אחוי לך . . . בדאים, דשמעתי ממורי מי שהיה . . . ודפח\"ח\" <i>וממשיך</i>: \"ובזה יובן משה אמת, לכך תורתו שהתיר לאהרן לשנות מפני שלום אמת, משא\"כ אנו בדאים לכך גם לעשות שלום אסור לדבר שקר . . .\"\n----- הערות וציונים -----\n<i>תשובתו שלא כו'</i> – ראה רמב\"ם הל' דעות פ\"ב ה\"ב ושמנה פרקים פ\"ד, וכמ\"ש כבר המאירי בפירושו לסנהדרין כה, ב.\n<i>שהתיר לאהרן כו'</i> – ראה אבדר\"נ יב, ג."]]],[300010050,"מא\n\n<b>&lt;מבעש\"ט&gt;</b> <span data-k=\"sm\">[דשמעתי </span>ממורי<span data-k=\"sm\">]</span> פירוש סור מרע ועשה טוב, דירמיה הנביא נענש מה שהושלך לבור וכיוצא לפי שלא התפלל על ישראל כששמע הנבואה לרעה על ישראל, משא\"כ ישעיה שמו מורה על ישועה וכו'. והאדם יכול להפך חלום או נבואה מרעה לטובה, כמו שרואה בחלום מת יכול להפוך לעשות תם <span data-k=\"sm\">[וכו']</span> &lt;מצרה צהר&gt;. וז\"ש סור מרע ועשה טוב <span data-k=\"sm\">[ודפח\"ח]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>בפ</b>\"<b>י</b>,<b> ויצא נה</b>,<b> ג (רסח</b>,<b> ב)</b>\n<i>סור מרע גו'</i> – תהלים לד, טו. <i>שהושלך לבור</i> – ירמיה לח, ו. <i>ישעיה שמו כו'</i> – זח\"ב קעט, ב. רש\"י ישעי' מט, א.\n----- הערות וציונים -----\n<i>שלא התפלל כו'</i> – ראה מהרש\"א למגילה יד, ב ד\"ה מפני שנשים רחמניות הן. וראה הל' יסוה\"ת פ\"י ה\"ד.\n<i>והאדם יכול להפך חלום</i> – ראה ברכות נה, ב. זח\"א קפג, א ושם קצא, א. שו\"ת מן השמים סי' כב.\n<i>או נבואה</i> – עיין היטב ביאור הרה\"מ למגילה יד, ב באו\"ת סי' תמט (בלקו\"י סי' רלח). מדל\"י סי' קכ-קכא (קל) ומקבילו באו\"ת פ' עקב סי' קסד. ומקיים שם מה שדחה המהרש\"א הנ\"ל.\n<i>יכול להפך כו'</i> – ראה לקמן סי' פז-א-פז-ד.\n<i>וז\"ש סור מרע כו'</i> – כלומר שיעשה מרע טוב, כמבואר לקמן סי' כט. ורג\"כ סי' פט."]]],[300010051,"מב-א\n\n<b>&lt;מבעש\"ט&gt;</b> <span data-k=\"sm\">[שמעתי </span>ממורי<span data-k=\"sm\">]</span> כל אשר תמצא ידך לעשות בכחך עשה, &lt;פי'&gt; לקשר המעשה &lt;בכח&gt; <span data-k=\"sm\">[עם]</span> המחשבה, &lt;וז\"ש לעשות בכחך&gt;. זהו מעלת חנוך מט\"ט שהיה מייחד קבה\"ו על כל תפירה. וזהו מעלת משה רבינו ע\"ה <span data-k=\"sm\">[שנאמר]</span> ואתה פה עמוד עמדי כו'.",[["","","----- מקורות ומראה מקומות -----\n<b>בפ</b>\"<b>י</b>,<b> ויצא נה</b>,<b> ד (ער</b>,<b> א)</b>\n<i>כל אשר גו'</i> – קהלת ט, י.<i> חנוך מט\"ט</i> – תיב\"ע ובראשית רבתי נח ה, כד. <i>שהי' מייחד כו'</i> – עמק המלך, שער קרית ארבע פצ\"ד בשם מדרש. מגיד מישרים פ' מקץ (בסוף מהד\"ב). עשרה מאמרות, מאמר אם כל חי ח\"ג סי' סב. <i>ואתה פה גו'</i> – ואתחנן ה, כח.\n----- הערות וציונים -----\nראה לקמן סי' צא\n<i>לקשר המעשה עם המחשבה</i> – ראה לקמן סי' קפט. ורג\"כ סי' מט, נט ושע.\n<i>חנוך מט\"ט</i> – תיב\"ע ומדרש בראשית רבתי לנח ה, כד. ראה תוס' יבמות טז, ב ד\"ה פסוק זה.\n<i>שהיה מייחד כו'</i> – עמה\"מ שער קרית ארבע פצ\"ד (קג, שלהי ע\"ד) בשם מדרש. עשרה מאמרות, מאמר אם כל חי ח\"ג סי' כב. מגיד משרים פ' מקץ בסוף מהד\"ב. וראה מדל\"י סי' קלא (קמ).\n<i>וזהו מעלת מרע\"ה כו'</i> – בבפ\"י כתב כאן \"וכתבתי מזה במ\"א\" והוא שם פ' מקץ עג, ג (שנד, ב): וז\"ש ויוסף הוא השליט על הארץ הוא המשביר . . שגם בעת שהיה משביר לכל עם הארץ לפקח בעסק המדינה ועמי הארץ גם אז לא נפסק מדביקות השי\"ת אשר מעלה זו נאמר במרע\"ה ואתה פה עמוד עמדי."]]],[300010052,"מב-ב\n\n<b>וישא</b> יעקב רגליו, <span data-k=\"sm\">[ונראה לי דשמעתי </span>ממורי<span data-k=\"sm\">]</span> כי ע\"י האמונה מעלה רגלי המלכות אשר רגליה ירדות מות ומקשרה עם סמכי קשוט דז\"א <span data-k=\"sm\">[וכו', ודפח\"ח]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>בפ</b>\"<b>י</b>,<b> ויצא נו</b>,<b> סע</b>\"<b>א (ערב</b>,<b> ב)</b>\n<i>וישא יעקב גו'</i> – ויצא כט, א. <i>המלכות אשר כו'</i> – ע\"ח של\"ד פ\"א. <i>רגליה גו'</i> – משלי ה, ה.\n----- הערות וציונים -----\nראה לקמן סוף סי' פ וסי' פח.\n<i>ומקשרה עם סמכי קשוט דז\"א</i> – שהם בחי' האמונה כנ\"ל סי' יא-ב. וש\"נ."]]],[300010053,"מג\n\n<b>&lt;מהבעש\"ט&gt;</b> <span data-k=\"sm\">[דשמעתי </span>ממורי<span data-k=\"sm\">]</span> ביאור ש\"ס פ' תלמידים היו להלל כו' עד עוף הפורח נשרף בהבל פיו &lt;דיונתן בן עוזיאל&gt;. להבין זה, גם ביאור ש\"ס &lt;באלישע&gt; שלא נראה זבוב על שולחנו <span data-k=\"sm\">[וכו']</span>. והענין, לפי מחשבתו של אדם כך יש עולמות למעלה ממנו העומדים עליו, אם מחשבתו בקדושה ורוחני כך הם העולמות שלמעלה הימנו, ואם מחשבתו בטומאה כך הם העולמות, וכפי המחשבה והעולמות כך עוברים לפניו בגשמי עופות טהורים או טמאים, וה\"ה שאר מיני בעלי חיים טמאים או טהורים עוברים לפניו. ויש בזה ג' בחינות, א' טהורים, ב' טמאים, ג' ממוצע כו', ולמעלה מזה יש עולם השכל, שאין שום דבר משיגו כו'. וז\"ש כל עוף הפורח נשרף כו', וזהו שלא נראה זבוב על שולחנו וידעה שהוא איש קדוש ומחשבתו קדוש וכו', <span data-k=\"sm\">[ודפח\"ח]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>בפ</b>\"<b>י</b>,<b> ויצא נו</b>,<b> ד (ערה</b>,<b> ב)</b>\n<i>פ' תלמידים כו'</i> – סוכה כח, א. <i>באלישע שלא נראה כו'</i> – ברכות י, ב.\n----- הערות וציונים -----\n<i>ביאור ש\"ס פ' תלמידים כו'</i> – הובא לקמן שלהי סי' שכ.\n<i>לפי מחשבתו של אדם כך כו'</i> – ראה לקמן סי' קמה. צוה\"ר סי' קמב. מדל\"י סי' כט (לג).\n<i>וזה שלא נראה זבוב כו'</i> – מהרש\"א שם. ועיין מש\"כ בבפ\"י בסמוך נז, א (רעז, א): דשמעתי ממורי כפי מחשבתו של אדם בקדושה או בקליפה כך הם העולמות שעליו מלמעלה, וכפי המחשבה כך המאורע במעשה שעוברין לפניו אם בעלי חיים טהורים או טמאים, והוא הדין שאר המאורעות וכו' ודפח\"ח."]]],[300010054,"מד-א\n\n<b>ענין</b> הדביקות בו יתברך הוא ע\"י אותיות התורה והתפלה, שידבק מחשבתו ופנימיותו לפנימיות רוחניות שבתוך האותיות, בסוד ישקני מנשיקות פיהו, דביקות רוחא ברוחא, וכמו ששמעתי <span data-k=\"sm\">[</span>ממורי<span data-k=\"sm\">]</span> אם תשכבון בין שפתים <span data-k=\"sm\">[וכו', כתבתי מזה במ\"א]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>בפ</b>\"<b>י</b>,<b> ויצא נט</b>,<b> ד (רפח</b>,<b> ב)</b>\n<i>ישקני גו'</i> – שה\"ש א, ב. <i>דביקות רוחא ברוחא</i> – זח\"ב קכד, ב. <i>אם תשכבון גו'</i> – תהלים סח, יד.\n----- הערות וציונים -----\nראה לקמן סי' מד-ב ורפד-ב."]]],[300010055,"מד-ב\n\n<b>וכשמאריך</b> בתיבה הוא דביקות שאינו רוצה ליפרד מאותו תיבה<i>[ftnref_1_ו]</i>.",[["","","----- מקורות ומראה מקומות -----\n<b>לקו</b>\"<b>י ג</b>,<b> א (סי</b>'<b> כא) [צוה</b>\"<b>ר סי</b>'<b> ע]</b>\n----- שולי הגליון -----\n[ftn_1_ו]) <i>במקורו</i>: הדביקות הוא כשאומר תיבה א' הוא מאריך באותה תיבה הרבה, שמחמת דביקות אינו רוצה לפרוד עצמו מהתיבה, ולכך מאריך באותה תיבה.\n----- הערות וציונים -----\n<i>וכשמאריך בתיבה כו'</i> – ראה לקמן סי' קצב. ועיין צוה\"ר סי' עה ומדל\"י סי' מז (נב-נג)."]]],[300010056,"מה\n\n<b>&lt;מהבעש\"ט&gt;</b> <span data-k=\"sm\">[ששמעתי </span>ממורי<span data-k=\"sm\"> איך]</span> בכל אות נכללו כל האותיות, כי שורש כל האותיות הוא אות א' והוא קרוב לאחדות הא\"ס, ואח\"כ נתפשטו, כי אות ב' הוא ב' אלפין כו' עד &lt;אות&gt; ת' הוא ד' מאות אלפין, ואות ת' הוא אחרון ורחוק מן המאציל, וע\"י הצדיק מקרב כל האותיות לשרשן, לאות א', ואז נמתק הדין בשרשו כו'.",[["","","----- מקורות ומראה מקומות -----\n<b>בפ</b>\"<b>י</b>,<b> ויצא ס</b>,<b> א (רצ</b>,<b> ב)</b>\n<i>שורש </i>. .<i> אות א</i> – זח\"ב רלד, ב.\n----- הערות וציונים -----\nראה לקמן סי' פו, צו-ב, קס, קצ ושנה. ורג\"כ דמ\"א ס\"פ תצוה: קבלתי מאא\"ז זללה\"ה כי בכל אות מהכ\"ב אתוון יש כל כ\"ב אותיות חוץ מאות מ\"ם כו'.\n<i>א' והוא קרוב כו' ת' הוא אחרון ורחוק כו'</i> – ראה פרדס רמונים להרמ\"ק, שער האותיות פ\"ב."]]],[300010057,"מו-א\n\n<b>&lt;מהבעש\"ט&gt;</b> <span data-k=\"sm\">[דשמעתי </span>ממורי<span data-k=\"sm\">]</span> ביאור ש\"ס לא גלו ישראל עד שכפרו בה' ובדוד <span data-k=\"sm\">[וכו']</span>, וביאור ש\"ס אין בין עוה\"ז לימות המשיח אלא שעבוד מלכיות בלבד <span data-k=\"sm\">[וכו']</span>, דאמרו בש\"ס מי שעברו עליו מ' יום בלא יסורין קיבל עולמו <span data-k=\"sm\">[וכו']</span> ה\"ד יסורין הושיט ידו לארנקי &lt;ליטול דינר זהב ונטל מטבע פחותה&gt;, והקשה הא אין יסורין בלא עון, וכי ס\"ד שזה נחשב לכפרת עון. וביאר, כי צדיק באמונתו יחיה, כי המאמין בהשגחה פרטית של הש\"י ויודע שכל מאורעותיו של האדם &lt;הם&gt; ממנו ית', הן דבר קטן או גדול, הכל הוא בדין אדנ-י דינא דמלכות שמים, והוא לסיבת חטאו, ומיד נתחרט ומלא חרדה ופחד ה', מיד מוחלין לו מאחר שהוא מאמין וחוזר בו ומדבק מחשבתו בו ית'. לכך גם המושיט ידו &lt;ליקח דינר זהב ועלה בידו דינר כסף&gt;, אחר שהוא <span data-k=\"sm\">[מאמין שזה]</span> לסיבת חטאו ומתחרט, נחשב לכפרת עון.\n<b>ובחינה</b> זו נקרא דוד, כי א\"ס שנקרא אין, בחינת ד', ומזה נמשך שהיא ו', אל ד' ב' שהוא תכלית השפלות הכל בהשגחה פרטיות ממנו ית' <span data-k=\"sm\">[וכו']</span>. וכשאינו מאמין זה שהכל בהשגחה פרטיות ממנו ית', רק אומר כחי ועוצם ידי עשה לי, זה נקרא כופר בהש\"י ובבחי' דוד הנ\"ל, כי כופר בדין מלכות אדנ-י, רק מלכות הוא מכוסה ומשועבד אל הקליפה המכסה ומסתיר עניני השגחתו ית' מבני אדם. ולעתיד בימות המשיח, אשר את רוח הטומאה יעביר מן הארץ, אז יתגלה השגחתו ית' בפרטי פרטות כו'. ובזה יובן לא גלו ישראל עד שכפרו בהקב\"ה ובמלכות בית דוד <span data-k=\"sm\">[וכו']</span>. וזהו שבין עוה\"ז לימות המשיח שעבוד מלכיות בלבד, והבן, <span data-k=\"sm\">[ודפח\"ח]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>בפ</b>\"<b>י</b>,<b> וישלח סד</b>,<b> א (שח</b>,<b> ב)</b>\n<i>לא גלו כו'</i> – זח\"ב קעה, ב. <i>אין בין עוה\"ז כו'</i> – ברכות לד, ב. <i>מי שעברו כו'</i> – ערכין טז, ב. <i>אין יסורין כו'</i> – שבת נה, א. <i>צדיק באמונתו יחי'</i> – חבקוק ב, ד.<i> אד' דינא דמ\"ש</i> – זח\"ג יא, ב. שם רנז, ב. <i>כחי ועוצם גו'</i> – עקב ח, יז. <i>את רוח הטומאה גו'</i> – זכרי' יג, ב.\n----- הערות וציונים -----\n<i>המאמין בהשג\"פ כו'</i> – ראה לקמן סי' סו.\n<i>ובחינה זו נק' דוד כו' בחי' ד'</i> – ד' איהו מסכנא (זח\"א ג, א. שבת קד, א) בחינת דוד (זח\"א קנז, א. ועיין זח\"ג רכג, א). ועיין מדל\"י סי' קסו (קעג) ובאו\"ת סי' קמג.\n<i>נמשך שהוא ו'</i> – אות ו' מורה על המשכה. ראה זו\"ח בראשית ה, ג. תקו\"ז תנ\"ב פז, א. מדל\"י סי' קסו (קעג) בביאור הן עם לבדד (באו\"ת סי' קמג). תניא אגה\"ת פ\"ד.\n<i>ד' ב' שהוא תכלית השפלות</i> – מלכות דמלכות. ראה לקו\"י סי' עא.\n<i>וכשאינו מאמין כו'</i> – נשנה בשנוי לשון קצת לקמן סי' תכז."]]],[300010058,"מו-ב\n\n[<b>ונ\"ל</b> <span data-k=\"sm\">דשמעתי </span>ממורי<span data-k=\"sm\">]</span> &lt;ש&gt;כל מה שאדם משיג בענין אלקות הוא בחי' מלכות, אבל למעלה מזה א\"א להשיג <span data-k=\"sm\">[וכו', ודפח\"ח]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>בפ</b>\"<b>י</b>,<b> ס</b>\"<b>פ בשלח סה</b>,<b> ב (שיד</b>,<b> ב)</b>\n----- הערות וציונים -----\n<i>כל מה שאדם משיג כו'</i> – ראה תקו\"ז יא, סע\"ב, ושם ת\"ג יח, ב ות\"ו כא, סע\"ב. וראה לקמן סי' עד."]]],[300010059,"מז\n\n<b>&lt;הקשו</b> התוס'&gt; <span data-k=\"sm\">[לבאר קושיית התוספות בפרק ט' דשבת . . .]</span> למה הוצרך הקב\"ה לכפות ההר &lt;על ישראל&gt;, <span data-k=\"sm\">[כגיגית]</span> הא אמרו מעצמן נעשה ונשמע . . . &lt;ופירש הבעש\"ט&gt; <span data-k=\"sm\">[שמעתי מפי </span>מורי<span data-k=\"sm\"> זלה\"ה ע\"ה]</span> לכך כפה הקדוש ברוך הוא על ישראל הר כגיגית, ללמד שגם שאינו חושק לתורה ועבודת ה', מ\"מ אינו בן חורין ליבטל, רק יעשה בעל כרחו וידמה כמי שכופו אותו לעשותו בע\"כ, <span data-k=\"sm\">[והוא דרך טוב לאיש ישראלי לימי הקטנות שלא יבטל התלמיד מעסק למודו ועבודת ה' גם כשאין חושק, דמכל מקום עשה מעשה, שהדיבור נקרא מעשה, ולכך גם שהיה בלי כונה יצא]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>בפ</b>\"<b>י</b>,<b> וישב סו</b>,<b> סע</b>\"<b>ג (שכא</b>,<b> א)</b>\n<i>התוס'</i> – שבת פח, א ד\"ה כפה.<i> שהדיבור נקרא מעשה</i> – ב\"מ צ, סע\"ב.\n----- הערות וציונים -----\nנראה לי שמה ששמע מפי הבעש\"ט קאי על דברי הרמב\"ן (ראה לקמן ריש סי' קכז, ובתוי\"י ס\"פ משפטים סג, ד), וביאור התוס' הוא מבעל בפ\"י עצמו (ונשנה בספרו בדרוש לשה\"ג תקכ\"ז, דף קט, סע\"א, בסתמא). ולהעיר שעד\"ז כבר פירש המהר\"ל בס' גור אריה ליתרו יח, יז ובנצח ישראל פי\"א.\n<i>שהדיבור נקרא מעשה</i> – ראה תניא פל\"ז ושם פנ\"ג."]]],[300010060,"מח\n\n<b>&lt;מהבעש\"ט&gt;</b> <span data-k=\"sm\">[ששמעתי </span>ממורי<span data-k=\"sm\"> זלה\"ה]</span> ביאור ש\"ס <span data-k=\"sm\">[סוף כתובות]</span> כל הדר בא\"י דומה כמי שיש לו אלוה וכל הדר בחו\"ל דומה כמי שאין לו אלוה <span data-k=\"sm\">[וכו' יעו\"ש]</span>, והוקשו הדיוקים אהדדי, וגם יציבא בארעא כו'. וביאר זה ע\"פ מה שביאר משנה מה בין תלמידי אברהם אבינו לתלמידי בלעם הרשע כו', והכא נמי כך, מי שהוא מתלמידי א\"א ומתמיד בתורה ובעבודת ה' כל היום ונק' דר בא\"י, ופעם א' נזדמן לו ביטול תורה או תפלה שאז דר בחו\"ל, דומה לו כמי שאין לו אלוה, ובהיפך כו' <span data-k=\"sm\">[ודפח\"ח]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>בפ</b>\"<b>י</b>,<b> וישב סח</b>,<b> ג (שכט</b>,<b> ב)</b>\n<i>כל הדר כו'</i> – כתובות קי, סע\"ב. <i>יציבא בארעא כו'</i> – ע\"פ עירובין ט, א. <i>מה בין כו'</i> – אבות פ\"ה מי\"ט.\n----- הערות וציונים -----\nראה לעיל סי' כט, ובהערות שם מס' דמ\"א.\n<i>ע\"פ מה שביאר משנה כו'</i> – ראה לקמן סי' סג וסח."]]],[300010061,"מט\n\n[<b>ששמעתי</b> ממורי<span data-k=\"sm\">]</span> כל מה שתמצא ידך לעשות בכחך עשה, &lt;פי'&gt; להעלות אנשי עשיה אל המחשבה שנק' יו\"ד, <span data-k=\"sm\">[אותיות]</span> יד\"ו.",[["","","----- מקורות ומראה מקומות -----\n<b>בפ</b>\"<b>י</b>,<b> וישב סח</b>,<b> ד (שלא</b>,<b> א)</b>\n<i>כל מה גו'</i> – קהלת ט, י. <i>המחשבה שנק' יו\"ד </i>– תקו\"ז תי\"ט מא, ב. שם תס\"ט קטו, א.\n----- הערות וציונים -----\nראה לעיל סי' מב-א, ולקמן סי' צא, קפט-ב ושע."]]],[300010062,"נ\n\n<b>&lt;מהבעש\"ט&gt;</b> <span data-k=\"sm\">[הנה שמעתי </span>ממורי<span data-k=\"sm\"> זלה\"ה]</span>, אם כבר בא לידי נסיון, דהיינו דעייל ונפק, שוב אינו בא לידי נסיון ויוכל להיות עומד על מצב ומדריגה אחת שלא לירד. וזה שאמר <span data-k=\"sm\">[הכי דוד המלך ע\"ה]</span> לא אמות כי אחיה, שלא יצטרך לירד כדי להעלות זולתו <span data-k=\"sm\">[וכו']</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>בפ</b>\"<b>י</b>,<b> ס</b>\"<b>פ וישב סט</b>,<b> א (שלב</b>,<b> ב)</b>\n<i>לא אמות גו'</i> – תהלים קיח, יז.\n----- הערות וציונים -----\n<i>דהיינו דעייל ונפיק</i> – להעיר מזח\"א קמ, ב ושם ס\"ת קמז, ב. זח\"ג רצב, א."]]],[300010063,"נא-א\n\n[<b>ביאר</b> מורי<span data-k=\"sm\"> זלה\"ה ש\"ס . . .]</span> אע\"פ שאלו אוסרין ואלו מתירין, היינו בו' קצוות זעיר אנפין, אבל למעלה, בבינה שנק' אלקים חיים, הכל אחדות אחד, וז\"ש אלו ואלו דברי אלקים חיים <span data-k=\"sm\">[ודפח\"ח]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>בפ</b>\"<b>י</b>,<b> מקץ סט</b>,<b> ג (שלד</b>,<b> ב)</b>\n<i>אע\"פ שאלו אוסרין כו' אלו ואלו כו'</i> – עירובין יג, ב. <i>בבינה שנק' אל' חיים</i> – זח\"ב סח, ב (ובהג' הרח\"ו שם). לקו\"ת להאריז\"ל ירמי' י.\n----- הערות וציונים -----\nראה צ\"פ פ' שמות ז, א (לז, א): דשמעתי ממורי ביאור ש\"ס אע\"פ שאלו אוסרין ואלו מתירין אלו ואלו דא\"ח, כי אוסרין ומתירין הם מצד ו' קצוות ששם דבר והיפוכו, משא\"כ בבינה שנקרא אלקים חיים שם הוא אחדות אחד."]]],[300010064,"נא-ב\n\n[<b>דכתב</b> <span data-k=\"sm\">בזוהר שערי היכלות התפלה זה למעלה מזה, ומלאכים מקבלי התפילות, יש מלאך שקומתו ת\"ק שנה וכו' יעו\"ש]</span>. ויש להבין, הא הש\"י מלא כל הארץ כבודו, לית אתר פנוי מיניה, ובמקום שאדם <span data-k=\"sm\">[מתפלל]</span> שם כבודו ית' מצוי, וא\"כ למה לי שיקובל התפלה ע\"י המלאכים שילכו מהיכל להיכל וכו'. &lt;וי\"ל דהקב\"ה עשה זה כדי שיראה לו לאדם שהוא רחוק, וישתדל להתקרב מאד, כמ\"ש הבעש\"ט ז\"ל&gt; <span data-k=\"sm\">[דשמעתי </span>ממורי<span data-k=\"sm\"> זלה\"ה]</span> משל שאמר קודם תקיעת שופר, שהיה מלך א' חכם גדול ועשה באחיזת עינים חומות ומגדלים ושערים וצוה שילכו אצלו דרך השערים והמגדלים, וצוה לפזר בכל שער ושער אוצרות המלך, ויש שהלך עד שער א' &lt;ולקח ממון&gt; וחזר, ויש כו', עד שבנו ידידו התאמץ מאד שילך &lt;דוקא&gt; אל אביו המלך, אז ראה שאין שום מחיצה מפסיק בינו לבין אביו כי הכל היה אחיזת עינים. והנמשל מובן <span data-k=\"sm\">[ודפח\"ח]</span>. &lt;דהקב\"ה מסתתר בכמה לבושין ומחיצות, ובידוע&gt; <span data-k=\"sm\">[וכן כתבתי במ\"א ששמעתי </span>ממורי<span data-k=\"sm\"> זלה\"ה כי בידיעת האדם]</span> שהש\"י מלא כל הארץ כבודו וכל תנועה ומחשבה הכל ממנו יתברך, <span data-k=\"sm\">[אז בידיעה זו יתפרדו כל פועלי און וכו'. אם]</span> כן כל המלאכים <span data-k=\"sm\">[וכל]</span> ההיכלות הכל נברא ונעשה כביכול מעצמותו ית' כהדין קמצא דלבושיה מיניה וביה, &lt;ואין שום מחיצה מבדיל בין האדם ובינו ית' בידיעה זאת, ועי\"ז יתפרדו כל פועלי און&gt; <span data-k=\"sm\">[ובידיעה זאת יתפרדו כל פועלי און, שאין שום מחיצה ומסך מבדיל בין האדם ובינו ית' בידיעה זאת]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>בפ</b>\"<b>י</b>,<b> מקץ ע</b>,<b> ג (שלט</b>,<b> ב)</b>\n<i>בזוהר</i> – זח\"ב רמד, ב ואילך. שם רס, ב ואילך. <i>יש מלאך כו'</i> – זח\"ב נח, א. <i>מכה\"כ</i> – ישעי' ו, ג. <i>לית אתר כו'</i> – תקו\"ז תנ\"ז צא, סע\"ב. <i>יתפרדו גו'</i> – תהלים צב, י. <i>כהדין קמצא כו'</i> – בר\"ר כא, ה.\n----- הערות וציונים -----\n<i>שיקובל התפלה ע\"י מלאכים כו'</i> – ראה סנהדרין מד, ב ורש\"י שם ד\"ה לעולם יבקש. זח\"ב רא, ב. תקו\"ז תס\"ט קה, סע\"ב. וראה מאמר ד\"ה ואברהם זקן לכ\"ק אדמו\"ר זי\"ע (הועתק בביאורים והערות בסוף ס' צוה\"ר, סי' א) אות ד' ואילך.\n<i>שיראה לו לאדם שהוא רחוק וישתדל כו'</i> – ראה לעיל סי' כט ול. ולקמן סי' נה ורלז.\n<i>משל שאמר כו'</i> – המשל בארוכה בס' דמ\"א פ' תבוא בהפטרת תבוא. וראה לקמן בהוספות סי' מב ומג."]]],[300010065,"נב\n\n[<b>ששמעתי</b> ממורי<span data-k=\"sm\"> פירוש]</span> &lt;בשם&gt; הרמב\"ן ולא תגעל נפשי אתכם . . . לקשר ראיה ושמיעה והילוך הגשמי ברוחני כו'.",[["","","----- מקורות ומראה מקומות -----\n<b>בפ</b>\"<b>י</b>,<b> מקץ עד</b>,<b> א (שנו</b>,<b> א)</b>\n<i>פי' הרמב\"ן ולא תגעל גו'</i> – בחקותי כו, יא ופי' הרמב\"ן שם.\n----- הערות וציונים -----\nהובא באורך בס' כתונת פסים פ' בהעלתך לא, א יעיי\"ש."]]],[300010066,"נג\n\n<b>מבואר</b> בכוונת האר\"י זלה\"ה ענין בירורי נצוצות הקדושות שנפלו בעת <span data-k=\"sm\">[השבירה]</span> &lt;שהי' הקב\"ה בונה עולמות ומחריבן&gt;, וצריך האדם להעלות ולבררן מדומם לצומח חי מדבר, לברר הניצוץ הקדוש שבתוך הקליפה <span data-k=\"sm\">[וכו']</span>, וזה תכלית עבודת איש ישראל בתורה ומצות וכוונת אכילה, כמבואר כל אחד במקומו. ונודע כי כל ניצוץ שבתוך דומם וצומח כו' יש בו קומה שלימה מן רמ\"ח איברים ושס\"ה גידים, וכשהוא בתוך הדומם והצומח <span data-k=\"sm\">[וכו']</span> הוא בבית האסורין, שאינו יכול לפשוט ידיו ורגליו ולדבר כ\"א ראשו על כרעיו וקרבו, ומי שיכול בטוב מחשבתו <span data-k=\"sm\">[וכוונתו]</span> להעלות הניצוץ הקדוש מצומח לחי מדבר, הוא מוציאו לחירות, ואין לך פדיון שבוים גדול מזה, &lt;כמ\"ש&gt; <span data-k=\"sm\">[וכמו ששמעתי </span>ממורי<span data-k=\"sm\">]</span> &lt;הבעש\"ט ז\"ל&gt; <span data-k=\"sm\">[וכו']</span>, ובפרט אם &lt;הוא&gt; בן המלך בבית האסורין ובא אדם אחד בהשתדלותו והוציאו מבית האסורין מעבדות לחירות, ששכרו כפול ומכופל. אמנם כל זה הוא בדין ומשפט עליון, אשר קץ שם לחשך עד מתי יהיה בבית האסורין ואימתי יזכה לצאת חפשי וע\"י מי יהיה היציאה לחירות.",[["","","----- מקורות ומראה מקומות -----\n<b>בפ</b>\"<b>י</b>,<b> מקץ עד</b>,<b> ב (שנח</b>,<b> א)</b>\n<i>בכוונת האריז\"ל</i> – ע\"ח שער הכללים א-ב. שם שי\"ח פ\"א ושל\"ט פ\"א. פע\"ח שער התפלה פ\"ז. לקו\"ת וטה\"מ פ' עקב. שם תהלים פד. ספר הגלגולים פל\"ח. <i>בונה עולמות כו'</i> – בר\"ר ג, ז. <i>קץ שם לחשך</i> – איוב כח, ג.\n----- הערות וציונים -----\nראה לעיל סי' טו. לקמן סי' קיג-ב, קצד, ריח, רעז. צוה\"ר סי' קט (ובהערות שם), קכז, קמא. לקו\"י סי' קלב.\n<i>וזה תכלית עבודת כו'</i> – ראה ע\"ח ש\"נ פ\"ג.\n<i>כמש\"ש ממורי ובפרט כו'</i> – ראה לקמן סי' רכב. וראה סוף סי' קס וסוף סי' רפז."]]],[300010067,"נד\n\n<b>&lt;מהבעש\"ט&gt;</b> <span data-k=\"sm\">[דשמעתי </span>ממורי<span data-k=\"sm\">]</span> זלה\"ה, אם אדם רוצה לשבח ישבח את הקב\"ה, ואם רוצה לגנות יגנה את עצמו <span data-k=\"sm\">[וכו' ודפח\"ח]</span>. &lt;שהמשבח מודה באחדות ומכובד, משא\"כ המבזה ומגנה שנפרד מהאחדות.&gt;",[["","","----- מקורות ומראה מקומות -----\n<b>בפ</b>\"<b>י</b>,<b> ויגש עו</b>,<b> א (שסד</b>,<b> א)</b>\n----- הערות וציונים -----\n<i>שהמשבח מודה באחדות כו'</i> – קצר כאן וז\"ל במקורו: מצד האחדות חסרון של זולתו יש בו בעצמו שמץ מנהו [ראה לקמן סי' שסג, וכן סי' פט וקטז], הגם מצד שהוא נברא המבזה שום נברא כביכול כאלו מבזה לאומן שבראו, וכמעשה דרשב\"א שפגע באדם מכוער וכו' [תענית כ, ב], ובזה יובן כל המכבד את הבריות [אבות פ\"ד מ\"א] מצד שהוא בריה נברא ממנו ית' מורה על עצמו שהוא מכובד מצד האחדות, משא\"כ המבזה שום נברא כביכול נקרא בוזי [ש\"א ב, ל] שנוגע בכבודו ית', ומלבד זה מורה על עצמו שהוא נקלה ונבזה מצד האחדות . . ובזה יובן צחות לשונו של מורי זלה\"ה אם הוא משבח לשום נברא אז הוא משבח להשי\"ת שברא בריה נכבד זה, ואם מגנה שום נברא מלבד שנוגע בבורא ית' אלא את עצמו וא\"ש."]]],[300010068,"נה\n\n<b>&lt;מהבעש\"ט&gt;</b> <span data-k=\"sm\">[ושמעתי </span>ממורי<span data-k=\"sm\"> כי]</span> העושה מצוה גדולה, או למד תורה הרבה ומתפלל בכוונה, לא יכניס בלבו שום התפארות שהוא עשה זאת, כי אם מלכות שנק' אני מן אדנ-י היא עשתה זאת [. . .] משא\"כ אם מתפאר לומר שהוא בעצמו עשה זה, אז גורם ח\"ו שמסתלק י' מן אני ונשאר אן <span data-k=\"sm\">[וכו' ודפח\"ח]</span>.\n[<b>ונ\"ל</b>] שזהו מה שאמרו <span data-k=\"sm\">[במשנה]</span> מאין באת <span data-k=\"sm\">[ולאן אתה הולך וכו', ר\"ל]</span> כאשר חושב א\"ע ל<span data-k=\"sm\">[אפס ו]</span>אין <span data-k=\"sm\">[שיודע שבא מטפה סרוחה, אז מאין באת]</span>, &lt;באת בהתקרבות להש\"י&gt;. משא\"כ במתפאר שהוא העושה, וזה נקרא הולך &lt;ומרוחק מהש\"י&gt; <span data-k=\"sm\">[היפך ביאה כנודע]</span>, אז מסתלק י' ונשאר אן. וזהו <span data-k=\"sm\">[שאמר]</span> ולאן אתה הולך, והבן. <span data-k=\"sm\">[(ואפשר ששמעתי זה ג\"כ </span>ממורי<span data-k=\"sm\">, והשי\"ת יודע)]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>בפ</b>\"<b>י</b>,<b> ויגש עז</b>,<b> רע</b>\"<b>א (שסח</b>,<b> א)</b>\n<i>מלכות שנק' כו'</i> – זח\"א רס, ב. <i>מאין באת כו'</i> – אבות פ\"ג מ\"א.\n----- הערות וציונים -----\nראה לקמן סי' רסט.\n<i>כ\"א מלכות </i>. .<i> היא עשתה זאת</i> – ראה צ\"פ פ' וארא כא, סע\"ד (פו, ב): דכתבתי בשם מורי זלה\"ה בעת עוסקו בתורה ומצות לא יחשב בלבו שהוא עושה כך, רק השכינה העושה זאת ודפח\"ח. וראה לקמן סי' קצא (ובשוה\"ג שם) וצוה\"ר סי' קלח.\n<i>כשמתפאר </i>. .<i> נקרא הולך ומרוחק מהש\"י</i> – ראה לעיל סי' כט ול."]]],[300010069,"נו\n\n<b>&lt;מהבעש\"ט&gt;</b> <span data-k=\"sm\">[ששמעתי </span>ממורי<span data-k=\"sm\"> זלה\"ה]</span> כי במקום שאדם חושב במחשבה שם הוא כולו <span data-k=\"sm\">[וכו' ודפח\"ח]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>בפ</b>\"<b>י</b>,<b> ר</b>\"<b>פ ויחי עז</b>,<b> ד (שעא</b>,<b> ב)</b>\n----- הערות וציונים -----\nראה לקמן סי' רח, רל, ערה ורפג. צוה\"ר סי' סט. מדל\"י סי' מה (מח), צג (קב) – עיי\"ש היטב, קסה (קצב). ועיין לקמן בהוספות סי' מח ובהערות שם. וראה מש\"כ בהערות וציונים לצוה\"ר שם להעיר מירושלמי ברכות פ\"ו ה\"ח (הסיע דעתו כו'), ועיי\"ע זח\"א רסו, ריש ע\"ב ומחשבה איהו אדם, וכן בר\"מ זח\"ג רמז, ב (ועיי\"ש בנצו\"ז)."]]],[300010070,"נז\n\n<b>&lt;מבעש\"ט&gt;</b> <span data-k=\"sm\">[ששמעתי </span>ממורי<span data-k=\"sm\">]</span> ואשיבה רגלי אל עדותיך, &lt;פי'&gt; ההרגל <span data-k=\"sm\">[וכו']</span>. והכא נמי כך אם תשיב משבת רגליך, ההרגל של עוה\"ז, <span data-k=\"sm\">[וכל הפסוק יובן ממילא,]</span> אז והאכלתיך נחלת יעקב <span data-k=\"sm\">[אביך וגו' וק\"ל]</span>. ו&lt;כן&gt; <span data-k=\"sm\">[אפשר מה שנאמר]</span> וישא יעקב &lt;את&gt; רגליו <span data-k=\"sm\">[הוא]</span> ג\"כ ההרגל, שיצא מגשמיות לרוחניות, והבן.",[["","","----- מקורות ומראה מקומות -----\n<b>בפ</b>\"<b>י</b>,<b> ויחי פ</b>,<b> א (שפא</b>,<b> א)</b>\n<i>ואשיבה גו'</i> – תהלים קיט, נט. <i>אם תשיב גו'</i> – ישעיה נח, יג. <i>והאכלתיך גו'</i> – ישעיה נח, יד. <i>וישא יעקב גו'</i> – ויצא כט, א.\n----- הערות וציונים -----\nראה לקמן סי' קמא וקפח.\n<i>רגלי </i>. .<i> פי' ההרגל</i> – ראה לקו\"ת להאריז\"ל פ' שמות, שלהי ד\"ה ויקם.\n<i>שיצא מגשמי לרוחני</i> – להעיר ממש\"כ בבפ\"י פ' ויגש עו, ד (שסז, ב): וביעקב נאמר וישא יעקב רגליו שנשא והעלה לקשר רגליו שהם עשי' ראי' ושמיעה ודיבור הגשמי מעשי' אל הרוחני, לכך נתנו לו נחלה בלי מצרים והבן."]]],[300010071,"נח\n\n<b>&lt;מבעש\"ט</b> ז\"ל&gt; <span data-k=\"sm\">[ששמעתי </span>ממורי<span data-k=\"sm\"> ביאור ש\"ס, ע\"פ שאלה,]</span> הנהו תרי בדחי, שהיו מייחדים כל עניני הגשמי לקשרו ברוחני, זולת מי שהיה בעצבות לא היה אפשר לייחדו כ\"א &lt;ע\"י&gt; שהיו מבדחו תחלה וכו' <span data-k=\"sm\">[ודפח\"ח]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>בפ</b>\"<b>י</b>,<b> ויחי פא</b>,<b> סע</b>\"<b>ג (שפו</b>,<b> ב)</b>\n<i>הנהו תרי בדחי</i> – תענית כב, א.\n----- הערות וציונים -----\nראה לעיל סי' לז ולקמן סי' צג-ג, ערב ושעה.\n<i>מי שהיה בעצבות לא היה כו'</i> – להעיר מלקו\"י ד, ב (נג) דבלא שמחה א\"א להיות דבוק בבורא ית'."]]],[300010072,"נט\n\n[<b>וכמדומה</b> <span data-k=\"sm\">ששמעתי </span>ממורי<span data-k=\"sm\"> פירש]</span> דנשקי ארעא ורקיע, לקשר ולחבר מעשה הגשמי ברוחני <span data-k=\"sm\">[וכו', ע\"ד ששמעתי </span>ממנו<span data-k=\"sm\"> או בשמו כל אשר תמצא ידך לעשות בכחך עשה, כי כאשר מקשר המעשה גשמי ברוחני]</span> עי\"ז נעשה יחוד קוב\"ה ושכינתיה <span data-k=\"sm\">[וכו', ודפח\"ח]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>בפ</b>\"<b>י</b>,<b> ויחי פב</b>,<b> א (שפח</b>,<b> ב)</b>\n<i>דנשקי כו'</i> – ב\"ב עד, א. <i>כל אשר גו'</i> – קהלת ט, י.\n----- הערות וציונים -----\nראה לעיל סי' מב-א, ולקמן סי' צא וקפט-ב."]]],[300010073,"ס\n\n<b>שקלתא</b> לסילתאי ואתנחתא בכוותא דרקיעא, &lt;פי'&gt; שביקש שיפתחו לו כוי הרקיע לענין עוה\"ב בתורה ועבודה ותפלה, וכמו ששמעתי <span data-k=\"sm\">[</span>ממורי<span data-k=\"sm\">]</span> &lt;הבעש\"ט&gt; משל שביקש &lt;א'&gt; ממלך שידבר עמו ג' פעמים ביום, וזהו שכתוב תפלה לעני כי יעטוף ולפני ה' ישפוך שיחו, ואז ניתן לו גם העושר כו', <span data-k=\"sm\">[ודפח\"ח]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>בפ</b>\"<b>י</b>,<b> ויחי פב</b>,<b> ג (שצ</b>,<b> א)</b>\n<i>שקלתא כו'</i> – ב\"ב עד, א. <i>תפלה לעני גו'</i> – תהלים קב, א.\n----- הערות וציונים -----\nראה לקמן סי' צז."]]],[300010074,"סא\n\n<b>ויחי</b> יעקב בארץ מצרים <span data-k=\"sm\">[וגו', ששמעתי </span>ממורי<span data-k=\"sm\">]</span> &lt;מהבעש\"ט&gt;, בצר הרחבת לי, כי צדיקייא אינון שלוחי דמטרוניתא להתפלל על החסרון של השכינה, וזה נודע מחסרונך <span data-k=\"sm\">[וכו']</span>. וז\"ש ויחי יעקב בארץ מצרים, ר\"ל ע\"י &lt;הגלות ו&gt;הצרות והמיצרים שהיה ליעקב ידע להתפלל מזה על חסרון השכינה שנקרא &lt;ג\"כ&gt; יעקב <span data-k=\"sm\">[כמו ששמעתי זה מפורש </span>ממורי<span data-k=\"sm\"> ויבואר במ\"א, ושפיר קאמר]</span> ויחי יעקב, שחיבר השכינה אל חי החיים, <span data-k=\"sm\">[מארץ מצרים]</span> &lt;ע\"י&gt; <span data-k=\"sm\">[שהם הצרות ו]</span>המצירים, ובצר הרחבת לי, <span data-k=\"sm\">[והבן]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>בפ</b>\"<b>י</b>,<b> ויחי פג</b>,<b> ד (שצו</b>,<b> א)</b>\n<i>ויחי יעקב גו' </i>– ויחי מז, כח. <i>בצר הרחבת לי </i>– תהלים ד, ב. <i>צדיקייא אינון כו' </i>– זח\"א רמב, א. <i>מצרים ר\"ל כו'</i> – בר\"ר טז, ד. <i>השכינה שנק' יעקב</i> – זח\"א קמה, ב. <i>ויבואר במ\"א</i> – לקמן סוף סי' פא.\n----- הערות וציונים -----\nראה לעיל סי' כ ובהערות שם.\n<i>השכינה שנק' יעקב כו'</i> – ראה ע\"ח של\"ז ספ\"ג. אוה\"ח לזח\"א קמה, ב בפי' הרח\"ו והרא\"ג. ועיין קהלת יעקב, ערך יעקב אות ה.\n<i>שחיבר השכינה כו'</i> – להעיר מזח\"א רמא, א.\n<i>חי החיים</i> – ראה תקו\"ז ת\"ט מא, סע\"ב. תס\"ט קטו, א. ורג\"כ שם תכ\"ב סז, סע\"ב."]]],[300010075,"סב\n\n<b>&lt;מהבעש\"ט&gt;</b> <span data-k=\"sm\">[ששמעתי </span>ממורי<span data-k=\"sm\"> זלה\"ה פירוש חז\"ל בפסוק]</span> הנמצא כזה איש כו', ותרגום אונקלוס הנשכח כדין, אם נלך ונבקשנו הנמצא כמוהו, אין נבון וחכם כמוך וגו', כי לחקור מי נבון וחכם צריך שיהיה זה יותר נבון וחכם שיחקור אותו, וזה לא נמצא יותר נבון וחכם מיוסף שיחקור אותו, לכך אין נבון וחכם כו' <span data-k=\"sm\">[ודפח\"ח]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>בפ</b>\"<b>י</b>,<b> ויחי פד</b>,<b> ג (ת</b>,<b> א)</b>\n<i>פירוש חז\"ל כו'</i> – בר\"ר צ, א. הובא ברש\"י עה\"פ. <i>הנמצא כזה גו' אין נבון גו'</i> – מקץ מא, לח-לט.\n----- הערות וציונים -----\nראה הגירסא בתוי\"י פ' בא מג, ב (קס, א) ששם בשנויים קלים."]]],[300010076,"סג\n\n<b>&lt;מהבעש\"ט&gt;</b> <span data-k=\"sm\">[דשמעתי </span>ממורי<span data-k=\"sm\"> זלה\"ה]</span> משל למלך שהיה לו בן ורצה ללמדו כמה מיני חכמות שצריכין לו, ושכר לו כמה חכמים שילמדו עמו והוא לא יצלח שיקבל שום חכמה עד שנתייאשו מללמדו, ונשאר חכם אחד עמו. ופעם א' ראה בן המלך איזה בתולה וחמד יפיה, והיה החכם קובל למלך על בנו בענין זה, והשיבו &lt;המלך&gt; א\"כ מאחר שיש לו חמדה אפילו הוא גם בגשמי, מזה יבוא לכל החכמות, וצוה להכניס הבתולה לחצר המלך, וצוה עליה המלך שאם יתבענה לא תשמע לו עד שיקבל חכמה אחת, וכן עשתה, ואח\"ז אמרה שילמוד עוד חכמה, עד שעי\"ז קיבל כל החכמות, וכשנעשה חכם אז מאס בבתולה הנ\"ל, כי ישא בת מלך כמותו. והנמשל מובן <span data-k=\"sm\">[ודפח\"ח]</span>. . .\n<b>אם</b> כן &lt;ע\"י&gt; <span data-k=\"sm\">[כשהיה]</span> מדה <span data-k=\"sm\">[עין]</span> רעה &lt;שיש&gt; בתלמידי אברהם אבינו <span data-k=\"sm\">[איש החסד קו ימין קו החכמה, אז ע\"י תואר חכם וחסידות שבו היה יכול לשבר הטבע ולהפכו מרעה לטובה, ואז]</span> אוכלין בעוה\"ז <span data-k=\"sm\">[ונוחלין לעוה\"ב]</span>, מה שאין כן כשיש מדה זו <span data-k=\"sm\">[עין רעה]</span> בתלמידי בלעם הרשע הרשיעו בזה יותר עד שעי\"ז יורשין גיהנם ויורדין לבאר שחת. ושפיר אמר ומה בין תלמידי א\"א כו'.",[["","","----- מקורות ומראה מקומות -----\n<b>בפ</b>\"<b>י</b>,<b> ויחי פה</b>,<b> א (תב</b>,<b> א)</b>\n<i>אברהם אבינו איש החסד קו ימין</i> – זח\"ג שב, א. <i>קו ימין קו החכמה</i> – זח\"ג רכד, א. תקו\"ז תי\"ח לב, ב. <i>ומה בין תלמידי א\"א כו'</i> – אבות פ\"ה מי\"ט.\n----- הערות וציונים -----\nראה בסמוך סי' סד.\n<i>א\"כ כשהי' מדה כו'</i> – ראה לקמן סי' סח ובהערות שם."]]],[300010077,"סד\n\n[<b>דשמעתי</b> <i>ממורי</i><span data-k=\"sm\"> זלה\"ה]</span> בשם רב<span data-k=\"sm\">[ינו]</span> סעדיה גאון שראוי לאדם שילמוד מחשק דברים גשמיים איך לחשוק עבודת הש\"י ואהבתו.<i>[ftnref_1_ז]</i>",[["","","----- מקורות ומראה מקומות -----\n<b>בפ</b>\"<b>י</b>,<b> ויחי פה</b>,<b> ב (תב</b>,<b> ב)</b>\n----- שולי הגליון -----\n[ftn_1_ז]) <i>במקורו</i>: שראוי לאדם שיחשוק בכל הדברים הגשמיים, ומתוכו יבוא לחשוק בתורה ועבודת ה' וכו', כמו משל הנ\"ל <i>(בסי' סג)</i>.\n----- הערות וציונים -----\nראה לעיל סי' סג. ומש\"כ \"וכמו משל הנ\"ל\" קאי על המשל דשם."]]],[300010078,"סה\n\n<b>&lt;מהבעש\"ט&gt;</b> <span data-k=\"sm\">[שמעתי </span><i>ממורי</i><span data-k=\"sm\">]</span> המדבק את עצמו בחלק אחד מן האחדות דבוק בכולו, והוא הדין ההיפך.",[["","","----- מקורות ומראה מקומות -----\n<b>בפ</b>\"<b>י</b>,<b> לקוטים פח</b>,<b> א (תטו</b>,<b> ב)</b>\n----- הערות וציונים -----\nראה לקמן סי' קיא-א ורנ. עיין בהוספות סי' רכז.\n<i>וה\"ה ההיפך</i> – ראה בפ\"י פ' ויצא נח, ריש ע\"ב (רפא, ב) התופס מקצת אחדות תופס כולו, וכן הדוחה מקצת אחדות דוחה כולו."]]],[300010079,"סו\n\n<b>בקשתי</b> את שאהבה נפשי בקשתיו ולא מצאתיו <span data-k=\"sm\">[וגו' . . . דשמעתי משל </span><i>ממורי</i><span data-k=\"sm\"> זלה\"ה שהיה מלך אחד שעשה כמה מחיצות וחומות זה לפנים מזה ע\"פ אחיזת עינים שהי' מסבבין את המלך, ובכל שערי החומות צוה לפזר ממון, ויותר שהיה החומה לפנים פזרו הון יותר כדי לראות זריזות וחשק בני המדינה איך כל א' מתחזק ומזרז עצמו לבוא אל המלך, ויש שחזרו אחר שקבלו ממון בשערי החומות, ויש שחזר בשער השני, ויש בשלישי וכו', ומעט מזעיר שלא נכנס בלבם חשק הגשמי לאסוף הון כי אם לבוא אל המלך, ואחר כמה טרחות שבאו אל המלך ראו שאין שום חומה ומחיצה כי אם אחיזת עינים וכו'.</span>\n<b>ו</b>]<b>הנמשל</b> מובן שהמלך הגדול <span data-k=\"sm\">[והנורא]</span> ממ\"ה הקב\"ה מסתתר בכמה &lt;לבושין ו&gt;מחיצות <span data-k=\"sm\">[וחומות של ברזל, כמ\"ש בש\"ס מיום שחרב ביהמ\"ק וכו', והמחיצות]</span> הם מ\"ז וביטול תורה ותפלה כמ\"ש בזוהר כי הטוב הגנוז מסבב אותו החשך <span data-k=\"sm\">[והקליפות]</span>, משל למלך &lt;הנ\"ל&gt; <span data-k=\"sm\">[וכו' יעו\"ש]</span>. אמנם אנשי דעת היודעים <span data-k=\"sm\">[שכל מחיצות וחומת ברזל וכל לבושין וכסויין הוא עצם מעצמותו ית']</span> דלית אתר פנוי מיניה, א\"כ אין זה הסתתרות אצלו, <span data-k=\"sm\">[כמו שכתבתי במ\"א]</span> אלופינו מסובלים, כשיודע שאלופו של עולם הוא בכל מקום אז סובל הכל <span data-k=\"sm\">[וכו' יעו\"ש ודפח\"ח]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>בפ</b>\"<b>י</b>,<b> דרוש לשה</b>\"<b>ג תקכ</b>\"<b>ה קיא</b>,<b> א</b>\n<i>בקשתי גו'</i> – שה\"ש ג, א. <i>מיום שחרב ביהמ\"ק [נפסקה חומת ברזל כו']</i> – ברכות לב, ב. <i>כמ\"ש בזוהר</i> – זח\"ג קכג, א. <i>דלית אתר כו'</i> – תקו\"ז תנ\"ז צא, סע\"ב. <i>אלופינו גו'</i> – תהלים קמד, יד.\n----- הערות וציונים -----\nמשל זה הובא בארוכה, בכמה שנויים, בס' דמ\"א פ' תבוא ושם הפטרת תבוא ופ' וילך. וראה לעיל סי' נא-ב. רג\"כ לקמן סי' פה, צח ושנה.\n<i>אלופינו מסובלים כו'</i> – פירוש זה נראה להיות מבעל בפ\"י, שכן מביאו כמה פעמים בסתמא; ראה צ\"פ פ' וארא כד, ג (צח, א): אלופינו מסובלים ר\"ל כשיודע שכל מאורעות ומוצאות הוא מהשי\"ת אלופו של עולם אז יוכל לסבול הכל וכו' וכ\"כ בשם מורי זלה\"ה כיצד מרקדין לפני הכלה וכו' (וכוונתו למש\"כ שם פו, ד (דש, א) ששמעתי ממורי זללה\"ה ביאור פלוגתא ב\"ש וב\"ה כיצד מרקדין לפני הכלה . . והעולה משם כי בידיעת האדם שידע ומאמין שהשי\"ת מכה\"כ בכל תנועה ומחשבה הכל ממנו ית' אז יתפרדו כל פועלי און וכו' יעו\"ש)."]]],[300010080,"סז-א\n\n<b>&lt;מהבעש\"ט&gt;</b> מלכות נק' דיבור, ומחשבה והכוונה נקרא בינה, וכאשר מחבר בין בעסק התורה או התפלה ב' בחינות האלו, דהיינו הדיבור עם הכוונה, אז מחבר ומקשר מלכות עם הבינה, בסוד מ\"י זא\"ת עולה מן המדבר <span data-k=\"sm\">[כמו ששמעתי </span><i>ממורי</i><span data-k=\"sm\"> זלה\"ה]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>בפ</b>\"<b>י דרוש לש</b>\"<b>ת תקכ</b>\"<b>א קטז</b>,<b> ג</b>\n<i>מלכות נק' דיבור</i> – זח\"א קמה, א. זח\"ג רכח, א. תקו\"ז תס\"ט קה, א. <i>ומחשבה והכוונה נק' בינה</i> – זח\"ג רכט, סע\"ב. זח\"א רמו, ב. <i>מי זאת גו'</i> – שה\"ש ג, ו.\n----- הערות וציונים -----\nראה לקמן סי' תה, תי, תכג-א. וראה עוד לקמן סי' קב, רפא-ב, שא-ג ושא-ד."]]],[300010081,"סז-ב\n\n<b>&lt;וכן&gt;</b> <span data-k=\"sm\">[שמעתי </span><i>ממורי</i><span data-k=\"sm\"> זלה\"ה]</span> כשהי' אחד לומד איזה משנה היה אומר לו מה שיהי' לעתיד בגשמי כמעשה שהיה <span data-k=\"sm\">[וכו']</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>בפ</b>\"<b>י</b>,<b> דרוש לש</b>\"<b>ת תקכ</b>\"<b>ז קכב</b>,<b> א</b>\n----- הערות וציונים -----\nראה תקזו\"ח צג, א מגו מלה דא דפרח מפומוי אנא חמא כו'. וראה לקמן סי' צו.\n<i>כמעשה שהיה וכו'</i> – ראה שבחי הבעש\"ט (הוצ' ירושלים תשכ\"א) ע' קכ. ועיין דרך מצותיך להצ\"צ, מצות האמנת אלקות פי\"ב. ביאורי הזוהר להצ\"צ, ח\"א פ' תרומה ע' רנח, ושם ח\"ב פ' תולדות ע' תרסד, ולפי הנראה מדובר שם על העובדא אשר בשבחי הבעש\"ט סוף עמוד עא. ויעויין בנספחים לס' שבחי הבעש\"ט הוצאת ר\"י מונדשיין ע' 7-256 ושם ע' 263. [שוב ראיתי שרוב הציטוטים הנ\"ל הובאו בהוספות סי' שלח-שמב עיי\"ש בפנים ובהערות]."]]],[300010082,"סח\n\n<b>מה</b> בין תלמידיו של אברהם אבינו <span data-k=\"sm\">[לתלמידיו של בלעם הרשע]</span> כו', והקושיא מפורסמת, וביאר <i>מורי</i> זלה\"ה, כי גם תלמידי א\"א יש להם מדות של <span data-k=\"sm\">[בלעם הרשע]</span> רוח גבוה <span data-k=\"sm\">[וכו']</span>, וה\"ה איפכא &lt;דהם&gt; <span data-k=\"sm\">[דתלמידי בלעם הרשע]</span> יש להם מדות <span data-k=\"sm\">[אברהם אבינו]</span> של נפש שפלה כו', רק שזה לוקח בגשמי וזה ברוחני <span data-k=\"sm\">[וכו' יעו\"ש]</span>.\n<b>&lt;פי'</b> תלמידי א\"א ע\"י רוח גבוה ויגבה לבו בדרכי ה' לעשות מצוות גדולות, ואלו ע\"י נפש שפלה הם שפלים בעיני עצמם שלא לעשות מצוות.&gt;",[["","","----- מקורות ומראה מקומות -----\n<b>בפ</b>\"<b>י</b>,<b> דרוש לש</b>\"<b>ת תקכ</b>\"<b>ז קכב</b>,<b> סע</b>\"<b>א</b>\n<i>מה בין כו'</i> – אבות פ\"ה מי\"ט. <i>ויגבה לבו גו'</i> – דה\"ב יז, ו.\n----- הערות וציונים -----\nעיין בס' כתנת פסים פ' צו ז, ב. וראה לעיל סי' סג.\n<i>תלמידי א\"א ע\"י רוח גבוה כו'</i> – ראה לקמן סי' רכא ושצג. וראה צ\"פ ר\"פ יתרו ס, סע\"א (רטו, ב): צריך האדם שיעשה לו עזר מפני יצה\"ר ע\"י שיעשה כנגדו היפך היצה\"ר, שאם היצה\"ר משפילו לומר אתה טפה סרוחה אשר מחומר קרצת איך אפשר שיקדש בגדר הקדושה והחסידות וכו', אז יאחז מדת הגאוה נגד היצה\"ר הלא נפשי חלק אלו\"ה ממעל ונברא בצלם אלקים וראוי ליכנס בגדר הקדושה והחסידות, וכמש\"כ במ\"א בשם מורי ביאור משנה בין תלמידי אברהם אבינו לבין תלמידי בלעם וכו' יעו\"ש."]]],[300010083,"סט\n\n[<b>ששמעתי</b> <i>ממורי</i><span data-k=\"sm\"> זלה\"ה פי' הפסוק]</span> סור מרע ועשה טוב, פירוש שיעשה מרע טוב, <span data-k=\"sm\">[ודפח\"ח]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>בפ</b>\"<b>י</b>,<b> דרוש לש</b>\"<b>ת תקכ</b>\"<b>ז קכב</b>,<b> ג</b>\n<i>סור מרע גו'</i> – תהלים לד, טו.\n----- הערות וציונים -----\nראה לעיל סי' מא ולקמן סי' פט. ולהעיר מצוה\"ר סי' קל."]]],[300010084,"ע\n\n<b>&lt;מהבעש\"ט&gt;</b> <span data-k=\"sm\">[שמעתי בשם </span><i>מורי</i><span data-k=\"sm\">]</span> וירא ה' כי סר לראות, כי <span data-k=\"sm\">[היה]</span> משה רבינו &lt;ע\"ה&gt; ירא שמא הוא קליפה, עד שאמר משה משה, אז אמר הנני. והענין, כי משה שמו כולל כל העולמות, ולכך שמו הוקשה לו. והענין, כמו שהשכינה כוללת כל העולמות דומם צומח ו<span data-k=\"sm\">[כל הנביאים</span><i>[ftnref_1_ח]</i><span data-k=\"sm\">]</span> טובים ורעים, כך אות מ' מן משה הרומז למלכות כולל כל הענינים ג\"כ. ואות ש' כולל כל הרוחות, ואות ה' הנשמות, ולכך שמו הוקשה לו, ודרשו חז\"ל מנורה שקלים החדש ר\"ת משה כו', אבל באמת שמו עצמו הוקשה לו, ששמו כולל כל מיני &lt;טוב ו&gt;רע ג\"כ, זה היה תמיה לו איך שהיחוד האמיתי היא השכינה ואיך כוללת &lt;ב' הפכים&gt; בנושא א', טוב ורע שהם ב' הפכים, והוא היחוד, וכן ג\"כ שמו משה ג\"כ כולל הכל ואיך נעשה היחוד על ידו. וזה שאמרו בש\"ס משה רבכם קוביוסטוס.\n<b>אבל</b> באמת אתי שפיר, כי הרע הוא כסא אל הטוב, כמו ופרעה הקריב כו', או ע\"י שרואה מעשה הרשעים יש לו הנאה שהוא צדיק ויש לו הנאה ותענוג, ונעשה זה בכל העולמות התענוג ע\"י הרע, וכמעט שעי\"ז יש לרע עליה ג\"כ, רק כשעולה משם יתפרדו כל פועלי און. וכן מחשבה רעה הוא כסא על דבר הנ\"ל. וז\"ש משה פעם א' לא אמר הנני, שהיה תמיה לו איך נעשה יחוד, כי כשנגלה בסנה, מדריגה תחתונה, נפתחו כל מקורות עליונות עד למטה, ומה טעמא לא יבער הסנה, שיכלו ויתבערו הרע שהוא הסנה עד שא\"ל פעם ב' משה, שנעשה עי\"ז יחוד וחיבור וקישור מדריגה תחתונה בעליונה כו', אז אמר הנני <span data-k=\"sm\">[ודפח\"ח כי קצרתי]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>בפ</b>\"<b>י</b>,<b> קו</b>\"<b>א (דברים ששמעתי ממורי) קכו</b>,<b> ג</b>\n<i>וירא ה' גו' משה משה ויאמר הנני</i> – שמות ג, ד. <i>שהשכינה כוללת כו'</i> – תקזו\"ח קב, ד. שם קיא, ב. <i>אות מ' מן משה </i>. .<i> הנשמות</i> – זח\"ב נד, א. <i>מנורה שקלים החדש ר\"ת משה</i> – זח\"ב ר\"מ קנז, סע\"ב. <i>משה רבכם כו'</i> – בכורות ה, א. <i>ופרעה הקריב</i> – בשלח יד, י. <i>שרואה מעשה הרשעים כו'</i> – בר\"ר ב, ה. <i>יתפרדו גו'</i> – תהלים צב, י. <i>מדוע לא יבער הסנה</i> – שמות ג, ג. <i>הרע שהוא הסנה</i> – ריש מכילתא דרשב\"י. שמ\"ר ב, ה.\n----- שולי הגליון -----\n[ftn_1_ח]) <i>צ\"ע</i>,<i> ונראה דצ\"ל</i>: וכל הנבראים.\n----- הערות וציונים -----\nראה לעיל סי' כו.\n<i>כי סר לראות</i> – נראה שהביאור קאי בקשר לפסוק לפני זה, וירא והנה הסנה בער באש והסנה איננו אכל, דהסנה מדריגה התחתונה כו' כדבעי למימר לקמן.\n<i>אות מ' מן משה הרומז למלכות</i> – להעיר דהרח\"ו (בהגהות לזוהר כאן, ובפי' באוה\"ח בעמוד לפני זה) מפרש בסדר הפוך: מ' אימא (בינה, רמז לנשמות) ש' זעיר (רמז לרוחות) ה' נוקבא (מלכות, רמז לנפשות). ברם בזח\"ג רלו, ב (וכן תקוזו\"ח קכ, ב) מפורש דמ\"ם פתוחה מלכות.\n<i>משה רבכם קוביוסטוס</i> – עיין דמ\"א ס\"פ כי תשא ד\"ה וראו בני ישראל.\n<i>כי הרע הוא כסא לטוב כמו כו'</i> – ראה לעיל סי' כו, ולקמן סי' קו וקפח ובהערות שם.\n<i>פעם א' לא אמר הנני כו'</i> – להעיר שבספרא ר\"פ ויקרא (פ\"א אות יא) שעל כל קריאה הי' אומר הנני כו'. ולא קשה, דכתב שם (לפני זה (אות י)) שכל הקריאות היו משה משה.\n<i>שנעשה עי\"ז יחוד כו'</i> – להעיר מזח\"ג קפז, ב. ורג\"כ זח\"א קכ, ב וזח\"ג קלח, א."]]],[300010085,"עא\n\n<b>&lt;מהבעש\"ט&gt;</b> <span data-k=\"sm\">[ושמעתי </span><i>ממורי</i><span data-k=\"sm\">]</span> בענין עבודת הש\"י, אף שאינו עולה לו לפי דעתו יכוין כי &lt;בפ'&gt; <span data-k=\"sm\">[בפעם א']</span> אשר נשבעתי באפי, כי גם כשיש ח\"ו אף, יכוין כי אלו שמנה מדריגות מבינה, ואף שהיא &lt;פ\"א&gt; <span data-k=\"sm\">[פ']</span> בו ג\"כ נתעלם אות א' אלופו של עולם, ועי\"ז נמתק האף <span data-k=\"sm\">[ודפח\"ח]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>בפ</b>\"<b>י</b>,<b> קו</b>\"<b>א קכו</b>,<b> ג</b>\n<i>אשר נשבעתי גו'</i> – תהלים צה, יא. <i>אות א' אלופו של עולם</i> – זח\"ג לא, א.\n----- הערות וציונים -----\n<i>יכוין כי (בפ') [פעם א']</i> – כונתו צ\"ע. בס' בעש\"ט פ' משפטים הגה ח' מציע דקאי על מש\"כ בסימן לפני זה (ששניהם באים בסמיכות בבפ\"י) פעם א' לא אמר כו' דאיירי בבחי' קטנות כו' עיי\"ש. ואולי צ\"ל פ\"א, כדלקמן בסימן זה והמדפיס שנה את זה ל\"פעם א'\".\n<i>ח' מדריגות מבינה ואף שהיא פ'</i> – גם זה צ\"ע, ואולי כוונתו שבינה איהי תמינאה דספיראן מתתא לעילא ובגין דא אתקריאת ח' (זח\"ג רמה, ב. זו\"ח יתרו לד, סע\"ד), וכמ\"ש בקהלת יעקב ערך פ' אות ז וז\"ל: פ' נ\"ל שהוא בבינה כי היא כוללת ז' ספירות שתחתיה ועם כללות עצמותה הרי ח' וכ\"א כלול מיו\"ד כנודע הרי פ' כו' עיי\"ש.\n<i>ואף שהיא פ' בו ג\"כ נתעלם אות א'</i> – הא' דמלוי פ\"א.\n<i>נתעלם אות א' אלופו של עולם</i> – ראה לקמן סי' פה, רפח ושנה. והשוה לעיל סי' סו."]]],[300010086,"עב\n\n<b>בענין</b> מחשבות יש כמה מיני מחשבות טובים ורעים, ובתוך שקר יש אמת, כי מספר שקר ת\"ר ובו מובלע אמת שהוא תמ\"א, והבן.",[["","","----- מקורות ומראה מקומות -----\n<b>בפ</b>\"<b>י</b>,<b> קו\"א קכו</b>,<b> ג</b>\n----- הערות וציונים -----\nבמקורו זה בא בהמשך לסי' עא כמש\"כ כאן, אבל לכאורה אין קשר ביניהם וצ\"ל ענין בפ\"ע. ועיין בס' דברי תורה לבעל מנח\"א, מהד\"ט אות נב מה שכתב בביאור ענין זה. ובס' בעש\"ט על התורה פ' משפטים הג' ט באופן אחר."]]],[300010087,"עג\n\n<b>&lt;מהבעש\"ט</b> ז\"ל&gt; <span data-k=\"sm\">[ושמעתי </span><i>ממורי</i><span data-k=\"sm\">]</span> בענין משל שהי' למלך ג' אוהבים ודברו עליהם שאינם אוהבים, וצוה להם שיזונו ויפרנסו כל א' כלב מחצר המלך, א' היה חכם ועשה עטרה למלך מההוצאה שהיה ראוי שיוציא על פרנסת הכלב, ב' פירנס וזן בדוחק את הכלב שלא ימות, ג' השגיח לזונו בריוח ועי\"ז גירה המלך הכלב בו, משא\"כ לזה שעשה עטרה <span data-k=\"sm\">[וכו' ודפח\"ח]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>בפ</b>\"<b>י</b>,<b> קו</b>\"<b>א קכו</b>,<b> ריש ע</b>\"<b>ד</b>\n----- הערות וציונים -----"]]],[300010088,"עד\n\n[<b>ושמעתי</b> <i>ממורי</i><span data-k=\"sm\">]</span> בענין כל הנוטל מלכות לבד <span data-k=\"sm\">[וכו']</span>, כי כל הדברים הניכרים נק' מלכות, ושאינו מושג הוא למעלה מן המלכות, וצריך להבין שיש למעלה ממנה וכו'.",[["","","----- מקורות ומראה מקומות -----\n<b>בפ</b>\"<b>י</b>,<b> קו</b>\"<b>א קכו</b>,<b> ד</b>\n<i>כל הנוטל מלכות לבד</i> – תקו\"ז תס\"ט קיז, ב.\n----- הערות וציונים -----\nראה לעיל סי' מו-ב. להעיר מזח\"ב רכז, ב."]]],[300010089,"עה\n\n<b>&lt;מהבעש\"ט&gt;</b> <span data-k=\"sm\">[שמעתי בשם </span><i>מורי</i><span data-k=\"sm\">]</span> איך יתפלל על שונאו, והתועלת היא זה כי שבע יפול צדיק וקם, ר\"ל בז' ספירות נתגלגל נר\"ן שלו. דהיינו נפש הם עבדים והבהמות שלו. ורוח היא אשתו, והדיבור הוא ג\"כ זווג שבפה שנק' אשתו, זכה עזר לא זכה כנגדו, דהיינו שפגם בדבורו כגון לה\"ר וכיוצא <span data-k=\"sm\">[מזה]</span> נעשו &lt;ממנו&gt; אנשים שונאיו המדברים עליו. ופגם שבמוח במחשבה גורם שיש לו צער מבניו. ובנפש ג\"כ אם פגם במעשיו ובעובדא גורם לו צער מעבדיו ובהמתו. ובכל הספירות יכול להעלות נר\"נ, משא\"כ בספירה שביעית, היא במלכות, ומשם יונקים הקליפות נוגה קשה לו להעלות נר\"נ שם. נמצא &lt;אויבים&gt; <span data-k=\"sm\">[שונאיו]</span> שבאו &lt;לו&gt; ע\"י פגם הדיבור צריך לתקנם להעלותם ע\"י דיבור התפלה, ובאם לאו, שדוחה אותם, נעשו יותר שונאים ע\"י עביות וחומריות. לכך גם ענוש לצדיק לא טוב, כי הוא רוחו של צדיק עצמו. לכך צריך להתפלל על שונאיו לתקנם ולהעלותם, וע\"י התפלה נמתק בשרשו ומוציא מהם רוחו, ומה שנשאר בהם הם כלים מאליהם, ישמע חכם ויוסיף לקח <span data-k=\"sm\">[ודפח\"ח]</span>.\n<b>וזהו</b> ענין מעלת מרע\"ה שהעלה ותיקן דבורו, ותחלה היו צאן שהיה רועה אותן, ואחר כך בגלגול נעשו תלמידיו שנתן להם התורה ולמד עמהן וכו' <span data-k=\"sm\">[ודפח\"ח]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>בפ</b>\"<b>י</b>,<b> קו</b>\"<b>א קכו</b>,<b> ד</b>\n<i>כי שבע גו'</i> – משלי כד, טז. <i>זכה עזר כו'</i> – יבמות סג, א. <i>במלכות ומשם כו'</i> – ע\"ח שמ\"א פ\"ב. <i>גם ענוש גו'</i> – משלי יז, כו. <i>הם כלים מאליהם</i> – גיטין ז, א. <i>ישמע חכם גו'</i> – משלי א, ה.\n----- הערות וציונים -----\nדרוש זה הובא ג\"כ בצ\"פ פ' שמות ז, ד (מ, א) בשנויים קלים וכמה הוספות.\n<i>איך יתפלל על שונאו</i> – ראה לעיל סי' יח ובהערות שם.\n<i>נר\"ן</i> – למבואר לקמן שהם כנגד מחשבה דיבור ומעשה ראה זו\"ח יתרו לד, ב. תקו\"ז תכ\"ב סח, סע\"ב.\n<i>ורוח הוא אשתו</i> – בצ\"פ: והרוח ממללא הוא הדיבור.\n<i>והדיבור הוא ג\"כ כו'</i> – בצ\"פ: ונודע כי הדיבור נקרא זוו\"ג וז\"ש חז\"ל (כתובות יג, א) ראוה מדברת וכו' (ראה ע\"ח שט\"ז ספ\"ד, וראה לעיל סי' לב-ב), א\"כ אשתו היא רוח ג\"כ, זכה כו'.\n<i>ופגם שבמוח במחשבה</i> – בצ\"פ: הנשמה שוכנת במוח שמזה נעשה טיפה זרעית והם מבניו (להעיר מזח\"א קפא, ב והג' החיד\"א שם) ואם פגם במחשבה שבמוח כו'.\n<i>ומשם יונקים הק\"נ</i> – ראה ע\"ח שמ\"א פ\"ב ושמ\"ט פ\"ג.\n<i>צריך לתקנם כו'</i> – בצ\"פ: לכן צריך להעלותן ולתקנם ע\"י דיבור התפלה להתפלל עליהם שישובו ויתוקנו, וכמו שאיתא בש\"ס דברכות (י, א) דר' מאיר וברוריא אתתיה יתמו חטאים (תהלים קד, לה) ולא חוטאים, ואם אינו עושה כך רק שדוחה אותן נעשו חומריות ועב יותר ושונאים אותו יותר, וזהו שאמרו חז\"ל (ברכות ז, א) ענוש לצדיק לא טוב.\n<i>וזהו ענין כו'</i> – בצ\"פ כלל כל זה בדברי הבעש\"ט, ובזה מובן מש\"כ כאן בסופו ודפח\"ח."]]],[300010090,"עו\n\n[<b>שמעתי</b> <span data-k=\"sm\">בשם </span><i>מורי</i><span data-k=\"sm\">]</span> סוד עירוב אלפים אמה כו', כי אין להקב\"ה בעולמו אלא ד' אמות של הלכה, והענין, כי בכל דבר שבעולם יש בו ג' שמות אדנ\"י הוי\"ה ואהי\"ה, כמו בית נק' אדנ\"י, ומה שמהוה ממנו כגון שיש לו הנאה מבית מקושט וכיוצא נק' הוי', ואור המקיף הבית להציל &lt;מן ה-&gt; <span data-k=\"sm\">[מכל]</span> קליפה נקרא אהי\"ה. &lt;מבעש\"ט&gt;.",[["","","----- מקורות ומראה מקומות -----\n<b>בפ</b>\"<b>י</b>,<b> קו</b>\"<b>א קכז</b>,<b> א</b>\n<i>עירוב אלפים אמה</i> – עירובין נא, א. <i>אין להקב\"ה כו'</i> – ברכות ח, א.\n----- הערות וציונים -----\n<i>וסוד עירוב כו' ד' אמות כו'</i> – להעיר מעירובין שם: שבו איש תחתיו אלו ד' אמות, אל יצא איש ממקומו אלו אלפים אמה.\n<i>בכל דבר שבעולם כו'</i> – ראה לקמן סי' קנ."]]],[300010091,"עז\n\n<b>&lt;מהבעש\"ט&gt;</b> ביאור משנה דאבות <span data-k=\"sm\">[פ\"ב]</span> הוי זהיר בגחלתן כו' כגחלי אש. <span data-k=\"sm\">[ושמעתי </span><i>ממורי</i><span data-k=\"sm\">]</span> כי קודם הלימוד אמרו מלתא דבדיחותא <span data-k=\"sm\">[וכו']</span>. והענין, כי יש קטנות וגדלות בעולם שנה נפש, וע\"י מלתא דבדיחותא עולה מן הקטנות ומתדבק בגדלות. והנה בזמן הגדלות שבעולם אז הוא דבוק בו ית' כפשוטו, משא\"כ בימי הקטנות שיש בעולם אז צריך האדם מלחמה גדולה שיוכל להתקרב אליו ית'. וזהו עיקר השכר שיש לאדם שעושה על צד ההכרח, גם שלא יוכל לעשות הטוב בפועל, מ\"מ בלבי צפנתי אמרתיך, ובחוץ יעשה ענינים גשמיים. וז\"ש חז\"ל תורה ומלאכה שיגיעת שניהם משכחת עון, וכיוצא בזה, וכשבא איזה תלמיד להרב בימי הקטנות ולומד ממנו דברים גשמיים הנק' גחלת בלי אור פנימי.\n<b>וז\"ש</b> והוי זהיר בגחלתן כו' עקרב, ר\"ל &lt;עקרב&gt; ז' מדריגות &lt;הנ\"ל&gt; הנק' ע', הוא מקרב לשרשן, וזה אינו יודע מזה <span data-k=\"sm\">[וסובר]</span> וכו' <span data-k=\"sm\">[ודפח\"ח]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>בפ</b>\"<b>י</b>,<b> קו</b>\"<b>א קכז</b>,<b> א</b>\n<i>הוי זהיר כו'</i> – אבות פ\"ב מ\"י. <i>קודם הלימוד אמרו כו'</i> – שבת ל, ב. <i>בלבי צפנתי גו'</i> – תהלים קיט, יא. <i>תורה ומלאכה כו'</i> – אבות פ\"ב מ\"ב.\n----- הערות וציונים -----\nראה לקמן סי' שסו באורך. ורג\"כ סי' רמד.\n<i>מלתא דבדיחותא כו'</i> – ראה לעיל סי' לז ובהערות שם.\n<i>שעושה על צד ההכרח כו'</i> – ראה לעיל סי' מז. להעיר משמנה פרקים פ\"ו עיי\"ש.\n<i>עקרב</i> – מבואר יותר בסוף סי' שסו."]]],[300010092,"עח-א\n\n<b>&lt;מבעש\"ט&gt;</b> <span data-k=\"sm\">[ושמעתי </span><i>ממורי</i><span data-k=\"sm\">]</span> פי' הש\"ס השוחט דעלמא חייב משום צובע, וחד אמר משום נטילת נשמה <span data-k=\"sm\">[ופריך משום צובע כו' אלא אף משום נטילת נשמה]</span> כו'. כי היצה\"ר נידון לע\"ל, וקשה הא לכך נברא, וצ\"ל שעושה עצמו ליצה\"ט כו'. ובזה יובן השוחט דעלמא חייב, וקשה הא לכך נברא, ומשני משום צובע, שהוא צבוע בדמות יצ\"ט, ועי\"ז נוטל נשמה. ופריך כו', ומשני אף נטילת נשמה <span data-k=\"sm\">[ודפח\"ח]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>בפ</b>\"<b>י</b>,<b> קו</b>\"<b>א קכז</b>,<b> א</b>\n<i>השוחט דעלמא כו'</i> – שבת עה, סע\"א ובתוס' שם ד\"ה שוחט. <i>היצה\"ר נידון לע\"ל</i> – סוכה נב, א\n----- הערות וציונים -----\n<i>הא לכך נברא</i> – ראה זח\"ב קסג, א.\n<i>שהוא צבוע כו'</i> – ראה לקמן סי' עח-ב וסי' קיד."]]],[300010093,"עח-ב\n\n<b>&lt;וז\"ש</b> היצה\"ר דברי פיו און, שהם עבירות שנק' און ומרמה, פי' מרמה את האדם לומר שהוא מצוה, ועי\"ז חדל להשכיל להיטיב, פי' אינו עושה תשובה, כי מי עושה תשובה על עשיית מצות.",[["","","----- מקורות ומראה מקומות -----\n<b>קיצור מלקו</b>\"<b>י יז</b>,<b> ב (סי</b>'<b> ר) [צוה</b>\"<b>ר סי</b>'<b> עד]</b>\n<i>דברי פיו גו' חדל גו' און יחשב גו' יתיצב גו'</i> – תהלים לו, ד-ה.\n----- הערות וציונים -----\nראה לעיל עח-א, ולקמן סי' קיד. וראה צוה\"ר סי' קיז ושם סי' קכד."]]],[300010094,"(עט)\n\n<b>און</b> יחשוב על משכו, בחליו מפתהו היצה\"ר שיתפלל שיעזור לו ה' עבור אותן מצות, אבל באמת יתיצב על דרך לא טוב כו'&gt;<i>[ftnref_1_ט]</i>.",[["","","----- מקורות ומראה מקומות -----\nראה מקבילות לעיל סימן עח-ב.\n----- שולי הגליון -----\n[ftn_1_ט]) <i>מד\"ה וז\"ש היצה\"ר עד סוף סי' עט הוא קיצור המובא בלקו\"י יז</i>,<i> ב (סי' ר) – ומקבילו בצוה\"ר סי' עד – וז\"ל שם</i>:\nדברי פיו און ומרמה חדל להשכיל להטיב כו'. כי יש ב' מיני אדם, א' שהוא רשע גמור שיודע רבונו ומכוין למרוד בו, והשני הוא שיצה\"ר מסמא את עיניו ומדמה לו בעיניו שהוא צדיק גמור, וגם בעני הבריות נראה שהוא צדיק גמור. ובאמת אף שהוא לומד בתמידות, ומתפלל ומסגף א\"ע, לריק יגיעו, כי אין לו דביקות בבורא ית' ואמונה שלימה כראוי להיות דבוק בו ית' בכל עת, ואינו יודע איך עיקר העבודה כמו שראוי ללמוד ולהתפלל ולעשות מצוה לשמה.\nוהחילוק ביניהם, כי הרשע גמור אפשר שיהיה לו תעלה ורפואה למכתו כשיבוא לו התעוררות התשובה, ושב אל ה' בכל לבו ויבקש מהשי\"ת שיורוהו בדרך ישכון אור, אבל הב' אין לו שום תקנה, כי טח עיניו מראות את הבורא ית' וגדולתו ועבודתו, וצדיק הוא בעיני עצמו, ואיך ישוב בתשובה.\nומזה הטעם כשיצה\"ר מפתה את האדם לעבירה על פי רוב מראה לו כאלו עשה מצוה כדי שלא ישוב לעולם.\nוזהו הרמז דברי פיו און ומרמה, שהיצה\"ר מרמה את האדם בעבירה שנראה לו שעושה מצוה, ולמה חדל להשכיל להטיב, שיחדול מלשוב לעולם כנ\"ל.\nוגדולה מזו, און יחשוב על משכבו, ר\"ל עוד גם בזה מרמה אותו, כשאדם נופל למשכב הוא מתפלל אל השי\"ת שירפאו מחליו על ידי תורתו ומצותיו שעשה, ואינו יודע שמזכיר עונותיו, שהכל היה פתוי היצר הרע.\n----- הערות וציונים -----\nראה הערות וציונים לעיל סימן עח-ב."]]],[300010095,"פ\n\n<b>&lt;מבעש\"ט&gt;</b> <span data-k=\"sm\">[שמעתי </span><i>ממורי</i><span data-k=\"sm\">]</span> ענין התפלה בח\"ל, העיקר הוא האמונה שיאמין שהש\"י מלא כל הארץ כבודו <span data-k=\"sm\">[וכו']</span>, ועי\"ז מעלה ומנשא <span data-k=\"sm\">[רגלי]</span> השכינה כו', וגם יאמין מיד כשיצא מפיו נוסח התפלה מה ששואל, מיד הוא נענה. וכ\"ת הא לפעמים שלא מצא מבוקשו, הענין הוא שהוא בהעלם ממנו, למשל שנעשה בקשתו בכללות העולם, הגם שבפרטות הוא מבקש להסיר הצער, ובאמת הוא לטובתו או למרק עון או כיוצא כו'. כי אם &lt;יש&gt; בכוונת שאלתו שמצפה שיהיה נענה, אז מכניס גופניות בתוך שאלתו שהיה ראוי שיהיה רק ברוחני לתועלת השכינה ולא לתועלת עוה\"ז, לכך הוי מסך מבדיל כו'. <span data-k=\"sm\">[והאריך בזה, ודפח\"ח]</span>.\n<b>&lt;וז\"ש&gt;</b> <span data-k=\"sm\">[ובזה מובן]</span> וישא יעקב רגליו, שהוא רגלי השכינה, על ידי האמונה ובטחון בלב כמ\"ש חזקו ויאמץ לבבכם <span data-k=\"sm\">[וכו']</span> וז\"ש שנשאו לבו משהובטח, והבן.",[["","","----- מקורות ומראה מקומות -----\n<b>בפ</b>\"<b>י</b>,<b> קו</b>\"<b>א קכז</b>,<b> סע</b>\"<b>א</b>\n<i>מלא כל גו'</i> – ישעי' ו, ג. <i>למרק עון</i> – ברכות ה, א. יומא פו, א. <i>וישא יעקב גו'</i> – ויצא כט, א. <i>חזקו גו'</i> – תהלים לא, כה. <i>שנשאו לבו כו'</i> – בר\"ר ע, ח.\n----- הערות וציונים -----\n<i>התפלה בח\"ל</i> – פענוח \"בח\"ל\" צ\"ע. אולי צ\"ל התפלה בחול, לעומת תפלה בשבת, דהתחלת המאמר בבפ\"י שם: וישב יעקב בארץ וגו' ונבאר ש\"ס (שבת קיח, ב) כל המענג שבת נותנין לו משאלות לבו וכו' והקשה הגאון (כונתו להגאון מהו' העשיל, כמש\"כ במפורש לפני זה בדרוש לשה\"ג תקכ\"ז דף קז, ג, וכן בצ\"פ פ' בא לו, ג, ונמצא בס' חנוכת התורה – קובץ חידושי הר\"ר העשיל – אות קצז) הא אמרינן איך אדם מת וחצי תאותו וכו' (קה\"ר א, יג ושם ג, י), ונבאר פסוק וישא יעקב רגליו מפרש נשאו לבו משהובטח וכו' (בר\"ר ע, ח וברש\"י ויצא כט, א), שמעתי ממורי (כבפנים). וי\"ל בדרך אפשר דזה ע\"פ הא דנקטינן דאסור לתבוע צרכיו בשבת (ירושלמי שבת פט\"ו ה\"ג. ויק\"ר סוף פל\"ד), דמדובר בסימן זה על בקשת צרכיו. ולהעיר עוד מהמבואר בתקו\"ז תכ\"א מה, ב ובפע\"ח שער התפלה פ\"ז בענין תפילת ימי החול לעומת תפילה בשבת וכו'.\n<i>האמונה שיאמין כו'</i> – ראה לעיל סי' לט ובצוה\"ר סי' נח וקלז. וראה דמ\"א ר\"פ עקב.\n<i>וגם יאמין כו' מיד הוא נענה</i> – ראה לקמן סי' פא, קלח, קמה וריד. וראה כאן בהמשך.\n<i>לפעמים שלא מצא מבוקשו הענין הוא כו'</i> – עיין ס' העיקרים מ\"ד פכ\"ד. בית אלקים להמבי\"ט, שער התפילה פי\"ז. ועיי\"ע לקמן סי' קלח, וצוה\"ר סי' קכג. מדל\"י סי' קמה. לקו\"י ח, ד (סי' קכג). ודמ\"א פ' עקב רד\"ה לא יהיה בך עקר, ושם ס\"פ תצא, הפטורת תצא ד\"ה או יאמר רני (ושם ע\"פ המבואר לקמן סי' קלח).\n<i>כי אם כו' הוי מסך כו'</i> – ראה לקמן סי' קעו. צוה\"ר סי' עג. לקו\"י ח, ד (סי' קכג).\n<i>לתועלת השכינה</i> – ראה לעיל סי' כ ובהערות שם. כאן המקום להעיר מדברי הבעש\"ט המובאים בסו\"ס דמ\"א (באלה הדברים אשר שמעתי מפי אא\"ז זללה\"ה): ביאר קושיא בזוהר (תקו\"ז ת\"ו כב, א) כתיב צווחין ככלבין הב לן מזונא וכו' ובמאמר א' (זח\"ב סב, א) מפורש מאן דלא מתפלל על פרנסה בכל יום הוא מקטני אמונה; ותירץ כי כל דבר חסרון שיש לאדם מרגיש החיות, נמצא כשמתפלל על איזה חסרון, דרך משל שחסר לו פרנסה, ומי מרגיש החסרון הלא החיות שלו (עיי\"ש בדמ\"א ר\"פ בחקותי) והחיות הוא מן השכינה, ולכן יתפלל על צער החיות שהיא השכינה ממש, ובזה מתורץ קושיא הנ\"ל.\n<i>וז\"ש וישא יעקב כו'</i> – ראה לעיל סי' מב.\n<i>שהוא רגלי השכינה</i> – ראה לעיל סי' סא ולקמן סוף סי' פא."]]],[300010096,"פא\n\n<b>&lt;מהבעש\"ט&gt;</b> <span data-k=\"sm\">[שמעתי </span><i>ממורי</i><span data-k=\"sm\">]</span> פירש פסוק וישלח יעקב מלאכים. <span data-k=\"sm\">[גם]</span> הקשה, בימות המשיח שיבטלו הצרות וכל ענינים שצריך להתפלל עליהם, א\"כ התפלה שהוא אבר השכינה וכי ח\"ו אפשר לבטלה <span data-k=\"sm\">[וכו']</span>. גם הקשה ע\"פ בימים ההם יבוקש את עון ישראל ואיננו ואת חטאת יהודה, ויש להבין למה יבוקש, וכי צריך לעון בית ישראל.\n<b>ופירש,</b> כי יש ד' סוגי התפלה, א' שצר לו על כבודו ית' שנתחלל בין אומות העולם ומתפלל <span data-k=\"sm\">[וכו']</span>, ב' על עונות, כי הצרה הוא העון עצמו, וגם העבירה חמורה ממיתה, כי המיתה מכפרת וממרקת עון, משא\"כ העון גורם כמה מיתות וכריתות <span data-k=\"sm\">[וכו']</span>, ג' התפלה על הפרנסה <span data-k=\"sm\">[וכו']</span>, ד' על חיים.\n<b>והנה</b> איברי השכינה מעוטף בד' עניני הצער הנ\"ל כדי שידע ויתפלל ויפרד הגשמיים ויעלה ניצוצי השכינה הפנימי למעלה <span data-k=\"sm\">[וכו']</span>, משא\"כ בדליכא ד' סוגי הנ\"ל אינו יודע על מה להתפלל. וז\"ש יבוקש עון בית ישראל, כדי שיתפלל עליו, ואיננו, וגם חטאת וחסרון שאר סוגים הנ\"ל ולא תמצאנה על מה להתפלל, כ\"א שיהיה התפלה דרך יחודים. כי כל מעשים גשמיים שנעשה בעולם הכל נרמז בתורה, והוא ג\"כ בעולם האצילות. גם שכ' בזוהר שהוא דרך משל <span data-k=\"sm\">[וכו']</span> היינו ג\"כ עד\"ז. והעיקר האמונה שיאמין כי דרך דבורו ותפלה הוא נעשה כך מיד בלי שום ספק <span data-k=\"sm\">[וכו']</span>.\n<b>ובזה</b> יובן וישלח יעקב, השכינה. כי י' הוא גולמי שנתלבש בז' ימי הבנין שהוא ע', כל אחד כלול מי', ובאמת עשר ספירות כל אחד כלול מן י' הוא ק', והכל ע\"י הבינה שהוא ב'. מלאכים, כמ\"ש בכתבים מלאכים המוני מעלה כו'. אל עשו אחיו, הוא עולם העשיה כו' <span data-k=\"sm\">[ודפח\"ח]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>בפ</b>\"<b>י</b>,<b> קו</b>\"<b>א קכז</b>,<b> ב</b>\n<i>וישלח יעקב גו' אל עשיו אחיו</i> – וישלח לב, ד. <i>התפלה שהוא אבר השכינה</i> – זח\"א כד, א. שם רנג, א-ב. <i>בימים ההם יבוקש גו'</i> – ירמיה נ, כ. <i>העבירה חמורה ממיתה</i> – ספרי תצא פ' רנב. תנחומא ורבה לפנחס כה, יז. <i>המיתה מכפרת כו'</i> – יומא פו, א. <i>שכ' בזוהר</i> – ר' זח\"א קלה, א. <i>יעקב השכינה</i> – זח\"א קמה, ב. <i>ע\"ס כ\"א כלול כו'</i> – זח\"ב ר, א. תקו\"ז תי\"ז לא, א. שם תמ\"ב פד, א. תס\"ט קטז, ב. <i>כמ\"ש בכתבים כו'</i> – תקו\"ז טז, ב. פע\"ח שער השבת פ\"כ. שה\"כ ענין מוסף של שבת.\n----- הערות וציונים -----\n<i>איברי השכינה מעוטף כו'</i> – ראה לעיל סי' פ ובהערות שם.\n<i>חטאת וחסרון</i> – כלו' חטאת הוא לשון חסרון כפרש\"י למ\"א א, כא.\n<i>כ\"א שיהיה התפלה דרך יחודים</i> – ראה תניא אגה\"ק סי' כו (דבזה\"ז עיקר עסק התורה והמצוות הוא לברר הניצוצות, אבל לעת\"ל לא יהיה עסק התורה והמצוות לברר בירורין כ\"א ליחד יחודים כו').\n<i>כל מעשה גשמיים כו'</i> – ראה זח\"א קלד, ב.\n<i>והעיקר האמונה כו'</i> – ראה לעיל סי' פ.\n<i>יעקב השכינה</i> – ראה לעיל סי' סא.\n<i>עשיו </i>. .<i> עולם העשיה</i> – להעיר מפירוש עשו לשון עשוי (ראה רש\"י ורשב\"ם, ומדרש לקח טוב, לתולדות כה, כח)."]]],[300010097,"פב\n\n<b>&lt;מהבעש\"ט&gt;</b> <span data-k=\"sm\">[שמעתי </span><i>ממורי</i><span data-k=\"sm\">]</span> פירוש הענין בחטא א' שחטא אדם נזדמן לו חטא אחר כדי שישוב ממנו, עי\"ז יהיה כפרת חטא א'. וכשרואה יצה\"ר כך, מתגבר עליו בחטא ב', ומ\"מ הש\"י מליץ בעדו. על שלשה פשעי ישראל כו', וכאשר חטא ג\"פ אז נתלבש נפשו רוחו ונשמתו בקליפות, ועבירה גוררת עבירה, ודרכי התשובה נמנע ממנו עד שירוחם משמים.\n<b>וז\"ש</b> הנביא נחפשה דרכינו ונחקורה ונשובה אליך וכו' כי אחר שנעשה הכל כ&lt;דרך&gt; מישור בעיניו ע\"י כי השמן לב העם הזה, וצריך חיפוש וחיקור שידע שחטא, אז ישוב עדיו ית', וק\"ל.",[["","","----- מקורות ומראה מקומות -----\n<b>בפ</b>\"<b>י</b>,<b> קו</b>\"<b>א קכז</b>,<b> סע</b>\"<b>ב</b>\n<i>על שלשה גו'</i> – עמוס ב, ו. <i>ועבירה גוררת כו'</i> – אבות פ\"ד מ\"ב. <i>נחפשה גו'</i> – איכה ג, מ. <i>השמן גו'</i> – ישעי' ו, י.\n----- הערות וציונים -----\n<i>נזדמן לו חטא אחר כדי שישוב כו'</i> – להעיר מתוי\"י פ' וארא לט, א (קמד, ב): ששמעתי ממורי בלומד דבר עמוק ואין מבין הוא מלכות, וכשנתן דעת להבין וירד לעומקו אז קישר וחיבר מלכות בבינה ודפח\"ח (ע\"כ הובא לקמן סי' קב, ובמקורו ממשיך:) ישמע חכם ויוסף לקח שאם נזדמן לו שוגג יתן דעתו שכבר עבר מזיד ולא תיקנו ועכשיו בא לזה שיתן דעתו לתקנו.\nלהעיר מתנחומא ויקרא ו בפסוק גם בלא דעת נפש לא טוב גו', מבואר בר\"ח שער היראה פ\"ד, (והובא בעץ יוסף על התנחומא שם) ששם באופן אחר.\n<i>על ג' פשעי ישראל כו'</i> – ראה יומא פו, ב. רמב\"ם הלכות תשובה פ\"ג ה\"ה ובנו\"כ שם.\n<i>וכאשר חטא ג' פעמים כו'</i> – ראה זח\"א עג, ב ובאוה\"ח והג' החיד\"א שם. ועיי\"ע זח\"ג קא, א והג' החיד\"א שם. וראה תניא, אגה\"ת פ\"ג.\n<i>אחר שנעשה הכל כמישור בעיניו כו'</i> – ראה לעיל עח-ב."]]],[300010098,"פג\n\n<b>&lt;מהבעש\"ט&gt;</b> <span data-k=\"sm\">[שמעתי </span><i>ממורי</i><span data-k=\"sm\">]</span> יום ליום יביע אומר ולילה ללילה יחוה דעת, כי תחילת דינו של אדם על ביטול תורה שנאמר פוטר מים ראשית מדון <span data-k=\"sm\">[וכו']</span>, אפס שסובר שיוכל לפטור מהדין עבור טרדת פרנסה ביום, ובלילה שובת מטרדתו, אך דיום החורף מכריעו כו' וליל הקיץ סותר וכו', <span data-k=\"sm\">[וז\"ש וכו', ודפח\"ח]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>בפ</b>\"<b>י</b>,<b> קו</b>\"<b>א קכז</b>,<b> ג</b>\n<i>יום ליום גו'</i> – תהלים יט, ג. <i>תחילת דינו כו'</i> – קידושין מ, ב. <i>פוטר מים גו'</i> – משלי יז, יד.\n----- הערות וציונים -----\n<i>אפס שסובר כו'</i> – להעיר מזח\"ב סג, א, וראה ר\"ח שער הקדושה פ\"ג."]]],[300010099,"פד\n\n<b>המכיר</b> את מקומו והשמח בחלקו והעושה סייג לדבריו. וקשה, איך שייך זה לקנין תורה להכיר מקומו. וגם במ\"א ארז\"ל איזהו עשיר השמח בחלקו. עוד קשה סייג מהו.\n<b>וי\"ל</b> דאנו אומרים בקדושה דשבת ויו\"ט וז\"ל כבודו מלא עולם משרתיו שואלים זה לזה איה מקום כבודו לעומתם משבחים ואומרים, וקשה, כיון דאמרנו כבודו מלא עולם, איך שייך תו השאלה איה מקום כבודו, וגם דשאלת איה בלא\"ה אינו שייך אל הבורא ית\"ש, דבחובות הלבבות &lt;איתא&gt; ונשאל קצת החכמים כו' ואנה הוא, א\"ל בצפיה ע\"ש.\n<b>וי\"ל</b> דבס' הקנה וירא אלקים את האור כי טוב, שאלו לר' מהו הפי' טוב, א\"ל אליהו ז\"ל אמר בפיו בהטיבו את הנרות תרגומו באדלקותיה, והנה כונת הענין כמדליק מנר לנר, וק' הלא הקב\"ה מוציא אורה מאין תמורה, פי' דאדם כשרואה בלילה שיכבה הנר מדליק נר אחר ממנו והוא תמורה של נר א', וזהו הוצאת יש מיש, אבל הקב\"ה מוציא אורה של אור הראשון יש מאין שזהו מאין תמורה, וא\"כ איך אמר כי טוב כמדליק נר מנר.\n<b>וי\"ל,</b> דבסוף הפ' דרז\"ל וירא אלקים את האור כי טוב ויבדל, ראה הקב\"ה שאין העולם כדאי להשתמש באור הראשון וגנזו לצדיקים לעתיד לבוא. והקשה הרב הקדוש מו' דוב בער זלה\"ה בשם <i>רבו</i> היכן גנזו, דהרי חמה ולבנה וכוכבים ומזלות גם כן אינם ברקיע א' ואפ\"ה נראים דרך זהר הרקיע, ואע\"פ דנר גשמי אפשר לגנוז האור ע\"י שגונז הנר מפני שהוא אויר הנתפס בשלהבת ובנר. אך כמו שאמר בתיקונים על הא\"ס לית מחשבה תפיסא ביה כלל, ופי' בס' הקנה דא\"ל מט\"ט למרע\"ה מפני שכל דבר שנתפס בהרהור המחשבה הוא נכלל בשש קצוות א\"כ הוא מוגבל, וכל מוגבל הוא מחובר ומחודש, פי' כי כמו שהאדם הוא בעל מדה כן כל דבר הנתפס במחשבתו הוא מוגבל ובעל מדה, ומוגבל בשש קצוות הוא מחובר, כי ע\"כ ארז\"ל אין למעלה לא מעלה ולא מטה ימין ושמאל פנים ואחור לא עורף ולא עיפוי, כי ע\"כ בדבר מוגבל זה מעלה מפני שנוטה ליסוד אש וזה מטה מפני שנוטה ליסוד עפר, ימין מיסוד המים שמאל מיסוד הרוח, וא\"כ כל מוגבל הוא מחובר, שדברים אשר חובר מהם קודמים לו הקדמה טבעית ומחברו קודם לו הקדמה זמנית וטבעית, א\"כ צ\"ל דהא\"ס לית מחשבה תפיסא ביה כלל, דאי לא תימא הכי א\"כ הוא מחובר ומחודש ואיננו קדמון, כן אור הראשון כ' בס' יצירה וחצב עמודים גדולים מאויר שאינו נתפס, א\"כ איך אפשר לגנזו.\n<b>ותירץ,</b> דאורה זו תורה. מתחלה רצה ליתן אור נגלה של התורה וסודותיה לעולם, ואח\"כ גנזו הקב\"ה, והיכן גנזו בסיפורי מעשיות של התורה. אבל לצדיקים, כמ\"ש אם תבקשנה ככסף וכמטמונים כו', אז עתיד לבוא אליהם האור. וז\"ש וגנזו לצדיקים לעת\"ל, ר\"ל שעתיד לבוא לצדיקים האור ע\"י דרושיהם<i>[ftnref_1_י]</i> את הש\"י ע\"י התורה. וז\"ש לעת\"ל תורה חדשה מאתי תצא, וקשה הא לא יחליף ולא ימיר דתו, אלא שיפרש הסודות שבה ושדיבר הכל מאת הש\"י מבנין עולמות העליונים.\n<b>והנה</b> אליהו ז\"ל אמר להרמ\"ק ז\"ל שלבטל מחשבות זרות יאמר פ' אש תמיד תוקד כו'. וקשה איך שייך זה. וי\"ל דפי' ואתם הדבקים בה' כו', דסבת אמתת החיות הוא הדביקות, וכשיש לו דביקות בהש\"י שהוא חי החיים הוא חי בעצם, וכשיפסק מהדביקות הוא חי במקרה, פי' דחמימות הוא עצמי באש, ובמים הוא מקרה שלא יתמיד כשיופסק ויופרד מהאש. וכן הדביקות ארז\"ל ע\"פ ולדבקה בו הלא ה' אש אוכלה הוא אלא הדבק במדותיו, פי' ע\"י התורה. ובשם הנ\"ל דלא מבעי כשהאדם עוסק בתפלה ותורה שהיא כולה שמותיו של הקב\"ה ודאי צ\"ל בדביקות עצום, אלא אפילו כל היום יקיים שויתי ה' ויהיה לו קצת דביקות, מלה\"ד לנר או גחלים, שאם יש בהם עדיין ניצוץ יוכל להבעיר, משא\"כ אם לא נשאר אפי' ניצוץ שצריך להביא אש מחדש. וז\"ש אש תמיד, פי' יהיה לו קצת דביקות שנמשל לאש רשפי אש שלהבת י-ה, על המזבח, למי שזובח יצרו בקרבו, לא תכבה, כנ\"ל. וז\"ש ואתם הדבקים כו', ל\"מ לעוה\"ב ודאי ישיג חיים הנצחיים, אלא אפילו חיים כולכם בעוה\"ז שנקרא היום.\n<b>וזה</b> פירוש שאלו לר' מהו וירא אלקים את האור כי טוב, פירוש דאמרו רז\"ל ויקרא אלקים לאור יום אלו מעשיהם של צדיקים ולחשך קרא לילה אלו מעשיהם של רשעים. והנה גם הפ' וירא אלקים את האור כי טוב צ\"ל דקאי על התורה כנ\"ל, וגנזו, דבריאת האור כבר נאמר ויאמר אלקים יהי אור ויהי אור, והרי התורה היא מעשיהם של צדיקים, וקשה ליה ל\"ל כי טוב, דכיון דקראו אור ודאי הוא טוב, א\"ל אליהו ז\"ל, אמר לשיטתו מה יהיה מעשיהם של צדיקים בהטיבו תרגומו באדלקותיה, פי' שיהיה תמיד קצת בדביקות. וז\"ש והנה כונת הענין כמדליק מנר לנר, שאם יש עדיין קצת אור על נר א' יוכל להדליק, משא\"כ כשכבה.\n<b>והנה</b> בשו\"ע או\"ח סי' א' כ' רמ\"א שויתי ה' כו', דכמו שהקב\"ה מקומו של עולם כן האדם שנקרא עולם הקב\"ה מקומו עומד עליו ורואה במעשיו. וז\"ש הראני נא את כבודך, וא\"ל הקב\"ה לא תוכל לראות כי לא יראני אפי' מה\"ש שנ' בהם ודמות פניהם פני אדם וחי שחי לעולם, מפני שכל נברא הוא מוגבל וכן ראייתו הוא מוגבלת, והנה מקום אתי, ואינו אומר אני במקום, שהקב\"ה מקומו של עולם, פי' שהוא א\"ס, והאיך אפשר שמי שיש לו סוף יוכל לראות הא\"ס.\n<b>וכן</b> אמר מרע\"ה וידעת היום כו' בשמים ממעל כו'. וקשה דממעל ומתחת מיותר. עוד קשה מאי שייכות פה אין עוד. וי\"ל דצ\"ל דהבורא הוא א\"ס, דא\"ת הוא מוגבל א\"כ הוא מחובר כנ\"ל. וצריך לומר דהוא אחד, דא\"ת דיש ב' צ\"ל ביניהם הפרש וכל נפרש מוגבל כו'. וז\"ש וידעת היום כי ה', מדה\"ר, הוא האלקים, והכל אחדות א', דהרי הוא בשמים וממעל לשמים וכן על הארץ ומתחת לארץ, פי' שהוא מקומו של עולם דהוא א\"ס, א\"כ צ\"ל אין עוד, דא\"כ<i>[ftnref_2_יא]</i> צ\"ל הפרש וכל נפרש מוגבל.\n<b>ובגמרא</b> כשרצה שלמה להכניס הארון לבית ק\"ק דבקו שערים כו', אמר שאו שערים גו' ויבוא מלך הכבוד רהטו בתריה למבלעיה <span data-k=\"sm\">[כו']</span> אמר מי הוא זה מלך הכבוד ה' <span data-k=\"sm\">[כו']</span>. וק' מה\"ת הטעות. וי\"ל דהר\"מ אלשיך פי' דק' הלא מכה\"כ אפי' בחו\"ל, ובא\"י מיוחד יותר לשריית שכינה, כ\"ש ירושלים ובהמ\"ק, ומאי נפ\"מ. ופי' כמו הנשמה דמליאה כל הגוף ואפ\"ה לא תמצא חוש ראיה ודיבור כ\"א בעינים ופה מפני כח הכנתם, כן העולם, דארז\"ל דיש לו כל האיברים ראש עפרות רחבת ידים. נמצא הבהמ\"ק וק\"ק הוא כמו ראיה, כ\"ש הארון דשם הדיבור מבין ב' הכרובים, וזה נק' מלך הכבוד. וכן י\"ל על שלמה דהיה מלך ונביא ומוכן יותר להשראת שכינה נק' מלך הכבוד. אלא דהוא יוהרא, ע\"כ רהטו בתריה למבלעיה, ע\"כ אמר מי זה מלך הכבוד ה' השוכן על הארון וכרובים.\n<b>ובמשנה</b> רבי מאיר אומר אם עמלת בתורה נותנים לך שכר הרבה ואם בטלת יש בטילים הרבה כנגדך. פי' מדרש שמואל דעכ\"א הרבה, דבס' (חסידים) [הזוהר] דכשצדיק עוסק בשירות ובתורה בעוה\"ז שורש הנשמה שתחת כסה\"כ וכל מלאכים שנבראו ע\"י מצותיו משוררים למעלה בעולם עליון, עכ\"א אם עמלת בתורה נותנים לך שכר הרבה, פי' גם שכר עסק שלהם, ואם בטלת מן התורה הם בטילים.\n<b>וז\"ש</b> כבודו, פי' התפשטות כבוד השכינה, מלא עולם, משרתיו שואלים זה לזה איה מקום כבודו, פי' עיקר השראת שכינה, ומודים שהוא על ישראל, ואומרים הסימן הוא לעומתם, פי' בזמן שהם אומרים שירה משבחים ואומרים גם למעלה שם הוא עיקר השראת הכבוד.\n<b>וז\"ש</b> המכיר את מקומו, כמו שהקב\"ה מקומו של עולם כן הוא מקומו עומד ורואה במעשיו. וא\"ת הלא כמה ברואים שאינם משגיחים על זה, עכ\"א והשמח בחלקו, הצדיק יש לו נשמה חלק אלו-ה ממעל, ע\"כ והעושה סייג לדבריו שיהי' בדחילו ורחימו.",[["","","----- מקורות ומראה מקומות -----\n<b>?</b>\n<i>המכיר את מקומו כו'</i> – אבות פ\"ו מ\"ו. <i>איזהו עשיר כו'</i> – אבות פ\"ד מ\"א. <i>דבחובה\"ל</i> – שער היחוד פ\"י. <i>דבס' הקנה כו'</i> – ס' הפליאה, ד\"ה וירא אלקים את האור כי טוב. <i>וירא אלקים גו'</i> – בראשית א, ד. <i>בהטיבו גו'</i> – כי תשא ל, ז. <i>כמדליק נר מנר</i> – תקו\"ז תי\"ט מ, ב. <i>ראה הקב\"ה כו'</i> – חגיגה יב, א. בר\"ר ג, ו. <i>והקשה הרה\"ק מו' דוב בער זלה\"ה</i> – לקו\"י יד\"א כא, א (פ\"ג). <i>חמה </i>. .<i> ברקיע א'</i> – חגיגה יב, ב. בר\"ר ו, ו. <i>כמ\"ש בתיקונים</i> – הקדמה יז, א. <i>אין למעלה כו'</i> – חגיגה טו, א. תנחומא שמות יח. שם משפטים טו. רמב\"ם הל' יסוה\"ת פ\"א הי\"א. <i>בס' יצירה</i> – פ\"ב מ\"ו. <i>דאורה זו תורה</i> – מגילה טז, ב. <i>גנזו הקב\"ה </i>. .<i> התורה</i> – זו\"ח רות פה, א-ב. <i>אם תבקשנה גו'</i> – משלי ב, ד. <i>לעת\"ל תורה חדשה כו'</i> – ויק\"ר יג, ג. <i>לא יחליף כו'</i> – פיוט יגדל. הל' יסוה\"ת רפ\"ט. <i>אליהו ז\"ל אמר להרמ\"ק ז\"ל כו'</i> – של\"ה שער האותיות אות הל' (סט, א [נ, ב]). <i>אש תמיד גו'</i> – צו ו, ו. <i>ואתם הדבקים גו'</i> – ואתחנן ד, ד. <i>חי החיים</i> – תקו\"ז תי\"ט מא, סע\"ב. שם תס\"ט קטו, סע\"א. <i>ארז\"ל ע\"פ ולדבקה בו</i> – כתובות קיא, ב. סוטה יד, א. וראה ספרי עקב פ' מט. <i>ולדבקה בו</i> – עקב יא, כב. <i>אש אכלה הוא</i> – ואתחנן ד, כד. <i>הדבק במדותיו</i> – ר' ספרי שם. סוטה יד, א. שבת קלג, ב. <i>ותורה שהיא כולה שמותיו כו'</i> – זח\"ב פז, א. זח\"ג עג, א. שם רחצ, ב. ועוד. <i>שויתי ה' גו'</i> – תהלים טז, ח. <i>רשפי אש גו'</i> – שה\"ש ח, ו. <i>בעוה\"ז שנקרא היום</i> – ע\"ז ג, א. <i>דאמרו רז\"ל כו'</i> – בר\"ר ג, ח. <i>ויקרא אלקים לאור יום</i> – בראשית א, ה. <i>ויאמר אלקים יהי אור גו'</i> – בראשית א, ג. <i>שהקב\"ה מקומו של עולם</i> – בר\"ר סח, ט. <i>האדם שנקרא עולם</i> – תנחומא פקודי ג. <i>הראני נא גו'</i> – כי תשא לג, יח. <i>לא תוכל </i>. .<i> וחי</i> – כי תשא לג, כ. <i>אפילו מה\"ש כו'</i> – במ\"ר ספי\"ד. <i>ודמות פניהם גו'</i> – יחזקאל א, י. <i>הנה מקום אתי</i> – כי תשא לג, כא. <i>ואינו אומר אני במקום כו'</i> – תנחומא כי תשא כז. מדרש תהלים צ, י. <i>וידעת היום גו'</i> – ואתחנן ד, לט. <i>דא\"ת הוא מוגבל </i>. .<i> מוגבל כו'</i> – חובה\"ל שער היחוד פ\"ז ד\"ה והרביעי. <i>ה' מדה\"ר</i> – ספרי ואתחנן פ' כז. זח\"ג סה, א. <i>ובגמרא כשרצה שלמה כו'</i> – שבת ל, א. <i>שאו שערים גו'</i> – תהלים כד, ז. <i>מי הוא זה גו'</i> – תהלים כד, י. <i>דהרמ\"א פי'</i> – תורת משה משפטים כג, כ. <i>מכה\"כ</i> – ישעי' ו, ג. <i>הנשמה דמליאה כל הגוף</i> – ברכות י, א. ויק\"ר ספ\"ד. <i>דארז\"ל דיש לו כו'</i> – קה\"ר א, ט. אדר\"נ לא, ג. <i>הארון דשם הדיבור כו'</i> – נשא ז, פט. ספרי נשא פ' נח. <i>שלמה דהיה מלך ונביא</i> – סע\"ר פ\"כ ע\"פ גי' רש\"י מגילה יד, א ד\"ה נבואה. <i>ר\"מ אומר כו'</i> – אבות פ\"ד מ\"י. <i>בזמן שהם אומרים כו'</i> – חולין צא, סע\"ב. ספרי האזינו פ' שו. אליהו זוטא פכ\"ה.\n----- שולי הגליון -----\n[ftn_1_י]) <i>אולי צ\"ל</i>: דורשיהם.\n[ftn_2_יא]) <i>נראה דצ\"ל</i>: דא\"ל.\n----- הערות וציונים -----\n<i>והקשה הרה\"ק </i>. .<i> בשם רבו</i> – פשטות הלשון מראה שהעתיק זה מלקו\"י כא, א (יד\"א פ\"ג), וז\"ל שם: ששמעתי מפי הרב המופלג מוהר\"ר גרשון לוצקר תלמיד האלקי מו\"ה דוב בער זללה\"ה שאמר בשם רבו כו'. ונ\"ל שהתיבות \"בשם רבו\" קאי על רבו של הר\"ג, ה\"ה הרה\"מ, ולא על רבו של הרה\"מ (הבעש\"ט). ברם ברור שעצם הענין הוא מהבעש\"ט, וכדאי' מפורש בדמ\"א פ' בראשית ד\"ה וירא: שמעתי מאא\"ז נ\"ע זללה\"ה היכן נגנז האור ההיא ואמר שהש\"י גנזו בתורה. וראה בהוספות סי' שלח-שלט.\n<i>גנזו בספורי מעשיות של התורה</i> – ראה זח\"ג קמט, ב, ושם קנב, א וקנה, ב. וראה לקמן סי' רמב.\n<i>לעת\"ל תורה חדשה כו'</i> – ראה לקמן סי' רמב. עיין חס\"ל מעין ב פ' יא-יב.\n<i>אליהו ז\"ל אמר להרמ\"ק ז\"ל כו'</i> – ראה לקמן סי' ריז-ב. להעיר מאו\"ת פ' פנחס סי' קנא-א.\n<i>מלה\"ד לנר או גחלים כו'</i> – ראה לקמן סי' ריז-ב.\n<i>דהיה מלך ונביא</i> – עיין בסדר עולם רבה הוצ' ר\"ב ראטנער פ\"כ הערה כה, ובהוצ' רמ\"י וויינשטאק שם הערה טו. עיי\"ע הגהות הרד\"ל לזח\"א קנ, רע\"א. וצ\"ע מזח\"ב קנד, א, ועיין מה שהאריך שם בנצוצי זוהר אות ד'.\n<i>הביהמ\"ק וק\"ק הוא כמו ראי'</i> – ראה ב\"ב ד, א ותקו\"ז תכ\"א נ, ריש ע\"ב. וראה איכ\"ר פתיחתא טז לבך זה ביהמ\"ק כמד\"א והיו עיני ולבי שם כל הימים. וראה זח\"ג קסא, ב קה\"ק לבא כו'. ולהעיר מע\"ז כח, ב דשורינא דעינא באובנתא דלבא תלי. וראה ר\"מ זח\"ג רכב, א ותקו\"ז סתכ\"א סג, א.\n<i>הזוהר</i> – ראה זח\"ב קלא, ב, ושם קסד, ב, ברם שם מדובר ממלאכי עלאי ומשריין עלאין.\n<i>כבודו כו' על ישראל</i> – ראה פס\"ז נח ט, כו, ושם שלח יד, כא. ועיין זח\"א רלז, א ושם כה, רע\"א."]]],[300010100,"פה\n\n[<b>איתא</b> <span data-k=\"sm\">בתיקונים]</span> אני ה' לא שניתי, אבל לגבי חייביא אשתני הקב\"ה ואסתתר בכמה לבושין ובכמה כסויין כו' דאינון תהו ובהו כו'. וז\"ש אסתירה פני מהם, אבל אינון (דדחליין) [דתליין] מיניה ומשכינתיה לא אשתני לעולם <span data-k=\"sm\">[וכו' יעו\"ש]</span>. הרי שיש כמה לבושין וכסויין שהקב\"ה מסתתר בהם. אמנם <span data-k=\"sm\">[כתבתי לקמן דשמעתי </span><i>ממורי</i><span data-k=\"sm\"> זלה\"ה]</span> &lt;הבעש\"ט&gt;, שאם ידע האדם שהקב\"ה מסתתר שם, אין זה הסתרה, כי נתפרדו כל פועלי און. וז\"ש ואנכי הסתר אסתיר פני <span data-k=\"sm\">[מהם]</span> &lt;פי'&gt; שיסתיר <span data-k=\"sm\">[מהם]</span> שלא ידעו <span data-k=\"sm\">[ר\"ל]</span> שהקב\"ה שם בהסתרה זו <span data-k=\"sm\">[וכו' ודפח\"ח]</span>.\n<b>&lt;וז\"ש&gt;</b> <span data-k=\"sm\">[וכיוצא בזה שמעתי </span><i>ממנו</i><span data-k=\"sm\">]</span> כי ר\"ת אמר אויב ארדוף וגו' <span data-k=\"sm\">[ראשי תיבות]</span> הם ה' אלפין ששם אלופו של עולם מסתתר, בסוד שם סא\"ל &lt;גי' יחוד הוי' אדנ-י&gt; <span data-k=\"sm\">[וכו' ודפח\"ח]</span>.\n<b>ואחר</b> שידע אדם כלל זה שהוא כלל גדול שאין שום מסך מבדיל בינו לבין אלקיו בשעת תורה ותפלה, גם שיעלו לפניו כמה מ\"ז שהם לבושין וכסויין שהקב\"ה מסתתר שם, מ\"מ אחר שידע אדם שהקב\"ה מסתתר שם, אין זה הסתרה.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י ר</b>\"<b>פ בראשית ז</b>,<b> א (כב</b>,<b> א)</b>\n<i>איתא בתיקונים</i> – תכ\"ו עא, ב ואילך. <i>אני ה' גו'</i> – מלאכי ג, ו. <i>אסתירה גו'</i> – האזינו לב, כ. <i>ואנכי הסתר גו'</i> – וילך לא, יח. <i>אמר אויב גו'</i> – בשלח טו, ט.\n----- הערות וציונים -----\nראה לעיל סי' כה, נא, סו. לקמן סי' צח ושנה.\n<i>הסתר אסתיר כו' שלא ידעו כו'</i> – ראה לעיל סי' כה, ולקמן בהוספות סי' מב.\n<i>כי ר\"ת אמר כו'</i> – ראה לקמן סי' רפח, ובהערות לסי' קטו.\n<i>סא\"ל</i> – שם המ\"ה משם ע\"ב (ראה זח\"ב ער, א וזו\"ח שה\"ש סח, ד).\n<i>סא\"ל גי' יחוד הוי' אד'</i> – ראה כתנת פסים פ' בלק מב, רע\"א: שקבלתי ממורי זלה\"ה שגם בסמא\"ל יש בו ש\"ק סא\"ל גי' צ\"א יחוד הוי' ואד' וכו' ודפח\"ח, וזה מורה על אחדותו ית' אשר מלכותו בכל משלה גם על הקליפות, והבן והשי\"ת יכפר. וראה לקמן סס\"י קטו וסי' קכח ובהערות שם."]]],[300010101,"פו\n\n<b>&lt;מבעש\"ט</b> ז\"ל&gt; נודע כי אות א' הוא חכמה ומחשבה כמ\"ש <span data-k=\"sm\">[בפסוק]</span> ואאלפך חכמה. ובזה יובן בראשית ותרגומו בחכמתא שהיא אות א', בזה ברא אלקים את השמים. כי כל כ\"ב אותיות הם לבושין זה לזה, כי א' נתלבשה תוך אות ב', כי ב' ב' אלפין, ג' ג' אלפין <span data-k=\"sm\">[וכו' כמו ששמעתי </span><i>ממורי</i><span data-k=\"sm\"> זלה\"ה וכו']</span>. וראשית הבריאה הי' ע\"י אות א' שהוא חכמה, וברא הכל ע\"י חכמה כמ\"ש <span data-k=\"sm\">[כולם]</span> בחכמה עשית &lt;כו'&gt;.<i>[ftnref_1_יב]</i>\n<b>הרי</b> רוחנייתו ית' בתוך אות א', ונתעטף בו וברא אור מן אות א', והוא אור אצילות, ואח\"כ נתעטף עם א' בתוך אות ב' וברא עולם הבריאה כו'<i>[ftnref_2_יג]</i>.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י ר</b>\"<b>פ בראשית ז</b>,<b> א (כב</b>,<b> ב)</b>\n<i>אות א' הוא חכמה</i> – זח\"א כו, ב. זח\"ב קלו, סע\"ב. <i>ומחשבה</i> – זח\"ב כ, א. תקו\"ז יז, א. <i>ואאלפך חכמה</i> – איוב לג, לג. <i>בראשית ברא גו'</i> – בראשית א, א. <i>ותרגומו בחכמתא</i> – ת\"י שם. ספר הבהיר ג. זח\"א ג, ב. ושם קמה, א. <i>ברא אלקים א\"ת </i>. .<i> כל כ\"ב אותיות</i> – זח\"א טו, ב. שם כט, ב. תקו\"ז רתנ\"א פו, ב. אליהו רבה פי\"ח. <i>כי כל כ\"ב אותיות הם כו'</i> – זח\"א לג, רע\"א. <i>כולם בחכמה עשית</i> – תהלים קד, כד.\n----- שולי הגליון -----\n[ftn_1_יב]) \"&lt;כו'&gt;\"<i> כאן סימן שהשמיט כמה שורות מס' תוי\"י</i>.\n[ftn_2_יג]) \"כו'\"<i> כאן סימן שהשמיט סוף הפיסקא</i>.\n----- הערות וציונים -----\nנשנה לקמן סי' שנה עם ההמשך אשר בתוי\"י. וראה גם לעיל סי' מה ולקמן סי' קצה.\n<i>וברא אור מן אות א' כו'</i> – להעיר מזו\"ח שה\"ש סו, א."]]],[300010102,"פז-א\n\n<b>&lt;מהבעש\"ט&gt;</b> <span data-k=\"sm\">[דשמעתי בשם </span><i>מורי</i><span data-k=\"sm\"> זלה\"ה]</span> מה שביאר בכתבי האריז\"ל למתק הדינין בשרשן, <span data-k=\"sm\">[היינו ע\"י שימצא בדין שורש חסד אז נעשה הכל חסד, ונמתק הדין בשורש חסד זה שמצא בו, ודפח\"ח]</span>",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י נח יב</b>,<b> סע</b>\"<b>ב (מד</b>,<b> א)</b>\n<i>בכתבי האריז\"ל</i> – ע\"ח שי\"ג פי\"א. פע\"ח שער השופר פ\"א.\n----- הערות וציונים -----"]]],[300010103,"פז-ב\n\n<b>&lt;פי'&gt;</b> <span data-k=\"sm\">[דהקשה הרמב\"ן איך ע\"י תפלה נשתנה גזר דין מרעה לטובה, וכי יש ח\"ו שנוי רצון, וביותר המתפלל עבור חבירו וכו'. ותירץ </span><i>מורי</i><span data-k=\"sm\"> זלה\"ה בשם רבו שהתפלה היא למתק דין בשרשו, לקשר דין המלכות בבינה, ושם הוא אדם אחר וכו' יעו\"ש. </span><i>ומורי</i><span data-k=\"sm\"> זלה\"ה ביארו יותר]</span>, כי הגזר דין הוא אותיות, ויכול השליח לעשות צירוף אחר <span data-k=\"sm\">[מן אותיות אלו ממש וכו' יעו\"ש]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י נח יג</b>,<b> ב (מה</b>,<b> ב)</b>\n----- הערות וציונים -----\n<i>ע\"י התפלה נשתנה כו'</i> – ראה אמו\"ד לרס\"ג מ\"ב פ' ד-ה. אור ה' מ\"ג ח\"ב כלל א' פ\"א. ס' העיקרים מ\"ד פט\"ז ופי\"ח.\n<i>לעשות צירוף אחר כו'</i> – להעיר מתענית כה, א וביאור הרה\"מ בס' דברת שלמה פ' בשלח. עיין דמ\"א ר\"פ אמר בשם הבעש\"ט. ובענין השתנות ע\"י מיתוק בשורשו עיין מדל\"י סי' ז (ח), ט-י (י), מח (נד), קעב (קעז) ורלה (רמח)."]]],[300010104,"פז-ג\n\n<b>&lt;כמ\"ש&gt;</b> <span data-k=\"sm\">[וזה שאמר]</span> לנח צהר תעשה לתיבה, שיהפך מדת הדין למדת הרחמים <span data-k=\"sm\">[. . . ובזה יובן]</span> וכי תבאו מלחמה <span data-k=\"sm\">[בארצכם, הסבה הוא]</span> על הצר <span data-k=\"sm\">[הצורר אתכם, ר\"ל משנשאר הצר שלא ידעו להופכו מן הצר צהר רצה וכנ\"ל, לכך עצה היעוצה]</span> והרעותם בחצוצרות, שהוא תואר שמחה, היפך תואר שופר שהוא חרדה, <span data-k=\"sm\">[כמ\"ש בעקידה בזה יעו\"ש]</span>, וע\"י שקיבל בשמחה נהפך מצרה רצה, <span data-k=\"sm\">[כמו שכתבתי בשם </span><i>מורי</i><span data-k=\"sm\"> ז\"ל]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י נח יג</b>,<b> א (מד</b>,<b> ב)</b>\n<i>צהר תעשה לתיבה</i> – נח ו, טז. <i>וכי תבאו מלחמה גו' והרעתם גו'</i> – בהעלתך י, ט. <i>כמ\"ש בעקידה</i> – פ' אמר שער סז.\n----- הערות וציונים -----\n<i>הצר צהר רצה</i> – ראה בהוספות סי' ג (תורה החמשית), ושם סי' ט, י ויח. וראה לעיל סי' מא."]]],[300010105,"פז-ד\n\n[<b>ומעתה</b> <span data-k=\"sm\">יבואר ענין הטבת החלום בנוסח הנ\"ל שהוא להמתיק דינין בשרשן כפי שני פירושים הנ\"ל, א' כפשוטו כפירוש </span><i>מורי</i><span data-k=\"sm\"> זלה\"ה בשם רבו]</span> לקשר דין המלכות בבינה <span data-k=\"sm\">[וכו'. . .]</span>, &lt;או&gt; <span data-k=\"sm\">[ב' כפירוש מורי זלה\"ה]</span> למצוא &lt;בדין&gt; שורש חסד בתוך הדין, אז נמתק הדין בשורש חסד זה ונעשה באמת חסד <span data-k=\"sm\">[וכו']</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י נח שלהי יג</b>,<b> ג (מו</b>,<b> ב)</b>\n<i>ענין הטבת החלום</i> – ברכות נה, ב.\n----- הערות וציונים -----"]]],[300010106,"פח\n\n<b>&lt;מהבעש\"ט&gt;</b> <span data-k=\"sm\">[שקיבלתי </span><i>ממורי</i><span data-k=\"sm\">]</span> שיש באדם עשר ספירות, כי הוא עולם קטן, וכמ\"ש הראב\"ד כי מה שיש &lt;בעולם&gt; <span data-k=\"sm\">[בעולמות עליונים]</span> הוא ג\"כ בשנה ובנפש אדם, וסימנך והר סיני עש\"ן <span data-k=\"sm\">[וכו' יעו\"ש]</span>. ומדריגה אחרונה שבאדם, כגון צער ויסורין <span data-k=\"sm\">[וכדומה]</span>, &lt;הוא&gt; <span data-k=\"sm\">[זה]</span> נקרא מדת המלכות שהיא מדה אחרונה כי רגליה ירדות מות. ונצח והוד שבאדם הם עמודי קיימין ש<span data-k=\"sm\">[האדם]</span> מאמין אמונת הבורא על אמתתו. ומדת יסוד הוא כשיש לו תענוג בעבודת הש\"י יותר מכל התענוגים.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י לך לך טז</b>,<b> ג (נז</b>,<b> א)</b>\n<i>הוא עולם קטן</i> – תנחומא פקודי ג. <i>וכמ\"ש הראב\"ד</i> – פי' לס\"י המיוחס לראב\"ד בריש ההקדמה ושם פ\"י מ\"א. <i>והר סיני עש\"ן</i> – יתרו יט, יח. <i>המלכות </i>. .<i> רגלי' כו'</i> – ע\"ח של\"ד פ\"א. <i>רגלי' גו'</i> – משלי ה, ה.\n----- הערות וציונים -----\n<i>מדת המלכות כו' רגליה כו'</i> – ראה מדל\"י סי' קב (קיא).\n<i>ונו\"ה הם עמודי קיימין</i> – ראה זח\"א רכ, ב. תקו\"ז יז, א ושם תי\"ג כט, א.\n<i>שמאמין כו'</i> – עיין זח\"ג קצח, ב. קהלת יעקב, ערך מתנים. וראה לעיל סי' יא (ובהערות שם), ולקמן סי' רנז ותח.\n<i>ומדת יסוד כו'</i> – להעיר מזח\"ב קי, רע\"א ובאוה\"ח שם. וראה תניא, אגה\"ק סי' טו."]]],[300010107,"פט\n\n<b>&lt;מהבעש\"ט&gt;</b> <span data-k=\"sm\">[ששמעתי </span><i>ממורי</i><span data-k=\"sm\">]</span> שאם נזדמן &lt;לאדם&gt; שראה דבר עבירה או שמע על אחד, יבחין שיש בו שמץ עבירה זו ושירגיש לתקן את עצמו. ואמר הפסוק תחבושת לזה שינצור לשונו &lt;סור מרע ועשה טוב&gt; <span data-k=\"sm\">[אע\"פ שהוא קשה לפרוש, וכמו שאמרו בש\"ס וכולן באבק לשון הרע, מ\"מ נתן הפסוק תקנה לזה שידע שהוא ניתן לו לראות כדי שיסור עצמו מרע ויתקן את עצמו שיהיה טוב]</span>, ואז גם הרשע יחזור בתשובה אחר שיכליל אותו עמו ע\"י אחדות שכולם אדם א', ואז תגרום שתהיה מכלל ועשה טוב, שתעשה את הרע טוב, ואז תבוא למדת בקש שלום ורדפהו כו' <span data-k=\"sm\">[ודו\"ק]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י ס</b>\"<b>פ לך לך יז</b>,<b> א (נח</b>,<b> ב)</b>\n<i>ואמר הפסוק כו'</i> – תהלים לד, יד. <i>סור מרע גו'</i> – תהלים לד, טו. <i>וכולם באבק כו'</i> – ב\"ב קסה, א. <i>בקש שלום גו'</i> – תהלים לד, טו.\n----- הערות וציונים -----\n<i>נזדמן כו' יבחין שיש בו כו'</i> – ראה לקמן סי' קטז ושסג, ובהוספות סי' קעו (ועיי\"ש בהערות).\n<i>ואז גם הרשע כו'</i> – להעיר מלעיל סי' עז.\n<i>ועשה טוב כו'</i> – ראה לעיל סי' מא וסט."]]],[300010108,"צ\n\n<b>יש</b> בחינה שאחר עלותו למעלה חוזר ויורד כדי להעלות המדריגות התחתונות בסוד רחצתי את רגלי <span data-k=\"sm\">[איככה אטנפם. . .]</span>, וזה סוד רצוא ושוב, ונקרא קטנות וגדלות <span data-k=\"sm\">[וקטנות שני]</span>, ובכל ירידה צריך אזהרה איך לחזור ולעלות שלא ישאר ח\"ו, וכמו ששמעתי <span data-k=\"sm\">[</span><i>ממורי</i><span data-k=\"sm\">]</span> &lt;הבעש\"ט&gt; שיש כמה שנשארו <span data-k=\"sm\">[וכו']</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י וירא יז</b>,<b> ב (נט</b>,<b> ב)</b>\n<i>רחצתי גו'</i> – שה\"ש ה, ג. <i>רצוא ושוב</i> – יחזקאל א, יד.\n----- הערות וציונים -----\nנשנה במילואו לקמן סי' שנו. וראה לקמן סי' קלט ובהערות שם."]]],[300010109,"צא\n\n<b>&lt;מבעש\"ט&gt;</b> <span data-k=\"sm\">[דשמעתי בשם </span><i>מורי</i><span data-k=\"sm\">]</span> פירוש הפסוק כל אשר תמצא ידך לעשות בכחך עשה וגו', כי ענין חנוך מט\"ט שהיה מייחד קודשא בריך הוא &lt;ושכינתיה&gt; על כל תפירה הוא <span data-k=\"sm\">[כך]</span>, דהמחשבה נק' א\"ס, הוי', והמעשה הוא אדנ\"י, וכאשר מחבר המעשה עם המחשבה בעת עשיית המעשה נק' יחוד קודשא בריך הוא ושכינתיה. וז\"ש כל אשר תמצא ידך לעשות בכח\"ך עש\"ה, ר\"ל כי המחשבה נק' חכמה כח מה, ותעשה המעשה בכחך, שהיא המחשבה, לחבר שניהם <span data-k=\"sm\">[שהוא יחוד קב\"ה ושכינתיה]</span>. כי אין בשאול <span data-k=\"sm\">[וגו']</span>, ותיבת אין משמש למעלה ולמטה, ר\"ל שאם אינך מאמין בזה ותשאל ותסתפק בזה, אז אין בשאול דעת וחשבון כו' <span data-k=\"sm\">[ודפח\"ח]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י וירא יז</b>,<b> סע</b>\"<b>ב (נט</b>,<b> ב)</b>\n<i>כל אשר גו'</i> – קהלת ט, י. <i>חנוך מט\"ט</i> – תיב\"ע ובראשית רבתי בראשית ה, כד. <i>שהיה מייחד כו'</i> – עמק המלך, שער קרית ארבע פצ\"ד בשם מדרש. מגיד מישרים פ' מקץ (סוף מהד\"ב). עש\"מ, מאמר אם כל חי ח\"ג סי' סב. <i>דהמחשבה נק' כו'</i> – זח\"א רסו, ב. זח\"ג קיט, ב. <i>והמעשה הוא כו'</i> – זו\"ח יתרו לד, רע\"ג (ועיי\"ש סע\"ב). <i>המחשבה נק' חכמה</i> – זו\"ח שם. תקו\"ז יז, א. <i>חכמה כ\"ח מ\"ה</i> – זח\"ג כח, א. שם לד, א. תקו\"ז ד, א. <i>כי אין </i>. .<i> בשאול גו'</i> – קהלת ט, י.\n----- הערות וציונים -----\nראה לעיל סי' מב, מט ונט, ולקמן סי' קפט-א, קפט-ב ושע."]]],[300010110,"צב\n\n<b>&lt;ענין</b> רצוא ושוב אפילו בגשמי.&gt; הוי מתחמם כנגד אורן של חכמים <span data-k=\"sm\">[והזהר בגחלתן שלא תכוה]</span>, ר\"ל שלא לחמם <span data-k=\"sm\">[אלא</span><i>[ftnref_1_יד]</i><span data-k=\"sm\">]</span> מרחוק ולא להתקרב מאד עד גחלת האש &lt;כי והזהר בגחלתן שלא תכוה&gt; <span data-k=\"sm\">[שלא יגרם היזק שיכווה, וכמדומה ששמעתי בשם </span><i>מורי</i><span data-k=\"sm\">, והבן]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י וירא יז</b>,<b> ד (סא</b>,<b> ב)</b>\n<i>רצוא ושוב</i> – יחזקאל א, יד. <i>הוי מתחמם כו' והוי זהיר בגחלתן כו'</i> – אבות פ\"ב מ\"י.\n----- שולי הגליון -----\n[ftn_1_יד]) <i>המלה </i>\"אלא\"<i> לא כתוב שם</i>,<i> אלא מתוכן הדברים נראה שכן צ\"ל</i>.\n----- הערות וציונים -----\n<i>ענין רצו\"ש אפילו בגשמי</i> – פתיחה זו מיוסדת על מש\"כ שם בתוי\"י לפני תורת הבעש\"ט: דידוע מה שאיתא בכתבים בקשעה\"מ (שער הכונות, ענין דרושי הלילה דרוש ה') שם של מ\"ב שיש בו ב' מיני יראה בסוד רצו\"ש וכו' יעו\"ש והוא סוד עולם התיקון נגד עולם התוהו שע\"י קירוב גדול נתבטלו ממציאות, משא\"כ כשיש קירוב מרחוק כמו סוד עולם התיקון והבן זה היטב. <i>והוא הדין בגשמי</i> בעניני בני אדם נגד חבירו ראיתי בס' מבחר פנינים בשם חכם אחד הזהר שלא תקרב אדם א' יותר מדאי שלא יהיה הקירוב גורם ריחוק יעו\"ש, ואפשר שזה כוונת המשנה באבות והוי מתחמם (כבפנים)."]]],[300010111,"צג-א\n\n<b>&lt;מהבעש\"ט&gt;</b> <span data-k=\"sm\">[שמעתי </span><i>ממורי</i><span data-k=\"sm\">]</span> כשיש רשעים בעיר או מדינה המתנהגין בשקר ויש ביניהם צדיק המתנהג באמת כאשר עוסק בתורה או בתפלה ומדבק א\"ע אל האמת, אז יתפרדו כל פועלי און ושקר <span data-k=\"sm\">[וכו' ודפח\"ח]</span>. וז\"ש אם תשקור לי <span data-k=\"sm\">[והבן]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י וירא יח</b>,<b> רע</b>\"<b>א (סא</b>,<b> ב)</b>\n<i>יתפרדו גו'</i> – תהלים צב, י. <i>אם תשקור לי</i> – וירא כא, כג.\n----- הערות וציונים -----"]]],[300010112,"צג-ב\n\n<b>וכל</b> הבארות אשר חפרו <span data-k=\"sm\">[עבדי אביו]</span> בימי אברהם <span data-k=\"sm\">[אביו סתמום פלשתים . . וישב יצחק ויחפר וגו' . . . כי הבארות והצינורות אשר חפרו בימי אברהם]</span> שהם צינור החסד ואהבה, סתמום <span data-k=\"sm\">[פלשתים]</span> במות אברהם, <span data-k=\"sm\">[נסתם הבאר והצינור שהיו עובדים הש\"י מאהבה]</span>. וישב יצחק ויחפור באר וצינור היראה &lt;כמדתו&gt; <span data-k=\"sm\">[מדתו של יצחק, ומאחר שאינו צנור אהבה ואחדות כאברהם]</span>, &lt;ע\"כ&gt; <span data-k=\"sm\">[לכך]</span> ויריבו <span data-k=\"sm\">[רועי גרר]</span> לאמר לנו המים <span data-k=\"sm\">[ויקראו עשק כו']</span> &lt;פי' אנחנו רוצים לעבוד ה' ע\"י מדת אהבה, כי יש יראה חצוניות ג\"כ&gt;. <span data-k=\"sm\">[בשלמא בחינת אברהם, משא\"כ בחינת יצחק שהוא הפחד יש בו כמה בחינות פחד ויראה חיצונית . . . והכי נמי תחלה נקרא עשק, ר\"ל כי יראה חיצונית מחמת עונש נקרא ח\"ו עובד ע\"ז כמו שאיתא בזוהר ועשקו החיצונים ממנו הכל כנודע, ויחפר באר אחרת ונקרא שטנה שמעורר השטן ע\"י הבכיה שמעוררין המוכיחים כמו ששמעתי </span><i>ממורי</i><span data-k=\"sm\"> ז\"ל]</span>. &lt;ע\"כ&gt; ויחפר באר אחרת, יראה פנימית, ונקרא רחובות כי הרחיב ה' לנו, ופנימיות היראה נקרא רחובות, והבן.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י ס</b>\"<b>פ תולדות כא</b>,<b> סע</b>\"<b>ג (עו</b>,<b> ב)</b>\n<i>וכל הבארות גו'</i> – תולדות כו, טו. <i>וישב יצחק גו'</i> – תולדות כו, יח. <i>אברהם צינור החסד </i>. .<i> וצינור היראה מדתו של יצחק</i> – זח\"א צו, א. זח\"ג שב, א. <i>ויריבו גו'</i> – תולדות כו, כ. <i>ויחפור גו' רחבות גו' הרחיב ה' לנו</i> – תולדות כו, כב.\n----- הערות וציונים -----\n<i>כי הבארות והצינורות כו'</i> – ראה בכל זה זו\"ח תולדות כז, א (זח\"ג שב, ב).\n<i>כמו שאיתא בזוהר</i> – עיין סוף תקו\"ז ת\"ד קמא, א. ועיי\"ע זח\"א יא, ב."]]],[300010113,"צג-ג\n\n<b>וכאשר</b> נודע לבעלי בינה לעשות יחוד גם בספורי דברים שעם חבירו, <span data-k=\"sm\">[כמו ששמעתי </span><i>ממורי</i><span data-k=\"sm\"> קול באשה ערוה וכו']</span>, ולהסיר העצבות יפקח באיזה עסק, והוא ג\"כ יחוד &lt;כו', ע\"ש&gt;<i>[ftnref_1_טו]</i> על דרך הני תרי בדחי, <span data-k=\"sm\">[ששמעתי </span><i>ממורי</i><span data-k=\"sm\">]</span> שהיו מייחדין ומעלין העולמות בכל עניני עוה\"ז <span data-k=\"sm\">[יעו\"ש]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י ויצא כג</b>,<b> ב (פב</b>,<b> ב)</b>\n<i>קול באשה ערוה</i> – ברכות כד, א. <i>בכל דרכיך דעהו</i> – משלי ג, ו. <i>שויתי גו' שמח לבי גו' אף בשרי גו'</i> – תהלים טז, ח-ט. <i>הני תרי בדחי</i> – תענית כב, א.\n----- שולי הגליון -----\n[ftn_1_טו]) <i>\"</i>כו' ע\"ש\"<i> כלומר שהשמיט כאן כמה שורות</i>: גם כשרואה דבר מכוער באדם או שיבטל אותו מתורה ותפלה יבין שהוא מהש\"י לתועלתו, כאשר כתבתי בקוה\"א יעו\"ש א\"כ בכל דרכיך דעה\"ו אתי שפיר, וכאשר כתבתי שויתי ה' לנגדי גם שהוא לנגריות מ\"מ מימיני בל אמוט ואז שמח לבי לעורר רחמים ושמחה בעולם, וז\"ש אף בשרי ישכן לבטח יעו\"ש, נוסף לזה על דרך (<i>כבפנים</i>).\n----- הערות וציונים -----\n<i>לעשות יחוד גם מספורי דברים כו'</i> – ראה לעיל סי' ח, ולקמן סי' רכ-א, שב-א, שעג ובהערות שם.\n<i>כמו ששמעתי כו'</i> – ראה בסו\"ס תוי\"י רא, ב (תשלא אות כ).\n<i>גם כשרואה כו'</i> – ראה לקמן סי' שב-א.\n<i>וע\"ד הני תרי בדחי כו'</i> – ראה לעיל סי' ח וש\"נ בהערות."]]],[300010114,"צג-ד\n\n<b>אכן</b> יש ה' במקום הזה, ר\"ל במקום <span data-k=\"sm\">[זה של]</span> גדודי חיות <span data-k=\"sm\">[רעות ולסטים]</span> יש שם שמו ית', וממילא גם בכל מ\"ז ורעות שהם גדודי חיות ולסטים וקליפות יש שם ג\"כ ניצוצי קדושה של השכינה שירדה שם ע\"י השבירה. ויירא ויאמר מה נורא, ר\"ל שנפלה עליו יראה ורעדה, שציער א\"ע בצער השכינה וירידתה בין הקליפות כ\"כ, ועי\"ז נעשה יחוד יראה עם נורא ונתפרדו הקליפות <span data-k=\"sm\">[כמו ששמעתי </span><i>ממורי</i><span data-k=\"sm\"> בענין כזה יעו\"ש]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י ויצא כג</b>,<b> ג (פג</b>,<b> ב)</b>\n<i>אכן יש גו'</i> – ויצא כח, טז. <i>ויירא ויאמר גו'</i> – ויצא כח, יז.\n----- הערות וציונים -----\n<i>יחוד יראה ונורא</i> – מלכות (יראה, ראה זח\"ג קח, א ותקו\"ז תל\"ג עז, רע\"א) ותפארת (נורא, ראה זח\"ב עט, רע\"א. תקו\"ז תי\"ט לט, ב ושם ת\"ל עד, א). וראה צ\"פ פ' בשלח נ, רע\"ג (קפג, א): את האלקים אני ירא . . האלקי\"ם גימטריא צ\"א מספר הוי' אד' שהוא יחוד יראה עם נורא תפארת ומלכות והבן. וראה לקמן סי' קלה, קס, קסב וקסג."]]],[300010115,"צד\n\n<b>&lt;מבעש\"ט,</b> ידביק מחשבתו באור א\"ס שבתוך האותיות שהוא אור פני מלך חיים&gt;.\n[<b>ובעודו</b> <span data-k=\"sm\">מדבר בתורה ותפלה . . . יהיה מחשבתו דביקה בו ית' בדביקה וחשיקה באור פני מלך חיים אור האין סוף שבתוך האותיות, והבן ש]</span> &lt;ו&gt;הוא כלל גדול בתורה ותפלה <span data-k=\"sm\">[לפי מה שקבלתי </span><i>ממורי</i><span data-k=\"sm\">]</span>. גם מסוגל <span data-k=\"sm\">[זה כשיעשה כנ\"ל]</span> לבטל הדינין <span data-k=\"sm\">[וכאשר שמעתי </span><i>ממנו</i><span data-k=\"sm\">, ודפח\"ח]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י ויצא כד</b>,<b> סע</b>\"<b>ב (פו</b>,<b> ב)</b>\n<i>באור פני מלך חיים</i> – משלי טז, טו.\n----- הערות וציונים -----\nראה לעיל סי' י ומד. לקמן סי' צו, רפד ותכו. צוה\"ר סי' עה, קח וקיא.\n<i>מסוגל לבטל הדינין</i> – ראה לעיל סי' י ובהערות שם. ולקמן סי' קסד."]]],[300010116,"צה\n\n<b>&lt;מהבעש\"ט</b> זלה\"ה&gt; איתא בש\"ס דתענית א\"ר אמי מאי דכתיב אם ישך הנחש בלא לחש וגו', אם השמים נעצרין <span data-k=\"sm\">[וכו']</span> מה תקנתיה ילך אצל חסיד שבדור ויתפלל <span data-k=\"sm\">[וכו']</span> ואם לחש ונענה והגיס דעתו מביא אף לעולם שנ' מקנה אף על עולה <span data-k=\"sm\">[וכו']</span>. והקשה <span data-k=\"sm\">[</span><i>מורי</i><span data-k=\"sm\">]</span> אם הוא חטא והגיס דעתו, העולם מה חטאו להביא אף על העולם. וביאר, כי מהראוי שמי שאמר לשמן וידליק הוא יאמר לחומץ וידליק כרבי חנינא בן דוסא, ואם היו כל בני עולם נוהגין בחסידות לא היה פלא על א' שאומר לחומץ וידליק וכך היה, כי כולם עושין כך. משא\"כ מחמת שבני עולם הולכין בשרירות לבם הרע, ואינו עולה להם זה כ\"א ליחיד בדורו, שאם נענה בתפלה הוא דבר נפלא בעיניהם, לכך זה מגיס דעתו, א\"כ הוא בסיבת דורו ובני העולם, לכך מביא אף בעולם <span data-k=\"sm\">[ודפח\"ח]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י ויצא כד</b>,<b> ג (פז</b>,<b> א)</b>\n<i>בש\"ס דתענית</i> – תענית ח, א. <i>אם ישך גו'</i> – קהלת י, יא. <i>מקנה אף גו'</i> – איוב לו, לג. <i>כרחב\"ד</i> – תענית כה, א.\n----- הערות וציונים -----\nלהעיר מפרש\"י לויקרא ד, ג ולקמן סוף סי' קכה.\n<i>שמי שאמר לשמן כו'</i> – להעיר ממדל\"י סי' קלד (קמב) ואו\"ת סי' רפה."]]],[300010117,"צו-א\n\n<b>&lt;מהבעש\"ט.</b> ענין&gt; ד' שנכנסו לפרדס . . . ופירש רש\"י עלו לרקיע ע\"י שם, והתוספות פי' ולא עלו <span data-k=\"sm\">[למעלה]</span> ממש אלא נראה להם כאלו עלו <span data-k=\"sm\">[למעלה וכו']</span> . . .\n<b>&lt;וי\"ל,&gt;</b> פרד\"ס <span data-k=\"sm\">[שדרשו חז\"ל]</span> ר\"ת פשט רמז דרוש סוד, <span data-k=\"sm\">[ולפי מה שקבלתי </span><i>ממורי</i><span data-k=\"sm\">]</span> שעיקר עסק תורה <span data-k=\"sm\">[ותפלה]</span> הוא שידבק א\"ע אל פנימיות רוחניות אור א\"ס שבתוך אותיות התורה <span data-k=\"sm\">[והתפלה]</span>, שהוא הנקרא לימוד לשמה, שבזה אמר ר' מאיר כל העוסק בתורה לשמה זוכה לדברים הרבה ומגלין לו רזי תורה <span data-k=\"sm\">[וכו']</span>, ר\"ל שידע עתידות וכל מאורעותיו מתוך התורה, וידע איך יתנהג בתורה ועבודת הש\"י, מלבד שרואה עולמות של מעלה, <span data-k=\"sm\">[וכהנה שמעתי מפי </span><i>מורי</i><span data-k=\"sm\"> ודפח\"ח]</span>. . .",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י ויצא כד</b>,<b> סע</b>\"<b>ד (פח</b>,<b> ב)</b>\n<i>ד' שנכנסו לפרדס</i> – חגיגה יד, א. <i>פרד\"ס ר\"ת כו'</i> – תקזו\"ח קז, ג. <i>אמר ר\"מ כו'</i> – אבות פ\"ו מ\"א.\n----- הערות וציונים -----\n<i>שידביק א\"ע אל כו'</i> – ראה לעיל סי' י, מד וצד, ולקמן סי' תכו.\n<i>שידע עתידות כו'</i> – ראה לעיל סי' סז, ולקמן סי' קצט-א. עיין ס' סוד יכין ובועז פ\"ב ד\"ה ואף שחז\"ל: הזהירו אותי לזה מוריי הגדולים בתורה ובחסידות, ובתוכם ידידי הרב החסיד מופת הדו\"ר מוהר\"ר ישראל בעש\"ט זצללה\"ה כוונה רצויה בלימוד לשמה לדבק א\"ע בקדושה וטהרה עם האותיות בכח ופועל בדיבור ובמחשבה לקשר חלק מנר\"ן ח\"י בקדושת נר מצוה ותורה אור אותיות המחכימות ומשפיעים שפע אורות וחיות אמיתיות נצחיות. וכשזכה להבין ולהתדבק בהאותיות קדושים יוכל להבין מתוך האותיות ממש אפילו עתידות. ולכן נקראת התורה מאירת עינים שמאירה עיני המתדבק בהם בקדושה ובטהרה כמו האותיות של אורים ותומים. ומילדותי מיום שהכרתי בדביקות האהבה עם מורי הרב מוהר\"ר ישראל תנצב\"ה הנ\"ל ידעתי נאמנה שזה היה הנהגותיו בקדושה ובטהרה ברוב חסידות ופרישות וחכמתו צדיק באמונתו יחיה דמטמרין גלין ליה כבוד ה' הסתר דבר.\n<i>וידע איך יתנהג כו'</i> – ראה לקמן סי' קצו. רג\"כ לעיל סי' יג ובהערות שם. להעיר מזח\"ב נג, ב אמאי אקרי תורה כו', ושם רס, א אורייתא אוליף כו'. ועוד עד\"ז זח\"א יא, א וזח\"ב פב, ב ושם צו, סע\"ב. זח\"ג רב, א."]]],[300010118,"צו-ב\n\n[<b>ושמעתי</b> <i>ממורי</i><span data-k=\"sm\"> כי א' הוא סוד אלופו של עולם טמיר וגניז בגויה, ואות ב' הוא ב' אלפין, וכן ג' ג' אלפין עד אות ת' ד' מאות אלפין, א\"כ שורש אותיות התורה שקרוב יותר אל החיות הרוחני אוא\"ס הוא אות א', ואח\"כ יורד והולך ומתלבש זה בזה ונתרחק מן החיות עד אות ת' שהוא מלכות שבמלכות ששם מתלבש בתוך מחשבות רעות וזרות. וצדיקיא שלוחי דמטרוניתא אינון לקשר א\"ע אל האותיות ולהעלותן במחשבה עד מחשבה עליונה, ואז מעלה מתהום עד רום רקיעא את נצוצי השכינה שהיו בלבושים הנ\"ל שנקרא זה לימוד לשמה, לכך זוכה לדברים הרבה שיש כמה מדריגות בכל אות והוא מזכה להעלותן וזוכה עמהם, ודפח\"ח]</span>.\n<b>וז\"ש</b> ויקח מאבני המקום, ר\"ל &lt;שיש&gt; אבני שיש טהור &lt;שהוא סוד א'&gt; שבו הש\"י הנקרא מקום, וישם מראש\"ותיו, לדבק <span data-k=\"sm\">[ראשו ו]</span>מחשבתו לתוך פנימיות האותיות ולהעלותן, גם מרא\"ש-תי\"ו ר\"ל להמשיך אור מראש אל תי\"ו, להעלותה אל <span data-k=\"sm\">[החיות שהיא]</span> א' &lt;שהוא&gt; ראש של תי\"ו כנ\"ל, &lt;להתקרב מן ת' עד א', והוא מזכה להעלותן וזוכה עמהן&gt;.\n[<b>וז\"ש</b> <span data-k=\"sm\">וישכב במקום ההוא, ודרשו בזוהר ויש כ\"ב אותיות התורה וכו', כי אות א' שורש כל הכ\"ב אותיות וכנ\"ל, וכאשר שכב ודבק א\"ע בדביקות וחשיקה אל אותיות התורה נתפשט מהגשמיות]</span>. ויחלום &lt;והנה סולם&gt;, <span data-k=\"sm\">[ר\"ל שראה שכל עוה\"ז הוא כמו חלום, וכמ\"ש אז היינו כחולמים וגו', וראה מתועלת]</span> עוה\"ז <span data-k=\"sm\">[הוא]</span> &lt;אינו אלא&gt; <span data-k=\"sm\">[רק שיהיה לאדם]</span> כמו סולם מוצב ארצה, <span data-k=\"sm\">[שיעשה הכנה בעוה\"ז]</span> שעי\"ז יעלה &lt;ראשו&gt; ומגיע <span data-k=\"sm\">[ראשו]</span> השמימה, <span data-k=\"sm\">[וכמ\"ש בעוללות אפרים]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י ויצא כה</b>,<b> א (פט</b>,<b> ב)</b>\n<i>א' הוא סוד אלופו של עולם</i> – זח\"ג לא, א. חגיגה טז, א. <i>וצדיקייא כו'</i> – זח\"א רמב, א. <i>לימוד לשמה לכך זוכה כו'</i> – אבות פ\"ו מ\"א. <i>ויקח גו' וישם מראשותיו וישכב גו'</i> – ויצא כח, יא. <i>אבני שיש טהור</i> – חגיגה יד, א. <i>הש\"י הנקרא מקום</i> – בר\"ר סח, ט. <i>ודרשו בזוהר</i> – תקו\"ז ת\"ע קלב, ב. <i>אות א' שורש כו'</i> – זח\"ב רלד, ב. <i>ויחלום גו'</i> – ויצא כח, יב. <i>היינו כחולמים</i> – תהלים קכו, א. <i>כמ\"ש בעוללות אפרים</i> – מאמר קסו.\n----- הערות וציונים -----\n<i>א' </i>. .<i> ואות ב' כו'</i> – ראה לעיל סי' מה ופו. לקמן סי' קס, קצ ושנה."]]],[300010119,"צו-ג\n\n[<b>ששמעתי</b> <i>ממורי</i><span data-k=\"sm\"> כי]</span> אדם השלם אם יזדמן לו איזה ביטול תורה ותפלה, יש לו להבין שגם זה הוא ידו ית' שדוחה אותו כדי שיתקרב יותר, בסוד שמאלו תחת לראשי וימינו תחבקני <span data-k=\"sm\">[וכו', ודפח\"ח]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י ר</b>\"<b>פ וישב כח</b>,<b> רע</b>\"<b>א (קא</b>,<b> א)</b>\n<i>שמאלו תחת גו'</i> – שה\"ש ב, ו.\n----- הערות וציונים -----\nבמקורו הוסיף: וזה ששמעתי מן מוהר\"ן, עיין בקונטרס אחרון וכו', וז\"ש שויתי ה' לנגד\"י תמיד וק\"ל. ראה לעיל סי' צג-ג. ומה שציין לקו\"א הובא לקמן סי' שב-א עיי\"ש. וראה צוה\"ר סי' קכ וביאורו בתניא, אגה\"ק סי' כה."]]],[300010120,"צז\n\n<b>&lt;מהבעש\"ט&gt;</b> <span data-k=\"sm\">[שמעתי </span><i>ממורי</i><span data-k=\"sm\">]</span> פירוש הפסוק תפלה לעני כי יעטוף ולפני ה' ישפוך שיחו, ע\"פ משל שהכריז המלך ביום שמחתו כל מי שיבקש דבר מן המלך ימלאו &lt;לו בקשתו&gt; <span data-k=\"sm\">[מבוקשו]</span>, ויש מי שביקש שררה וכבוד, ויש שביקש עושר, ונתנו לכ\"א מבוקשו. והיה &lt;שם&gt; חכם א' שאמר ששאלתו ומבוקשו שידבר המלך בעצמו עמו ג' פעמים ביום, והוטב מאד בעיני המלך מאחר שדיבורו חביב עליו מן עושר וכבוד, לכן ימולא בקשתו שיתנו לו רשות ליכנס בהיכלו לדבר עמו ושם יפתחו לו האוצרות שיקח מן עושר וכבוד ג\"כ. וז\"ש תפלה לעני וגו' לפני ה' ישפוך שיחו, שזה מבוקשו <span data-k=\"sm\">[וכו', ודפח\"ח]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י ויגש לב</b>,<b> ג (קיז</b>,<b> א)</b>\n<i>תפלה לעני גו'</i> – תהלים קב, א.\n----- הערות וציונים -----\nראה לעיל סי' ס. לקו\"י ג, א (סי' כב). והובא ג\"כ באורך, ובתוספת ביאור, במאור עינים, שלהי פ' כי תשא (מ, סע\"ב)."]]],[300010121,"צח\n\n[<b>דשמעתי</b> <i>ממורי</i><span data-k=\"sm\"> פירוש הפסוק]</span> ויגש אליו יהודה ויאמר בי אדני <span data-k=\"sm\">[וגו']</span>, דאי' בברכות לעולם יסדר אדם שבחו של מקום ואח\"כ יתפלל <span data-k=\"sm\">[וכו']</span>, ובמס' ע\"ז איכא דסבירא ליה איפכא <span data-k=\"sm\">[וכו']</span>. וביאר &lt;הבעש\"ט&gt; דמר אמר חדא ומר אמר חדא ולא פליגי. דכתב הרמב\"ן כי כח הפועל במפעל ובריאת העולם <span data-k=\"sm\">[כולו]</span> כהדין קמצא דלבושיה מניה וביה, ובכל מיני צער &lt;בגשמי וברוחני&gt; שם יש ניצוץ קדוש ממנו יתברך אלא שהוא בתוך כמה לבושין. וזהו ענין ז' הנערות הראויות לתת לה מבית המלך. וכאשר יתן לב להבין שגם כאן הוא ית' אתו עמו, אז הוסר ונתגלה הלבוש ונתבטל הצער כו'.\n<b>וז\"ש</b> יסדר שבחו, שזהו שבחו שמלא כל הארץ כבודו, ובכל צרתם לו צר אז לא צער, ויתפלל, כי ממילא יתבטל הצרה אחר שיודע לסדר שבחו בענין &lt;זה&gt; <span data-k=\"sm\">[הנ\"ל (בסוד תכין לבם תקשיב אזניך ששמעתי </span><i>ממורי</i><span data-k=\"sm\"> ג\"כ, עיין במ\"א מזה)]</span>. ומר ס\"ל יתפלל תחלה, והוא ע\"י שמאמין שהשי\"ת שם הוא ג\"כ, ואז יוכל לסדר שבחו <span data-k=\"sm\">[ודפח\"ח]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י ר</b>\"<b>פ ויחי לד</b>,<b> ב (קכד</b>,<b> א)</b>\n<i>ויגש אליו גו'</i> – ויגש מד, יח. <i>לעולם יסדר כו'</i> – ברכות לב, סע\"א. <i>ובמס' ע\"ז</i> – ע\"ז ז, ב. <i>כהדין קמצא כו'</i> – בר\"ר כא, ה. <i>ז' הנערות</i> – אסתר ב, ט. <i>שמכה\"כ</i> – ישעי' ו, ג. <i>ובכל צרתם גו'</i> – ישעיה סג, ט. <i>תכין לבם גו'</i> – תהלים י, יז. <i>עיין במ\"א מזה</i> – לקמן סי' קלו.\n----- הערות וציונים -----\n<i>ובכל מיני צער שם יש כו'</i> – ראה לעיל סי' כ ובהערות שם, וסי' פה.\n<i>ענין ז' הנערות כו'</i> – ראה לקמן סי' רז-ב.\n<i>וכאשר יתן לב כו'</i> – ראה לעיל סי' נא וסו, ובהערות שם. עיין לקמן סי' קטו."]]],[300010122,"צט\n\n<b>&lt;מהבעש\"ט.</b> צריך&gt; להעלות מ\"ז <span data-k=\"sm\">[הוא]</span> דרך ג' קוין, וצריך לתת לב על כל מ\"ז מאיזה קו היא להעלותה בשרשה. וג' קוין אלו נקראים אבות כנודע, והקליפה נקרא קללה שהיא המ\"ז, והיא גלות השכינה בתוך עמקי הקליפות. וז\"ש קרבה אל נפשי גאלה, ר\"ל להעלות חלקי הנפש שהיא ניצוצי <span data-k=\"sm\">[השכינה]</span> &lt;הקדושה&gt; מתוך הקליפה אל הקדושה נקרא גאולה, <span data-k=\"sm\">[וכאשר שמעתי </span><i>ממורי</i><span data-k=\"sm\">]</span> כי צריך להתפלל על גלות נפשו רוחו ונשמתו שאצל יצה\"ר <span data-k=\"sm\">[וכו', ודפח\"ח]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י ס</b>\"<b>פ ויחי לה</b>,<b> ד (קכט</b>,<b> ב)</b>\n<i>וג' קוין אלו כו'</i> – זח\"ג קעט, ב. תקזו\"ח קא, א. <i>והקליפה נק' קללה</i> – זח\"ב רכד, א. <i>שהיא המ\"ז</i> – תקו\"ז ת\"ע קל, ב. <i>קרבה גו'</i> – תהלים סט, יט.\n----- הערות וציונים -----\n<i>להעלות מ\"ז דרך ג' קוין כו'</i> – ראה לעיל סי' לט, ועיי\"ש בהערות.\n<i>ג' קוין כו'</i> – ראה לקמן סי' קנב ושפג.\n<i>גלות השכינה</i> – ראה לקמן סי' קס ורצ."]]],[300010123,"ק-א\n\n<b>וארא</b> אל אברהם כו' באל שדי וגו'. &lt;מבעש\"ט&gt; <span data-k=\"sm\">[שמעתי </span><i>ממורי</i><span data-k=\"sm\">]</span> דברים נוראים בענין מיתוק דינין ש\"ך ופ\"ר והמתקת הרהורים ע\"י שם שדי וחלופו כה\"ת, וגם שם הוי\"ה בחלוף &lt;כ\"ו&gt;. <span data-k=\"sm\">[ורשמתי ראשי פרקים בנייר בפ\"ע, ובזה יבואר פסוק זה ג\"כ והבן, והש\"י יכפר]</span>. . .",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י שמות לו</b>,<b> ריש ע</b>\"<b>ב (קלד</b>,<b> א)</b>\n<i>וארא אל אברהם גו'</i> – וארא ו, ג.\n----- הערות וציונים -----\n<i>מיתוק דינין ש\"ך ופ\"ר</i> – ראה לקמן סי' קס.\n<i>ע\"י שם שד-י</i> – ראה לקמן סי' ק-ב.\n<i>וחלופו כה\"ת</i> – שם הח' משם ע\"ב (זח\"ב ער, א. זו\"ח שה\"ש סח, ד), והוא האותיות שאחר שד-י למפרע. עיין שער מאמרי רשב\"י ס\"פ בשלח, ושם שער מאמרי רז\"ל בביאור שבת קיט, ב ושם בהגהה ב.\n<i>וגם שם הוי' בחלוף</i> – שהוא שם כוז\"ו והוא האותיות שאחר הוי' (ראה זח\"א כג, א וזח\"ב רסא, ב) עיין רבנו בחיי פ' וישב לח, ה. ע\"ח ש\"מ ספי\"ג. ולקמן סוף סי' קטו, ובהערות שם.\n<i>(כ\"ו)</i> – נראה שצ\"ל כוז\"ו."]]],[300010124,"ק-ב\n\n<b>&lt;וכשיאור&gt;</b> <span data-k=\"sm\">[כשנתעורר]</span> שמחה בעולם ידע שהיא מדת אברהם איש החסד <span data-k=\"sm\">[וכו']</span>. וז\"ש באל שדי, <span data-k=\"sm\">[כי שמעתי </span><i>ממורי</i><span data-k=\"sm\">]</span> פירוש אל שדי שאמר לעולמו די, כי העולמות היו יורדין ומתפשטין עד עמקי הקליפות, ופן ח\"ו שלא יהיה אז מחמת עמקי הקליפות הרע גובר עד שאמר די כו', א\"כ יש למתק ולהעלות כל ענינים לשרשן ע\"י שם זה <span data-k=\"sm\">[והבן]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י שמות לו</b>,<b> ג (קלה</b>,<b> א)</b>\n<i>כשנתעורר שמחה כו'</i> – זח\"א קטז, סע\"א. <i>אברהם איש החסד</i> – זח\"ג רלא, א. שם שב, א. <i>בא</i>-<i>ל ש'</i> – וארא ו, ג. <i>פירוש </i>. .<i> שאמר לעולמו די</i> – חגיגה יב, א. תנחומא מקץ י.\n----- הערות וציונים -----\n<i>יורדין ומתפשטין עד עמקי הקליפות</i> – ראה לקמן סי' קנב-א.\n<i>ולהעלות כו' ע\"י שם זה</i> – ראה לקמן סי' קב."]]],[300010125,"קא\n\n<b>וגם</b> הקמותי את בריתי אתם <span data-k=\"sm\">[וגו']</span>, &lt;פי' הבעש\"ט&gt; <span data-k=\"sm\">[כי שמעתי </span><i>ממורי</i><span data-k=\"sm\">]</span> בא חבקוק והעמידן על אחת שנא' וצדיק באמונתו יחיה, כי מתחלה היה תענית יום א' מספיק לכמה דברים נוראים.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י שמות לו</b>,<b> ג (קלה</b>,<b> א)</b>\n<i>וגם הקמותי גו'</i> – וארא ו, ד. <i>בא חבקוק כו'</i> – מכות כד, א. <i>וצדיק באמונתו יחיה</i> – חבקוק ב, ד.\n----- הערות וציונים -----"]]],[300010126,"קב\n\n<b>וארא</b> אל <span data-k=\"sm\">[אברהם יצחק ויעקב]</span> &lt;האבות&gt; באל שדי, שהוא סוד שש קצוות, ואכתי שמי ה' לא נודעתי, שיתן הדעת בכל דרכיך דעהו, שהוא דבר נפלא, <span data-k=\"sm\">[כמו ששמעתי </span><i>ממורי</i><span data-k=\"sm\"> דברים פרטיים בזה איך]</span> &lt;כי צריך ל&gt;יתן הדעת בכל דבר גשמי ג\"כ להעלותו ולקשרו ולחבר האהל להיות אחד <span data-k=\"sm\">[אמן נצח סלה ועד ודי בזה. וכדי להבינך זה אזכור אפס קצה ששמעתי </span><i>ממורי</i><span data-k=\"sm\">]</span> &lt;וכן&gt; בלומד דבר עמוק ואין מבין הוא &lt;מדת&gt; מלכות, וכשנתן דעת להבין וירד לעומקו, אז קישר וחיבר מלכות בבינה <span data-k=\"sm\">[ודפח\"ח]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י ס</b>\"<b>פ וארא לט</b>,<b> א (קמה</b>,<b> א)</b>\n<i>וארא גו' ושמי ה' גו'</i> – וארא ו, ג. <i>בכל דרכיך דעהו</i> – משלי ג, ו. <i>ולחבר האהל להיות אחד</i> – ע\"פ תרומה כו, יא. <i>בלומד דבר עמוק כו'</i> – תקזו\"ח צט, ב.\n----- הערות וציונים -----\n<i>בכל דרכיך </i>. .<i> יתן הדעת בכל כו'</i> – ראה רמב\"ם הלכות דעות פ\"ג. טושו\"ע או\"ח סי' רלא. לקמן סי' רפב-א. וראה צוה\"ר סי' צח וצט.\n<i>בלומד דבר עמוק כו'</i> – ראה לעיל סי' סז-א ובהערות שם.\n<i>וכשנתן דעת כו' בבינה</i> – להעיר מתקו\"ז יג, ריש ע\"ב שכינתא עלאה (בינה) דאיהי תורת חסד ובה לב מבין. וראה לעיל בהערות לריש סי' פב."]]],[300010127,"קג\n\n[<b>ששמעתי</b> <i>ממורי</i><span data-k=\"sm\"> בסוד]</span> אחור וקדם צרתני, כשהוא &lt;בגשמיות&gt; בסוד אחור, אח\"כ כשחוזר ועולה למדריגה הנק' קדם מעלה גם אותן המדריגות הנק' אחור, <span data-k=\"sm\">[וזהו אחור]</span> וקדם צרתני <span data-k=\"sm\">[ודפח\"ח]</span>.\n<b>וז\"ש</b> ראה חיים עם אשה <span data-k=\"sm\">[אשר אהבת]</span>, &lt;דאפי'&gt; <span data-k=\"sm\">[כי]</span> עם האשה, <span data-k=\"sm\">[שהם מדריגות תחתונות]</span> &lt;שהם&gt; <span data-k=\"sm\">[כגון]</span> ספורים ודבורי ועסקי גשמיים, &lt;ראה חיים, פירוש להעלות הדבורים ושיהיו בקדושה&gt; <span data-k=\"sm\">[יכול לעשות מזה מיין נוקבין ע\"ד הנ\"ל, וממשיך עי\"ז מוחין הנקרא חיים]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י שמות לו</b>,<b> ב (קלד</b>,<b> ב)</b>\n<i>אחור וקדם גו'</i> – תהלים קלט, ה. <i>ראה חיים גו'</i> – קהלת ט, ט.\n----- הערות וציונים -----\nראה לקמן סי' שפד. רג\"כ סי' קלט וקפד.\n<i>עם האשה כו' כגון ספורים כו'</i> – ראה לעיל סי' לב-ב ועה, ולקמן סי' קנט ושפד."]]],[300010128,"קד\n\n<b>&lt;מהבעש\"ט&gt;</b> ואלה שמות &lt;בני ישראל&gt; <span data-k=\"sm\">[וגו']</span>, <span data-k=\"sm\">[דשמעתי </span><i>ממורי</i><span data-k=\"sm\">]</span> כמו שתפיסת הגוף הוא בגשמי שאוחז בגופו, כך תפיסת הנשמה הוא ע\"י קריאת שמו, גם בישן ניער משנתו בקראו שמו.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י שמות לז</b>,<b> ריש ע</b>\"<b>ד (קלט</b>,<b> א)</b>\n<i>ואלה שמות גו'</i> – שמות א, א.\n----- הערות וציונים -----\nראה צ\"פ פ' שמות ו, סע\"ג (לה, ב): קבלתי ממורי זל\"ה כי השם של האדם היא הנשמה, ונתן מופת לזה כאשר האדם ישן ובקראו שמו הוא נתעורר וכו', וכעין זה מפורש בזוהר (זח\"א כ, ב) אדם מלגאו והגוף נקרא בשר אדם וכו' יעו\"ש. ועיין מדל\"י סי' רמד (רנו), ובאו\"ת פ' בראשית סי' יד ביתר אריכות. ועיי\"ע קונטרס תשובות וביאורים לכ\"ק אדמו\"ר זי\"ע סי' א. (ובאג\"ק ח\"א סי' קנד)."]]],[300010129,"קה\n\n<b>יש</b> ב' סוגי רשעי ישראל, א' בהסתר וא' בפהרסיא. וההפרש ביניהם, &lt;דפי' הבעש\"ט ע\"פ&gt; <span data-k=\"sm\">[דשמעתי </span><i>ממורי</i><span data-k=\"sm\"> פסוק תהלים סימן ל\"ז]</span> ראיתי רשע עריץ וגו' ויעבור והנה איננו ואבקשהו ולא נמצא <span data-k=\"sm\">[וגו']</span>, &lt;והק'&gt; <span data-k=\"sm\">[ואמר]</span> למה יבקשהו לרשע שכבר איננו, וביאר, כי אחריו יקום רשע יותר גרוע ממנו, לכך יבקשהו לראשון <span data-k=\"sm\">[ודפח\"ח]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י בא לט</b>,<b> ג (קמו</b>,<b> א)</b>\n<i>ראיתי גו' ולא נמצא וגו'</i> – תהלים לז, לה-לו.\n----- הערות וציונים -----"]]],[300010130,"קו\n\n<b>ופרעה</b> הקריב. &lt;פי' הבעש\"ט&gt; <span data-k=\"sm\">[והנה קבלתי </span><i>ממורי</i><span data-k=\"sm\">]</span>, כשהרע הוא גורם טוב נעשה כסא אל הטוב והכל טוב גמור, כמעט ביטול הקליפות מעין העתיד. הגם שיש בזה דברים עמוקים לענין מ\"ז וכו', ודי בזה. <span data-k=\"sm\">[ואפשר שזהו כוונת חז\"ל]</span> &lt;ושארז\"ל&gt; אליעזר עבד אברהם ע\"י הטובה שעשה לאברהם אבינו יצא מכלל ארור ונכנס לכלל ברוך, והכוונה ע\"ד הנ\"ל, <span data-k=\"sm\">[והבן]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י בא מג</b>,<b> ג (קסא</b>,<b> א)</b>\n<i>ופרעה הקריב</i> – בשלח יד, י. <i>אליעזר עבד אברהם כו'</i> – בר\"ר ס, ז.\n----- הערות וציונים -----\nראה לעיל סי' כו וע. לקמן סי' קפח ובהערות שם."]]],[300010131,"קז\n\n[<b>ושמעתי</b> <span data-k=\"sm\">בשם </span><i>מורי</i><span data-k=\"sm\">]</span> טעם לענג החומר בשבת הוא מצוה, שעי\"ז יוכל הצורה לשמוח יותר בדביקות הש\"י, והוא עפ\"י משל לבן מלך שבא לו כתב מאביו בהיותו בשבי כו' <span data-k=\"sm\">[ודפח\"ח]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י בא מג</b>,<b> ד (קסב</b>,<b> א)</b>\n<i>לענג החומר בשבת הוא מצוה</i> – שבת קיח, ב ואילך. רמב\"ם הל' שבת פ\"ל.\n----- הערות וציונים -----\nהמשל הובא לקמן סי' שצב ובהערות לסי' שח, ובכמה מקומות בתוי\"י ביתר אריכות. ועיין מדל\"י סי' קז (קיח) בהרחבת הביאור (קטע משם הובא לקמן סי' שצה-ב). לתוכן סימן זה רג\"כ לקמן סי' רצה."]]],[300010132,"קח\n\n<b>והיה</b> כי יבואו עליך כל הדברים האלה הברכה והקללה וגו' והשבות אל לבבך כו', <span data-k=\"sm\">[ויש להבין, הא עיקר התשובה הוא אחרי היסורין, וכמו שאמר לעיל הקללות והיסורין מקיימין אתכם, ור\"ל שמכח זה שב בתשובה, וא\"כ למה הזכיר כאן הברכה והקללה, דהוי ליה לומר רק הקללה]</span>. &lt;וקשה, בשלמא על ידי יסורין אדם עושה תשובה, אבל למה הזכיר הברכה&gt;.\n[<b>ונ\"ל</b> <span data-k=\"sm\">דשמעתי </span><i>ממורי</i><span data-k=\"sm\"> פירוש הפסוק]</span> &lt;ופי' הבעש\"ט ע\"פ&gt; אל נקמות ה' אל נקמות הופיע, ע\"פ משל לאיש כפר א' שמרד במלך שהכה ורגם איקונין של מלך או כיוצא בזה, ומיד עשה המלך אותו לראש והעלהו ממדריגה למדריגה עד שנעשה משנה למלך, וכל מה שהיטיב המלך עמו יותר והביאו ליותר מדריגה וראה יותר כבוד המלך ומשרתיו והנהגותיו, היה יותר צער לזה שהיה בן כפר בזכרו שמרד נגד המלך הגדול הרחמן הזה, ומה שהיה ראוי לעונש הוא מטיב עמו יותר. והמלך עשה בכוונה מכוונת, שאם היה ממיתו היה צער לפי שעה ותו לא, משא\"כ בדרך הנ\"ל מצטער כל ימיו ומוסיף תמיד כשעולה ליותר גדולה מוסיף יותר צער על צערו איך מלאו לבו למרוד עיני כבודו. וז\"ש אל נקמות ה', ר\"ל שנקמות הש\"י הוא ע\"י מדת הרחמים שלא כמלך בשר ודם, והוא כי אל נקמות הופיע, ר\"ל שהנקמה הוא במה שהופיע לו מגדולתו, ובראותו גדולת המלך ובזכרו שמרד נגד מלך זה אין לך צער גדול מזה <span data-k=\"sm\">[ודפח\"ח]</span>.\n<b>וא\"כ</b> הכי נמי ר\"ל כי יבואו עליך הברכה והקללה והשבות אל לבבך <span data-k=\"sm\">[וכו']</span>, ר\"ל האדם שחטא ומרד עיני כבודו ית' המלך הגדול והנורא רב ושליט עיקרא ושרשא דכל עלמין, והיה ראוי לעונשים קשים ומרים, והש\"י משפיע לו הברכה, א\"צ יותר קללה וצער מזה שיודע שמרד בו, והש\"י ברחמיו משפיע לו כל טוב, בודאי ראוי שיתמרמר כל ימיו בבכיה וצער על כל מעשיו שמרד בו, וע\"ד הנ\"ל. ואז בראות המלך צערו זה שהוא יותר אצלו &lt;מעונשים&gt; מתכפר לו.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י בא מה</b>,<b> א (קסו</b>,<b> ב)</b>\n<i>והי' כי יבואו גו' והשבות גו'</i> – נצבים ל, א-ב. <i>הקללות והיסורין מקיימין אתכם</i> – רש\"י נצבים כט, יב. ע\"פ תנחומא נצבים א. <i>א</i>-<i>ל נקמות ה' גו'</i> – תהלים צד, א. <i>רב ושליט כו'</i> – זח\"א יא, ב.\n----- הערות וציונים -----\n<i>ע\"פ משל כו'</i> – להעיר מהמשל בשבט מוסר פי\"ב (אלא ששם באופן אחר)."]]],[300010133,"קט\n\n<b>&lt;מהבעש\"ט&gt;</b> <span data-k=\"sm\">[שמעתי </span><i>ממורי</i><span data-k=\"sm\">]</span> מי שרוצה לפטור מהצר והמיצר והוא נוסע אחריו, משל לאשה יולדת שהלכה למקום אחר לפטור מחבלי הלידה והצער הולך אחריה. ועצה היעוצה שיתפלל להש\"י ויפטר מהצער. וז\"ש מן המיצר קראתי יה ענני במרחב יה <span data-k=\"sm\">[ודפח\"ח]</span>.\n<b>וז\"ש</b> והנה מצרים נוסע אחריהם, אז הבינו זה, לכך ויצעקו בני ישראל אל ה'. ובאמת נאמר אז כאשר ראיתם את מצרים היום לא תוסיפו לראותם עוד עד עולם.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י בשלח מז</b>,<b> סע</b>\"<b>ב (קעה</b>,<b> א)</b>\n<i>מן המיצר גו'</i> – תהלים קיח, ה. <i>והנה מצרים גו' ויצעקו גו'</i> – בשלח יד, י. <i>אשר ראיתם את מצרים גו'</i> – בשלח יד, יג.\n----- הערות וציונים -----"]]],[300010134,"קי-א<i>[ftnref_1_טז]</i>\n\n[<b>בפסוק</b> <span data-k=\"sm\">ויהי בשלח פרעה את העם ולא נחם דרך וכו'. הביאור]</span> כי אדם עולם קטן, ויש בו פרעה ומצרים וכו' והורה הכתוב סדר התשובה שיהיה בהדרגה להסיב דרך ולא בפעם א', <span data-k=\"sm\">[בדרך התשובה להתקרב אליו ית' בפעם א', כי זה לסבה]</span> שיתבטל מכל וכל, <span data-k=\"sm\">[רק בשקידה רבה וכו' ובזה יובן]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י בשלח מז</b>,<b> רע</b>\"<b>ג (קעה</b>,<b> סע</b>\"<b>א)</b>\n<i>ויהי בשלח פרעה גו'</i> – בשלח יג, יז. <i>אדם עולם קטן</i> – תנחומא פקודי ג.\n----- שולי הגליון -----\n[ftn_1_טז]) <i>קטע זה צ\"ל סימן בפ\"ע</i>,<i> ולפני כל סי' קי</i><i>ב</i>, <i>ובכש\"ט הכניסו שלא במקומו (בהשמטת כמה מלים) בתוך סי' קי</i><i>ב</i>.\n----- הערות וציונים -----\n<i>כי האדם עולם קטן ויש בו כו'</i> – ראה לקמן סי' שצג, כמו שלימד הבעש\"ט וכו' שאומרים כל תלמידי הבעש\"ט ז\"ל בשמו שכל התורה צריך להמצא תמיד וכו'. ולקמן סי' שב-ב שהוא בכל אדם ובכל זמן, וכן במדל\"י רס\"י ד (ג) כי הנה התורה היא תמידית בכל דור ודור כו'. ובאו\"ת ר\"פ ויצא, רס\"י לח, שהתורה היא קדומה כו' שסיפור המעשה הזאת היא ההוה תמיד וגם באדם הנקרא עולם קטן יש בו ג\"כ כו'. וראה עוד לקו\"י סוף סי' סד. וענין זה מוזכר פעמים רבות בספרי בעל התוי\"י (ראה לקמן בהערות לסי' קטו).\n<i>ויש בו פרעה ומצרים</i> – אולי כונתו למש\"כ בלקו\"ת להאריז\"ל פ' וישב ופ' שמות דפרעה הוא היצה\"ר (וכן בזח\"ב סז, ב), ומצרים הוא מיצר הגרון אלא מצד האחוריים. ולהער מתניא פמ\"ז בענין יציאת מצרים בכל יום ויום. ראה ג\"כ לקמן בהערות לסי' קטו.\n<i>שיהיה בהדרגה כו'</i> – להעיר מלקמן סי' רנט וסוף סי' רפא. צוה\"ר סי' לב וסה. לקו\"י סי' מט וקעה. מדל\"י סי' קלח (קמו בסופו)."]]],[300010135,"קי-ב\n\n<b>ויהי</b> בשלח פרעה את העם ולא נחם אלהים דרך ארץ פלשתים כי קרוב הוא <span data-k=\"sm\">[וגו']</span>. &lt;מהבעש\"ט ז\"ל&gt; <span data-k=\"sm\">[ושמעתי בשם </span><i>מורי</i><span data-k=\"sm\">]</span> כי כשהזכרים קודם בשם הוי\"ה &lt;ר\"ל י\"ו קודם הההי\"ן&gt; אז הוא חסד גובר, &lt;ואם לאו גובר השכחה הנקרא פרעה&gt; –\n(<b>כי</b> <span data-k=\"sm\">האדם עולם קטן ויש בו פרעה ומצרים, והורה הכתוב סדר התשובה שיהיה בהדרגה להסיב דרך ולא בפעם א' שא\"כ יתבטל מכל וכל)</span><i>[ftnref_1_יז]</i> <span data-k=\"sm\">–</span>\n<b>&lt;וז\"ש&gt;</b> <span data-k=\"sm\">[ומה שגובר השכחה הנקרא פרעה]</span> עכשיו, ויהי בשלח פרעה את העם, שהם איברי האדם שהיו עד עכשיו מוכנעים תחת יד פרעה ועתה שילח את העם שהם איבריו לחירות, ולא נחם אלהים דרך ארץ פלשתים, כי יש בחינה הנקרא דרך, שם ס\"ג ושם אהי\"ה קס\"א גי' דרך, אשר משם ניזונים אפילו הרשעים, כי עד שם אינו מגיע פגם וחטא בני אדם התחתונים, ועז\"נ אם (תרשע) [חטאת] מה תפעל בו, ולכך תשובה מהני כי שם לא הגיע פגם החטא, אם חטא בזנות לא מתעורר שם רק בחינת אהבה. רק למטה עשה רשימות רעות ע\"י חטאו, ובעושה תשובה עשה רשימות טובים וניתקן הכל כי העלה המדריגות עד הבינה שהיא אהי\"ה וכו'. ואמר שיש בעמקות הזה דברים נפלאים והמשכיל יבין.\n<b>וז\"ש</b> ולא נחם אלהים דרך ארץ פלשתים, כי מן הדרך הזה ארץ &lt;שם&gt; פלשתים שהם הקליפות ג\"כ ניזונים, ולא נחם דרך ההוא, כי קרוב הוא, ר\"ל כי השכחה הנקרא פרעה קרוב הוא, ופן יראה בחינה זו הנקרא דרך ע\"ד הנ\"ל, ויש מקום בזה כו', ותיכף בהעלות על דעתו זה אז קרוב לחזור אל פרעה שהיא השכחה, לכך ויסב <span data-k=\"sm\">[וגו']</span>, ודפח\"ח, והש\"י יכפר <span data-k=\"sm\">[מה שנכתוב גם בקצרה]</span>.\n<b>ואגב</b> שזכינו לזה נזכיר <span data-k=\"sm\">[ג\"כ מה ששמעתי בשם </span><i>מורי</i><span data-k=\"sm\">]</span> &lt;הבעש\"ט ז\"ל על&gt; עשר מכות לפרעה, כי השכחה הנקרא פרעה, מכת דם, שהוא שם מ\"ה חסר א', היא מכה לפרעה שהיא השכחה, משא\"כ לישראל היה מים, שם מ\"ה, מים שאין להם סוף כו'. וכן צפ\"ר דע\"ה, כי צפר לשון צפרא נהיר, ודעה הוא היפך השכחה הנקרא פרעה, וכך היה זה מכה לפרעה משא\"כ לישראל היה צפ\"ר דע\"ה, והבן <span data-k=\"sm\">[ודפח\"ח]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י בשלח מז</b>,<b> ג (קעה</b>,<b> ב)</b>\n<i>ויהי בשלח גו'</i> – בשלח יג, יז. <i>כשהזכרים כו' ואם לאו כו'</i> – ראה תקו\"ז י, א. <i>השכחה הנקרא פרעה</i> – ראה בהערות לכאן. <i>דרך שם ס\"ג ושם אה' קס\"א</i> – שער ההקדמות, פרק בערכי הכינויין אות הדלת. <i>אשר משם ניזונים כו'</i> – זח\"ב רטו, א. <i>אם חטאת גו'</i> – איוב לה, ו. <i>הבינה שהיא אה'</i> – זח\"ג קח, ב. <i>צפרא נהיר</i> – ת\"א מקץ מד, ג.\n----- שולי הגליון -----\n[ftn_1_יז]) <i>המובא כאן בחצ\"ע אין כאן מקומו והובא לעיל סי' קי</i><i>א</i>.\n----- הערות וציונים -----\n<i>כשהזכרים קודם בשם הוי' כו'</i> – אותיות שם הוי' כסדרן ה\"ה אב (יו\"ד) ואם (ה') בן (ו) ובת (ה' בתראה) רחימו שלימו ודא תפארת (זח\"ג יא, ב וראה שם רצ, ב), ותפארת קו המכריע ומטה כלפי חסד (תניא, אגה\"ק סי' יב). ועיין תקו\"ז רתנ\"ו פט, ב.\n<i>י\"ו קודם הההי\"ן</i> – י\"ו דכורין וההי\"ן נוקבא, ראה תקו\"ז י, א. וראה זח\"ב קעח, ב. זח\"ג קכב, סע\"ב ושם קפג, ב. וראה זו\"ח, סוף מדרש שה\"ש עד, ג (ושם בהוספה עה, א).\n<i>ואם לאו</i> – עיי\"ש בתקו\"ז דאז דינא אחזי בעלמא כו'.\n<i>השכחה הנקרא פרעה</i> – ראה לקו\"ת להאריז\"ל, פ' וישב ד\"ה ויהי אחר, דפרעה כללות כל האחוריים של הגרון ונקרא עורף כי פרעה גי' עורף (עם הכולל כמ\"ש בשער הפסוקים פ' וישב) גם פרעה אותיות עורף (שם פ' שמות ד\"ה ויקם, פרעה יש בו אותיות הערף). ומבואר בע\"ח ש\"ט פ\"ב ושם שט\"ו פ\"ו דהשכחה מצד אחוריים (בחי' העורף), וראה בארוכה בשער המצות ר\"פ ואתחנן. ועיין אוה\"ת לכ\"ק אדמו\"ר הצ\"צ, פ' בשלח ד\"ה אמר אויב, שפרעה במילוי (פא – ריש – עין – הא) גימטריא תשכ\"ח (כנראה עם הכולל), ועיי\"ע פע\"ח שער חג המצות פ\"א.\n<i>שם ס\"ג ושם אהי' קס\"א גי' דרך</i> – כלומר שם ס\"ג שהוא שם הוי' במילוי יו\"ד ה\"י וא\"ו ה\"י, ביחד עם שם אהי' במילוי אל\"ף ה\"י יו\"ד ה\"י שהוא קס\"א, בגי' דרך, כמבואר בשער ההקדמות, ערכי הכנויים אות ד'.\n<i>אשר משם ניזונים כו'</i> – ראה זח\"א קצז, ב וזח\"ב לא, סע\"א.\n<i>ארץ פלשתים שהם הקליפות</i> – ראה מאו\"א מערכת פ' אות טו. קהלת יעקב, ע' פלשתים. ומבואר באוה\"ת להצ\"צ פ' בשלח, ע' שסז ואילך.\n<i>מכת דם שהוא שם מ\"ה חסר א'</i> – ראה שער הכונות, ענין הפסח דרוש א (קמא, ב). וראה עמה\"מ, שער קרית ארבע פכ\"ג.\n<i>מכה לפרעה </i>. .<i> משא\"כ לישראל כו'</i> – משנת ר' אליעזר פי\"ט. תנחומא וארא יג.\n<i>שם מ\"ה מים</i> – שם מ\"ה במילוי מ\"ם ה\"ה גי' מים. ועיין ע\"ח של\"ט דרוש ו.\n<i>וכן צפ\"ר דע\"ה</i> – ראה ילק\"ש וארא, שלהי רמז קפב (מאליהו רבה פ\"ז) ותעל הצפרדע צפור שיש בו דעה."]]],[300010136,"קי-ג<i>[ftnref_1_יח]</i>\n\n<b>(נודע</b> שהאדם מורכב מחומר וצורה שהוא הנשמה והגוף. והנה הנשמה תתלהב תמיד לידבק בקונה, רק סיבב החומר מפסיק הדביקות ומתאוה גם לחומריים משגל ואכילה &lt;ושתיה&gt; שהיא ג\"כ צורך גבוה לברר ניצוצין וכיוצא בזה, כ\"א לזמנים ידועים יכול לגבור הצורה על החומר לידבק בו ית' בסוד והחיות רצוא ושוב, ונקרא קטנות וגדלות, וכמו ששמעתי <span data-k=\"sm\">[</span><i>ממורי</i><span data-k=\"sm\">]</span> &lt;הבעש\"ט&gt; <span data-k=\"sm\">[בזה]</span> סוד הצמצום שהוא מיניה וביה, וסוד ג' רישין <span data-k=\"sm\">[ודפח\"ח]</span>).",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י ר</b>\"<b>פ יתרו מח</b>,<b> ב (קעח</b>,<b> א)</b>\n<i>והחיות רצו\"ש</i> – יחזקאל א, יד. <i>מיניה וביה</i> – בר\"ר כא, ה.\n----- שולי הגליון -----\n[ftn_1_יח]) <i>בכש\"ט קטע זה בחצ\"ע ואינני יודע טעם לזה.</i>\n----- הערות וציונים -----\n<i>לברר ניצוצין</i> – ראה לעיל סי' נג ובהנסמן שם בהערות.\n<i>בסוד והחיות רצו\"ש</i> – ראה לעיל סי' לד וצ. לקמן סי' קכא, קס, קעח, שנו, שסד ושצד.\n<i>קטנות וגדלות</i> – ראה לעיל סי' י, לז, עז וצ. לקמן סי' קכא, קכג, קלט, קנב, רב, ריז-א, שנו, שסו ושצד.\n<i>סוד הצמצום שהוא מיניה וביה</i> – ראה לעיל סי' נא וצח. וראה תניא פכ\"א, ושם שהיוה\"א שלהי פ\"ז.\n<i>וסוד ג' רישין</i> – ראה לקמן סי' קסא וקסד-ב. וראה תוי\"י פ' ויחי לה, ב בהג': מ\"ש חז\"ל אע\"פ שאלו אוסרין ואלו מתירין אלו ואלו דא\"ח, וכי אפשר זה, ושמעתי (ראה לעיל סי' נא-א) כי בששה קצוות יש ימין ושמאל, משא\"כ בג' ראשונות הכל אחדות אחד, וז\"ש אלו ואלו דא\"ח הנקרא בינה סוד ג\"ר והבן. והנה נודע כי הב\"ד הם סוד ג' רישין וכאשר שמעתי ממורי, עיין בקו\"א (לקמן סי' קסא וקסד-ב), א\"כ כל בי\"ד מישראל יכול להעלות בשרשן לעשות מן שמאל ימין ונעשה הכל אחדות א' וכו'."]]],[300010137,"קיא-א\n\n<b>&lt;מהבעש\"ט</b> בשם הראשונים&gt; <span data-k=\"sm\">[שכתבו הראשונים]</span> בראוי לידע סוד אחדותו יתברך, כי בכל מקום שאני תופס ואוחז בקצה וחלק &lt;מן&gt; <span data-k=\"sm\">[מחלק]</span> האחדות הרי אני תופס כולו <span data-k=\"sm\">[וכן שמעתי </span><i>ממורי</i><span data-k=\"sm\"> והבן]</span>.\n<b>והנה</b> מאחר שהתורה והמצות נאצלו מעצמותו ית' שהוא אחדות האמיתי, אם כן כשמקיים מצוה אחת על מכונה ובאהבה, שהיא הדביקות בו, ותופס במצוה זו חלק האחדות, א\"כ כולו בידו כאלו קיים כל המצות שהם כללות אחדותו <span data-k=\"sm\">[פרצוף שלם כבי\"כול. וכן כתב בזוהר נשא דף קכד דמקיים מצוה א' על מתכונתו סגי. וכיון הרמב\"ם לדעת חכמי האמת ברוח קדשו, גם שלא ראה חכמה זו כשכתב ספרו הנזכר לעיל כנודע]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י יתרו מט</b>,<b> ב (קפב</b>,<b> א)</b>\n<i>בשם הראשונים</i> – פי' הר\"י יעב\"ץ למס' אבות פ\"ד מ\"ב ד\"ה הוי רץ. ס' חרדים, בסוף מע' מצוות התלויות בא\"י. <i>בזוהר</i> – זח\"ג קכד, רע\"א. <i>הרמב\"ם</i> – פי' המשניות סוף מס' מכות.\n----- הערות וציונים -----\nנשנה לקמן סי' רנ, ועיי\"ש הרישא דלא הובא כאן.\n<i>בכל מקום שאני תופס כו'</i> – ראה לעיל סי' סה. עיין לקמן בהוספות סי' רכז.\n<i>וכתב בזוהר כו'</i> – וז\"ל: וכל מאן דקיים חד כדקא יאות כאלו מקיים רמ\"ח פקודין דעשה דלית פקודא דלאו איהו כלילא מכלהו רמ\"ח. וראה תקו\"ז ת\"ע קלא, ב כל פקודין אינון משולבין אלין עם אלין כו'. וזח\"ג רכח, ב ולית פקודא דלאו איהי שקילא לכל אורייתא כו' ובג\"ד כל מצוה איהי שקילא לתרי\"ג.\n<i>שלא ראה חכמה זו</i> – ראה שער הגלגולים של\"ו וספר הגלגולים פס\"ד.\n<i>כשכתב ספרו הנ\"ל</i> – משא\"כ בסוף ימיו כמש\"כ במגדל עז להלכות יסוה\"ת פ\"א ה\"י. תשובות הר\"מ אלשקר סי' קיז. נחלת אבות ספ\"ג דאבות. עבוה\"ק, חלק העבודה פי\"ג. שומר אמונים, ויכוח א' סי' יג. וראה שם הגדולים להחיד\"א, בריש ערך הרמב\"ם. ולהעיר מס' ההקדמה והפתיחה להרה\"צ הגרח\"ה מראדזין, ושו\"ת אור המאיר סי' לא והג' בסוה\"ס."]]],[300010138,"קיא-ב\n\n<b>כשנופל</b> עליו איזה שמחה ידבק בשמחתו יתברך <span data-k=\"sm\">[ולדבק בו]</span>, שהוא שורש הכל, <span data-k=\"sm\">[וכאשר קבלתי </span><i>ממורי</i><span data-k=\"sm\"> שאם יראה מחשבות זרות, אם מענין הרהורי תאות המשגל ידבק בשרשו שהוא חסד, וכיוצא בזה, וכבוד ה' הסתר דבר, ודפח\"ח]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י יתרו נ</b>,<b> סע</b>\"<b>א (קפה</b>,<b> א)</b>\n----- הערות וציונים -----\nראה לקמן סוף סי' קמו, ורג\"כ לעיל סי' לט ובהערות שם.\n<i>וכבוד ה' הסתר דבר</i> – ראה מה שהארכתי בזה בסוף ההערות לסי' לט."]]],[300010139,"קיב\n\n<b>&lt;מהבעש\"ט</b> ז\"ל&gt; <span data-k=\"sm\">[מבואר בכתבי האר\"י זלה\"ה שאין תפלה של יום זה דומה לתפלת יום אחר עד ביאת המשיח, וזהו כוונת המשנה ברכות העושה תפלתו קבע אין תפלתו תחנונים יעו\"ש. ושמעתי בשם </span><i>מורי</i><span data-k=\"sm\"> מופת על זה מן]</span> מ\"ז שבאין לאדם באמצע תפלתו &lt;הם&gt; מסוד השבירה ורפ\"ח ניצוצין שצריך האדם לברר בכל יום, והם <span data-k=\"sm\">[באין]</span> שיתקן אותם ולהעלותם. ואין מ\"ז של יום זה דומה למחשבה &lt;זרה&gt; של מחר, והוא בחון למי שנותן לב על זה. &lt;ופי' הבעש\"ט&gt; <span data-k=\"sm\">[וכאשר שמעתי </span><i>ממורי</i><span data-k=\"sm\">]</span> איך יתקן מ\"ז, אם הוא הרהורי נשים, יכוין להעלותן <span data-k=\"sm\">[ולדבקן]</span> בשרשן שהוא חסד, בסוד ואיש אשר יקח את אחותו חסד הוא, ומחשבת ע\"ז פגם בתפארת ישראל, ודי בזה.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י ויקהל סז</b>,<b> ד (רנא</b>,<b> א)</b>\n<i>בכתבי האר\"י זלה\"ה</i> – פע\"ח שער התפלה פ\"ז. שער הכונות, סדר שבת, בתחילתו. <i>המשנה ברכות</i> – דף כח ע\"ב. <i>ואיש אשר יקח גו'</i> – קדשים כ, יז.\n----- הערות וציונים -----\nראה לקמן סי' רנג. וראה לעיל סי' לט ובהערות שם.\n<i>בסוד ואיש כו'</i> – מבואר בשם הבעש\"ט במאור עינים פ' מקץ, ד\"ה הבעש\"ט, ושם פ' שמיני, ופ' פנחס ד\"ה וזה ואיש אשר."]]],[300010140,"קיג-א\n\n<b>&lt;מהבעש\"ט&gt;</b> <span data-k=\"sm\">[שמעתי </span><i>ממורי</i><span data-k=\"sm\">]</span> כשרוצין ליפרע העונש למי שהוא ראוי לעונש, אזי נוטלין ממנו מדריגת הבטחון, ע\"כ ראוי להתפלל לפניו ית' שיתחזק בבטחון בו ית' <span data-k=\"sm\">[ודפח\"ח]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י משפטים נו</b>,<b> ב (רח</b>,<b> ב)</b>\n----- הערות וציונים -----\nנשנה לקמן סי' שפב עם ההמשך אשר בתוי\"י."]]],[300010141,"קיג-ב\n\n[<b>דשמעתי</b> <span data-k=\"sm\">בשם הרה\"מ מו' מנחם מענדל מה שנזכר בזהר]</span> זכאה מאן דאחיד בידא דחייבא <span data-k=\"sm\">[וכו']</span>, דאין הכוונה לומר להם דברי מוסר כדי שישובו <span data-k=\"sm\">[וכיו\"ב]</span>, דא\"כ שמא לא ישמעו לו ולא עלתה בידו כלום. ועוד, דזה כלל גדול בכל פעולותיך שתעשה לש\"ש תראה שתהיה מיד בעשותך הדבר יהיה בו עבודת השם, הן באכילתו, שלא יאמר שיהי' כוונת אכילתו לש\"ש שיהיה לו כח אח\"כ לעבודת הש\"י, הגם שזה ג\"כ כוונה טובה, מ\"מ עיקר השלימות שיהיה בו עובדא לש\"ש מיד, והיינו להעלות ניצוצין &lt;קדישין&gt; . . . וה\"ה לכל מעשי האדם יהיו עד\"ז <span data-k=\"sm\">[ישמע חכם ויוסף לקח]</span>.\n<b>וא\"כ</b> באומר <span data-k=\"sm\">[דברי]</span> מוסר ותוכחה לבני עירו יראה לקשר א\"ע תחלה בו ית', ואחר כך יראה לדבק ולקשר א\"ע עמהם מצד האחדות והתכללות, כי שורש אחד להם לראשי הדור עם בני דורו. וכשעושה כך אז ה' אלקיו עמו ויעל עמהם לדבק אותם בו ית'. וז\"ש דאוחז בידם להעלותם, וא\"כ עושה פעולה מיד באמירתו להם תוכחה ומוסר לעם בני ישראל <span data-k=\"sm\">[ודפח\"ח]</span>.\n<b>&lt;וכמ\"ש</b> הבעש\"ט&gt; <span data-k=\"sm\">[וכן שמעתי זה הדרך </span><i>ממורי</i><span data-k=\"sm\">]</span> בענין התפלה להעלותם ג\"כ &lt;עד\"ז&gt;.\n[<b>. . . ונראה</b> <span data-k=\"sm\">לי]</span> שזה <span data-k=\"sm\">[פירוש]</span> ראיתי בני עליה והם מועטים, <span data-k=\"sm\">[ר\"ל שיהיה יכולת בידם להעלות א\"ע עם בני דורו ולדבקם ע\"י תפלה או מוסר בו ית' הם מועטים]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י משפטים נט</b>,<b> ב (ריט</b>,<b> ב)</b>\n<i>זכאה מאן כו'</i> – זח\"ב קכח, ב. <i>ישמע חכם גו'</i> – משלי א, ה. <i>ה' אלקיו עמו ויעל</i> – ע\"פ דה\"ב לו, כג. <i>ראיתי בני עלי' כו'</i> – סוכה מה, ב.\n----- הערות וציונים -----\n<i>דשמעתי בשם כו'</i> – והובאו דבריו באופן תמציתי לקמן סי' רנא-ב. ובצ\"פ ר\"פ ויקהל קיז, ד (תטו, א): ושמעתי מהרה\"מ מוהר\"ם כי המוכיח בשער בת רבים בדברי תוכחת מוסר אינו רק בדברים לבד, שאם לא ישמע לו לא פעל מאומה, רק שיעשה מעשה לחבר א\"ע עמו ולהעלותו, וזהו זכאה מאן דאחיד בידא דחייבא וכו' ודפח\"ח.\n<i>דזה כלל גדול כו'</i> – ראה לקמן סי' רכ-א, רפב-א<i>-ב</i> ושיא. צוה\"ר סי' יא וקכז.\n<i>הן באכילתו כו' להעלות כו'</i> – ראה לקמן סי' קצד.\n<i>לקשר עצמו תחלה בו ית'</i> – ראה לקמן סי' קלא, רנא, רסב וש.\n<i>לדבק ולקשר א\"ע עמהם כו'</i> – ראה לקמן סי' קלא, רנא ושפט.\n<i>מצד האחדות והתכללות כי כו'</i> – ראה לעיל סי' נד ופט, לקמן סי' קכה ושע. ועיין לקו\"ת להאריז\"ל פ' קדשים, מצות ואהבת לרעך כמוך. לקו\"ת לאדה\"ז ר\"פ נצבים.\n<i>וכן שמעתי זה הדרך ממורי כו'</i> – ראה לקמן סי' שעג. רג\"כ לעיל סי' ח וצג, ולקמן סי' שנח."]]],[300010142,"קיד\n\n[<b>שמעתי</b> <span data-k=\"sm\">בשם </span><i>מורי</i><span data-k=\"sm\">]</span> ביאור משנה קדשי קדשים שחיטתן בצפון וקדשים קלים בכל מקום, שהיצר הרע בא אל התלמידי חכמים בדמות יצר הטוב לעשות מצוה, משא\"כ להמוני עם <span data-k=\"sm\">[ודפח\"ח]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י כי תשא סו</b>,<b> סע</b>\"<b>ג (רמו</b>,<b> ב)</b>\n<i>קדשי קדשים כו'</i> – זבחים מז, א. <i>וקדשים קלים כו'</i> – זבחים נה, א.\n----- הערות וציונים -----\n<i>שהיצה\"ר בא אל הת\"ח כו'</i> – להעיר מסוכה נה, א ואת הצפוני גו' זה יצה\"ר כו' ובת\"ח יותר מכולם (ראה נצח ישראל למהר\"ל פ\"ב), וראה זח\"ג קי, רע\"א.\n<i>בדמות יצה\"ט כו'</i> – ראה לעיל סי' עח-א ועח-ב. צוה\"ר סי' קיז וקכד."]]],[300010143,"קטו\n\n<b>&lt;מהבעש\"ט&gt;</b> משל למלך א' שמושל בכיפה, ושלח א' מעבדיו שינסה המדינות כאלו הוא עבד מורד באדונו. וקצת מדינות עשו מלחמה עמו ושלטו עליו, וקצת מדינות השלימו <span data-k=\"sm\">[עמו]</span>, ובמדינה אחת היו חכמים והרגישו שזהו רצון המלך עושה <span data-k=\"sm\">[וכו' יעו\"ש]</span>.\n<b>והנמשל</b> מובן, שיש בני אדם שעושין מלחמה עם היצה\"ר, שעושה עצמו כאילו הוא עבד מורד באדונו, שמפתה בני אדם שלא יעשו רצון הבורא &lt;ית' שהוא&gt; מלך העולם, ועומדין כנגדו עד ששלטו ביצרם ע\"י גודל המלחמה וסיגופים גדולים. ויש בני אדם שהרגישו שהוא עושה רצון הבורא ושם מלובש שמו הקדוש מן ע\"ב שמות הקדושים, שהוא סא\"ל שהוא ממתיק לסמאל. וזהו שכוונת שם הקדוש כוז\"ו שבכל מקום יש כ\"ו &lt;גימטריא&gt; שם הוי\"ה בזו ובזו, <span data-k=\"sm\">[וכמו ששמעתי זה </span><i>ממורי</i><span data-k=\"sm\">]</span> והבן.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י ויקהל סח</b>,<b> סע</b>\"<b>א (רנב</b>,<b> א)</b>\n<i>שמו הקדוש מן ע\"ב כו'</i> – זח\"ב ער, א.\n----- הערות וציונים -----\nכמה עמודים לפני דרוש זה [סז, סע\"ג (רנ, א)] הובא משל זה בשנויים קלים, והנמשל באו\"א אשר כדאי להעתיק בבחי' דברי תורה פותחים זל\"ז: והנמשל מובן, שזהו שזכר הזוהר (זח\"ב קסג, א) ענין היצה\"ר נמשל לזונה שצוהו המלך לפתה את בנו וכו' יעו\"ש, הגם שיש בזה ענין פנימי כמו ששמעתי ממורי ענין ודוי אשמנו (לקמן סי' רנב) שהמלך בעצמו כסות ולשון שינה ובא לכבוש המלכה וכו' ודי בזה למבין, והוא דבר גדול כאשר קבלתי ממורי (ראה לעיל סי' צח) שבכל צער האדם בגשמי וברוחני שאם נותן לב שגם בזה הצער הוא השי\"ת בעצמו אלא שהוא דרך לבוש, וכאשר נודע לו זה הוסר הלבוש ונתבטל הצער וכל גזירות רעות, והאריך בזה ודפח\"ח. וכאשר שמעתי ממנו ג\"כ ענין ה' אלפין (ראה לעיל סי' פה) אמר אויב ארדוף אשיג אחלק שאלופו של עולם הוא כאן בהסתר ודפח\"ח, אם כן זהו עיקר השבח והשירה שהיו סוברים בגלות מצרים שהוא אויב ועכשיו שהרגישו שהוא עצם ית' נעשה מן אויב אוהב, וזהו עצמות הגאולה, והוא בכל אדם ובכל זמן, והוא סוד גלות מצרים שיש בכל אדם ובכל זמן וכו'.\n<i>שמו הקדוש כו' סא\"ל</i> – ראה לעיל סי' פה ובהערות שם.\n<i>סא\"ל שהוא ממתיק לסמא\"ל</i> – ראה לקמן סי' קכח שמוציא ממנו הרע שהוא אות מ' ונשאר כו' והוא שמו ית' כו'.\n<i>שם הקדוש כוז\"ו</i> – ואיהו שמא דברכאן וקדושין כוז\"ו רזא דשמא קדישא כו' ואלין אתוון אפיקו מניה הני אתוון אחרנין כו' (זח\"ב רסא, ב. ורג\"כ זח\"א כג, א). שם זה מבואר בארוכה במדל\"י סי' קסה (קצב) עיי\"ש. וראה לעיל בהערות לסי' ק-א.\n<i>כוז\"ו שבכל מקום יש כ\"ו כו'</i> – ראה בס' אורח לחיים פ' וירא ד\"ה ויאמר ה', שמביא שם פירוש הרה\"מ: שם כוז\"ו שהוא אותיות שניות שאחרי הוי\"ה . . כ\"ו, מספר כ\"ו הוא הוי\"ה, ז\"ו, כלומר אף בכאן הוא שם הוי\"ה, כי מלא כל הארץ כבודו עכ\"ד ודפח\"ח."]]],[300010144,"קטז\n\n<b>&lt;מבעש\"ט&gt;</b> אם לא תדעי לך היפה בנשים צאי לך בעקבי הצאן, <span data-k=\"sm\">[דשמעתי בשם </span><i>מורי</i><span data-k=\"sm\"> זלה\"ה]</span> &lt;ע\"פ&gt; ביאור משנה איזהו חכם הלומד מכל אדם, ע\"פ משל המסתכל במראה יודע חסרונו כו', כך ברואה חסרון זולתו יודע שיש בו שמץ מנהו וכו' <span data-k=\"sm\">[ודפח\"ח]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י פקודי ע</b>,<b> א (רנט</b>,<b> א)</b>\n<i>אם לא תדעי גו'</i> – שה\"ש א, ח. <i>איזהו חכם כו'</i> – אבות פ\"ד מ\"א.\n----- הערות וציונים -----\nראה לעיל סי' פט, ולקמן סי' שב-א ושסג. ובהוספות סי' קעו מס' מאור עינים ר\"פ חקת, ובהערות שם. להעיר מקידושין ע, א כל הפוסל כו'."]]],[300010145,"קיז\n\n<b>&lt;מבעש\"ט</b> ז\"ל&gt; <span data-k=\"sm\">[ששמעתי]</span> משל <span data-k=\"sm\">[בשם </span><i>מורי</i><span data-k=\"sm\">]</span> למלך שהיה ממנה על אוצרו ד' שרים, ונטלו האוצר וברחו. א' נתיישב בדעתו וחזר מעצמו, ב' נתיעץ עם חכם א' ודיבר על לבו מה ראה על ככה וחזר, הג' הגיע למקום שדנין בני אדם על כיוצא בזה וחזר מחמת מורא, ד' לא שב כלל. והמלך, לזה שחזר מעצמו נתן יותר גדולה מאחר שנתיישב בטוב שכלו לחזור, משא\"כ להשני אמר אלו לא מצא חכם שיעצו כך לא היה חוזר. והשלישי שחזר מחמת שראה שדנין לבני אדם מנהו המלך להיות ממונה שם לראות זה הצער. ואמר <span data-k=\"sm\">[</span><i>מורי</i><span data-k=\"sm\">]</span> &lt;הבעש\"ט&gt; זה על עצמו <span data-k=\"sm\">[וכו']</span>, והבן.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י צו עה</b>,<b> ב (רפא</b>,<b> א)</b>\n----- הערות וציונים -----\nעיין לקמן סי' רנה שם הובא במילואו ויבואר."]]],[300010146,"קיח\n\n<b>&lt;מבעש\"ט&gt;</b> <span data-k=\"sm\">[יש ז' דרכים שביארתי בז' קני מנורה ע\"פ ששמעתי </span><i>ממורי</i><span data-k=\"sm\">]</span> שש שנים תזרע שדך כו', א' שאינו הולך בדרך טובה ואינו מרגיש בו, זהו בנוקבא דתהומא רבא, ב' שיודע בעצמו שאינו נוהג בדרך טובה ומ\"מ הולך בדרך ההוא ואינו מתפלל על עצמו, ג' שיודע שאינו הולך בדרך טובה ומתפלל להשם שיעזור לו זה עושה יחוד כו'.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י צו עה</b>,<b> רע</b>\"<b>ג (רפב</b>,<b> א)</b>\n<i>שש שנים גו'</i> – בהר כה, ג. <i>בנוקבא דת\"ר</i> – זח\"ג קטו, רע\"א. שם קכב, א.\n----- הערות וציונים -----\nראה לקמן סי' תכא. ורג\"כ סי' קפד.\n<i>שביארתי בז' קני המנורה</i> – ראה תוי\"י פ' חקת שם הביא תורת הבעש\"ט המובאה לקמן סי' תכא וסיים: ובזה כתבתי ענין ז' קני מנורה יעו\"ש. וצ\"ע בנוגע לד' סוגים הנשארים. ולהעיר מתוי\"י פ' קדשים צא, ד (שמב, א) בביאור ג' ספרים נפתחין בר\"ה (ר\"ה טז, ב) שהקשה הרי\"ף דהא משמע דיש יותר מג' ספרים כו' ותירץ דאעפ\"י שיש יותר מג' מ\"מ כולם כלולים בג' כו' ז' מדות בפרטי פרטן שהם ז' ימי הבנין אלא שהכל נכללו בג' קוין כו' עיי\"ש."]]],[300010147,"קיט\n\n<b>&lt;מהבעש\"ט&gt;</b> <span data-k=\"sm\">[שמעתי </span><i>ממורי</i><span data-k=\"sm\">]</span> ענין הנס הוא שנתחדש הדבר בפעם הראשון על הטבע נק' נס, ואח\"כ נעשה זה טבע ג\"כ <span data-k=\"sm\">[וכו']</span>.\n<b>&lt;וז\"ש&gt;</b> <span data-k=\"sm\">[. . . ובדרך זה שמעתי בשם </span><i>מורי</i><span data-k=\"sm\"> פירוש הפסוק]</span> תקעו בחודש שופר <span data-k=\"sm\">[וגו']</span>, והקשה דהוי ליה למימר תקעו שופר בחודש, &lt;ופירש&gt; <span data-k=\"sm\">[והעולה מדבריו]</span> כי יראה &lt;אדם תדיר&gt; שיהיה בחודש, ר\"ל לחדש &lt;מעש\"ט&gt; שלא יהיה כמו חק קבוע. וז\"ש כי חק לישראל הוא &lt;משפט לאלקי יעקב, עמו על זה&gt; <span data-k=\"sm\">[וכו' ודפח\"ח]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י צו עז</b>,<b> שלהי ע</b>\"<b>ב ושם רע</b>\"<b>ג (רפט</b>,<b> ב)</b>\n<i>תקעו בחדש גו' כי חק גו'</i> – תהלים פא, ד-ה.\n----- הערות וציונים -----\nהדרוש במילואו לקמן סי' רנו עיי\"ש."]]],[300010148,"קכ\n\n<b>&lt;מבעש\"ט&gt;</b> <span data-k=\"sm\">[ששמעתי </span><i>ממורי</i><span data-k=\"sm\"> ז\"ל]</span> כי יש שצריך להתחזק תחלה קודם התפלה כדי שיהי' לו מוחין להתפלל בלי מחשבה זרה עכ\"פ, או בדביקות, והוא ע\"י מזמורים או תורה שיתעסק תחלה, ומתוך כך הוא עומד להתפלל מתוך דברי תורה שיש לו מוחין. ויש שאם ירבה מזמורים או תורה קודם התפלה לא יהי' לו מוחין בתפלה. וז\"ש אחד המרבה ואחד הממעיט ובלבד שיכוין לבו לשמים, שיהי' לו מוחין בתפלה, לכך הם שוין <span data-k=\"sm\">[וסרה קושית הט\"ז, ודפח\"ח]</span>.\n<b>ואז</b> שאדם עצמו עושה תחבולות להתעורר בתפלה נקרא זכר, מיין דוכרין, משא\"כ שיש לפעמים שמעוררין אותו מלמעלה <span data-k=\"sm\">[שמעצמו נתעורר]</span> בבכיה <span data-k=\"sm\">[וכיוצא]</span> זהו נקרא אשה, מיין נוקבין, ואז ח\"ו ותפלתו תהי' לחטאה, &lt;שיש עליו דינים הרבה ומזלי' חזי&gt;. והתקנה לזה, שיתחרט האדם בזכרו שלא התעורר מעצמו רק שהוצרכו לעוררו תחלה מלמעלה, ויבכה על הבכיה הראשונה שבאה מעצמה, ואז נתהפך מיין נוקבין למיין דוכרין ונעשה זכר <span data-k=\"sm\">[ודפח\"ח]</span>. . .\n<b>ויותר</b> מזה שיש להרחיב בזה להבינך לא ניתן לכתוב, והשי\"ת יכפר.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י תזריע פג</b>,<b> א (שיא</b>,<b> ב)</b>\n<i>אחד המרבה כו'</i> – מנחות קי, א. <i>קושיית הט\"ז</i> – או\"ח סי' א אות ג. <i>ותפלתו גו'</i> – תהלים קט, ז. <i>ומזלי' חזי</i> – מגילה ג, א.\n----- הערות וציונים -----\n<i>יש שצריך כו' שיהיו לו מוחין כו'</i> – ראה לקמן סי' שצט.\n<i>ויש שאם ירבה כו' לא יהיו לו כו'</i> – ראה צוה\"ר סי' לח.\n<i>שאדם עצמו עושה תחבולות כו'</i> – ראה לקמן סי' קנט, רנט ושצט. ועיין לקו\"י סי' מב.\n<i>לפעמים שמעוררין אותו מלמעלה כו' שיש עליו דינים כו'</i> – להעיר מפע\"ח שער השופר פ\"ה מי שבוכה אז מעצמו כו' עיי\"ש."]]],[300010149,"קכא\n\n<b>&lt;מהבעש\"ט</b> ז\"ל&gt; <span data-k=\"sm\">[</span><i>וממורי</i><span data-k=\"sm\"> שמעתי]</span> ענין החיות רצוא ושוב, כי הנשמה אחר שחוצבה ממקום קדוש ראוי שתתלהב תמיד אל מקום מחצבתה, ופן תתבטל ממציאות, לכך סיבבה בחומר שתעשה ג\"כ ענינים חומריים, כמו אכילה ושתיה ומשא ומתן וכיוצא, שלא &lt;תתהלך&gt; <span data-k=\"sm\">[תתלהב]</span> תמיד בעבודת הש\"י בסוד תיקון וקיום <span data-k=\"sm\">[הגוף]</span> עם הנשמה. וכן הוא במדריגות הספירות קטנות וגדלות <span data-k=\"sm\">[ודפח\"ח]</span>.\n<b>עוד</b> י\"ל והחיות רצוא ושוב, כי תענוג תמידי נעשה טבע ואינו תענוג, לכך האדם עולה ויורד בעבודת הש\"י כדי שיהיה &lt;לו&gt; תענוג שהוא עיקר עבודת הש\"י, <span data-k=\"sm\">[וכמו ששמעתי </span><i>ממורי</i><span data-k=\"sm\">]</span>.\n<b>וז\"ש</b> זאת תורת העולה, כי המיעוט שאין עולה לו עבודה תמה ומצטער &lt;על זה&gt;, הוא התכלית של עליה שיהיה לו אז יותר תענוג.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י תזריע פג</b>,<b> רע</b>\"<b>ג (שיב</b>,<b> א)</b>\n<i>החיות רצו\"ש</i> – יחזקאל א, יד. <i>שחוצבה ממקום קדוש</i> – זח\"א מדה\"נ קיג, א. <i>זאת תורת העולה</i> – צו ו, ב. <i>עבודה תמה</i> – יומא כה, א.\n----- הערות וציונים -----\nראה לעיל סי' לד וקי-ב, ולקמן סי' קעח.\n<i>תענוג תמידי כו'</i> – ראה צוה\"ר סי' קיא, ומדל\"י סי' קסח (קעה): ונודע מהבעש\"ט ז\"ל שתענוג תמידי אינו תענוג. ושם סי' נ (סב) וקו (קיז), ורג\"כ שם סי' רנו (רסד). ועיין אור האמת כז, ריש ע\"ב: תענוג תמידי אינו תענוג כדרך שאמר בגמרא (נדה לא, ב) מפני מה אמרה תורה כו'. ולהעיר ממו\"נ ח\"ג פכ\"ד (היציאה מן הטורח אל המנוחה יותר ערבה מההתמדה על המנוחה), ועוד שם פכ\"ד ופמ\"ט."]]],[300010150,"קכב\n\n<b>&lt;מבעש\"ט</b> ז\"ל&gt; <span data-k=\"sm\">[שמעתי </span><i>ממורי</i><span data-k=\"sm\">]</span> פירוש הפסוק נושא עון ועובר על פשע, ור\"ל שהוא על דרך משל שהיה ריב בין ב' בני אדם, וכשרוצין להתפייס זה עם זה אז מתווכחין לידע מי חטא נגד מי, משא\"כ כשאין רוצין להתפייס אינו נושא עונו להוכיחו על פניו מה שחטא לו. וז\"ש נושא עון, ר\"ל שנושא עונו ומוכיחו על פניו, היינו כשרוצה לעבור על פשע <span data-k=\"sm\">[ודפח\"ח]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י תזריע פד</b>,<b> א (שיד</b>,<b> ב)</b>\n<i>נושא עון גו'</i> – מיכה ז, יח.\n----- הערות וציונים -----"]]],[300010151,"קכג\n\n<b>והבגד</b> כי יהי' בו נגע <span data-k=\"sm\">[וגו' וראה הכהן וגו']</span>. &lt;כ' הבעש\"ט&gt; <span data-k=\"sm\">[כי שמעתי </span><i>ממורי</i><span data-k=\"sm\">]</span> ענין קטנות וגדלות שיש בספירות העליונות למעלה, כך הענין למטה בכל דבר, הן בבגדים כו'. וזהו שלפעמים עושה מלאכת הבגד מקולקלין, להצר לאדם, והוא בסוד קטנות כו'. והתקנה שיעשה פדיון, או שיתן הבגד הישן לעניים או שיתן לפי ערך שומת הבגד לצדקה <span data-k=\"sm\">[ודפח\"ח]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י תזריע פד</b>,<b> סע</b>\"<b>ב (שטז</b>,<b> א)</b>\n<i>והבגד גו'</i> – תזריע יג, מז. <i>וראה הכהן גו'</i> – תזריע יג, נ.\n----- הערות וציונים -----\n<i>ענין קטנות וגדלות</i> – ראה לעיל סי' קי-ב וש\"נ בהערות."]]],[300010152,"קכד\n\n<b>&lt;מבעש\"ט&gt;</b> <span data-k=\"sm\">[שמעתי בשם </span><i>מורי</i><span data-k=\"sm\">]</span> טעם הגון כי כשחטא בשוגג בלא דעת אז יש תקנה בעושה תשובה בכוונה שנותן בו דעת להעלותו. משא\"כ כשחוטא בדעת במה יתקנה. וזה פי' הש\"ס האומר אחטא ואשוב כו' והבן <span data-k=\"sm\">[ודפח\"ח]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י אחרי פח</b>,<b> סע</b>\"<b>ב (שכט</b>,<b> ב)</b>\n<i>האומר אחטא כו'</i> – יומא פה, ב.\n----- הערות וציונים -----\nראה לקמן סי' קנב-א. ורג\"כ לעיל סי' כה ולקמן סי' קלט ורעא. להעיר מרמב\"ם הל' תשובה פ\"ו ה\"ב וכשם שהאדם חוטא ברצונו ומדעתו כך הוא עושה תשובה ברצונו ומדעתו. ועיין הל' מקואות פי\"א הי\"ב. ובדרך מצותיך לאדמו\"ר הצ\"צ, מצות וידוי ותשובה פ\"א.\n<i>האומר אחטא ואשוב כו'</i> – עיין תניא פכ\"ה, ושם באגה\"ת פי\"א."]]],[300010153,"קכה\n\n<b>&lt;מבעש\"ט&gt;</b> <span data-k=\"sm\">[ששמעתי </span><i>ממורי</i><span data-k=\"sm\">]</span> כל שרוח הבריות נוחה הימנו רוח המקום נוחה הימנו, כי האדם נקרא עולם קטן, &lt;וכן ישראל בכללם&gt; זה ראש וזה &lt;עין&gt; <span data-k=\"sm\">[רגל]</span>, וזה שנקראו ראשי הדור עיני העדה, וכשעושה עצמו מרכבה להשראת שכינה ראשי הדור, וממנו מתפשט לשאר בני דורו.\n<b>וז\"ש</b> שרוח הבריות נוח\"ה, לשון השראה ונייחא, הוא הימנו, כי רוח המקום נוחה לכל העולם ממנו, ולכך &lt;הוא&gt; מה שרוח הבריות נוחה הימנו.\n<b>וההיפך</b> כשאין השראת שכינה לא יתלה הסרחון בדור רק בעצמו. וז\"ש כל שאין רוח המקום נוחה עליו, הוא הימנו, ר\"ל שהוא עצמו גרם זאת הסבה, לא הדור <span data-k=\"sm\">[וכו', ואם אין זה לשונו ממש, מ\"מ כך משמעות דבריו, ודפח\"ח]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י אחרי פח</b>,<b> ג (של</b>,<b> א)</b>\n<i>כל שרוח כו'</i> – אבות פ\"ג מ\"י. <i>האדם נקרא עולם קטן</i> – תנחומא פקודי ג. <i>ראשי הדור עיני העדה</i> – ספרי עקב פ' מא. שהש\"ר א, טו. וש\"נ. זח\"ב ריח, רע\"א. <i>כל שאין כו'</i> – אבות פ\"ג מ\"י.\n----- הערות וציונים -----\n<i>וכן ישראל בכללם כו'</i> – ראה לעיל סי' קיג-ב ובהערות שם.\n<i>וכשעושה עצמו מרכבה כו'</i> – ראה לקמן סי' רפה-א.\n<i>וממנו מתפשט כו'</i> – ראה לעיל סי' קיג-א. להעיר מלעיל סי' ה ולקמן סי' ער.\n<i>נוחה לשון השראה</i> – ע\"פ בהעלתך יא, כה-כו וישעי' יא, ב.\n<i>הוא הימנו כו'</i> – ראה לעיל סי' ו ובהערות שם."]]],[300010154,"קכו\n\n<b>על</b> זאת יתפלל כל חסיד <span data-k=\"sm\">[לעת מצא]</span>, ר\"ל כל <span data-k=\"sm\">[הצטרכות שלו אשר מצא אותו מן כל]</span> הרפתקאות דעדו עליו יתן לב להבין שהוא בשכינה, &lt;ולו&gt; נזדמן זה &lt;רק&gt; כדי שיתפלל עבור השכינה הנקראת זאת, <span data-k=\"sm\">[כמו ששמעתי </span><i>ממורי</i><span data-k=\"sm\"> ג\"כ]</span> ש<span data-k=\"sm\">[היא]</span> נקראת את, כלולה מן כ\"ב אתוון, ויכוין לחבר עמה ז' ספירות שלה שנקראת בת שבע, הרי זאת. גם יכוין לחבר מדריגה תחתונה שבמלכות, הוא אות ת', עם ז' מדריגות שלה אל אות אל\"פ שהוא פלא, והבן.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י ס</b>\"<b>פ אחרי פח</b>,<b> ד (של</b>,<b> ב)</b>\n<i>על זאת גו'</i> – תהלים לב, ו. <i>הרפתקאות דעדו עליו</i> – ע\"פ קידושין לג, סע\"א. <i>שהוא בשכינה</i> – סנהדרין מו, א. <i>השכינה הנקראת זאת</i> – זח\"ג רצז, סע\"ב. <i>שהיא נקראת את כלולה כו'</i> – תקו\"ז תי\"ט מא, רע\"א. <i>שנקראת בת שבע</i> – זח\"ג לז, א. <i>אות אל\"ף שהוא פלא</i> – זח\"ג קצג, ב. תקו\"ז ת\"ע קלה, א.\n----- הערות וציונים -----\n<i>יתן לב שהוא בשכינה כו'</i> – ראה מכדרשב\"י ר\"פ שמות. מכדר\"י פ' בא פי\"ד. וראה הנסמן לעיל בהערות לסי' כ.\n<i>הנקראת זאת</i> – ראה תקוזו\"ח קיא, א.\n<i>את כלולה מן כ\"ב אתוון</i> – דהוה נוטריקון א-ת, ראה זח\"א טו, ב ושם כט, ב. זח\"ב רסא, א. אליהו רבה פי\"ח.\n<i>לחבר עמה ז' ספירות כו' הרי זאת</i> – ראה זח\"ג ר\"פ חקת קעט, ב ובאוה\"ח שם."]]],[300010155,"קכז-א\n\n<b>&lt;מהבעש\"ט&gt;</b> <span data-k=\"sm\">[ששמעתי </span><i>ממורי</i><span data-k=\"sm\">]</span> בשם הרמב\"ן &lt;ז\"ל&gt; שאמר לבנו שידע בעצמו שאם בעסקו בתורה עוסק בה לשמה, כשיתמלא יראה ואהבה בעוסקו בתורה ידע שתורתו עולה לרצון לפניו ית' <span data-k=\"sm\">[וכו']</span>. . .",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י ס</b>\"<b>פ אחרי פח</b>,<b> ד (שלא</b>,<b> א)</b>\n----- הערות וציונים -----\n<i>כשיתמלא יראה ואהבה כו'</i> – להעיר מלעיל סי' לו ועיי\"ש בהערות. ובתוי\"י שלהי פ' משפטים סב, ד (רלב, ב) ששמעתי ממורי זלה\"ה בשם הרמב\"ן ששאלו א' איזה עבודת ה' והשיבו כל שיש בו תענוג ושמחה בצירוף המורא וכו'."]]],[300010156,"קכז-ב\n\n[<b>ששמעתי</b> <i>ממורי</i><span data-k=\"sm\">]</span> טעם הלומד לשמה זוכה לדברים הרבה, ומה ענינו של לימוד לשמה. וביאר &lt;מורי&gt;, כי כל מעשה בראשית, הן דבר קטן או גדול, נברא ע\"י אותיות ברל\"א שערים כנודע, וע\"י פגם עונות האדם מוריד נשמות קדושות, שהם אותיות הקודש, ממקום חיותם אל מקום הקליפות ח\"ו, הן בדומם או חי בלתי מדבר וכיוצא. ובתיקון האדם מעשיו ולומד לשמה, היינו לשמה של האות ההוא שהורידה למטה, שעתה ע\"י שלומד בדחילו ורחימו ומכוין להעלות האות שהיא נשמה ממקום הקליפות ולהעלותה לדבקה בשרשה.\n<b>והנה</b> ממקום הקליפות עד למעלה למעלה שהוא שורש האותיות יש כמה וכמה מדריגות לאלפים ולרבבות, וע\"כ מעלה כל המדריגות ששורש בריאתן מן האות הזה עד למעלה בשרשן. א\"כ שפיר אמר התנא <span data-k=\"sm\">[הלומד לשמה]</span> זוכה לדברים הרבה, כי <span data-k=\"sm\">[הרבה]</span> דברים נעשה מזה האות, ואת כולם מעלה לשרשו, ע\"כ נקרא אהוב <span data-k=\"sm\">[וכו' ודפח\"ח. וז\"ש ויפק רצון מה', שנקרא אהוב]</span> אוהב את המקום, וכי יש לך אוהב גדול מזה שמעלה בן המלך שהיה כמה שנים בשביה למלך.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י ס</b>\"<b>פ אחרי פח</b>,<b> ד (שלא</b>,<b> א)</b>\n<i>הלומד לשמה כו'</i> – אבות פ\"ו מ\"א. <i>אותיות ברל\"א שערים</i> – ס\"י פ\"ב ד-ה. זח\"א רד, א (ונצוצי אורות שם). <i>נקרא אהוב</i> – אבות פ\"ו מ\"א. <i>ויפק רצון מה'</i> – משלי יח, כב.\n----- הערות וציונים -----\n<i>כל מעשה בראשית כו' ע\"י אותיות</i> – להעיר מברכות נה, א. וראה פרש\"י איוב כח, כג.\n<i>ע\"י אותיות ברל\"א שערים</i> – ראה תניא, שהיוה\"א פ\"א.\n<i>ובתיקון כו' ולומד לשמה כו' להעלות כו'</i> – ראה זח\"ב רמה, ב ובפי' הרמ\"ז שם. עיין תניא ספל\"ט ופ\"מ, ושם קו\"א סי' ג.\n<i>לשמה היינו לשמה של האות</i> – ראה לקמן סי' קמב ותכו.\n<i>זוכה לדברים הרבה</i> – ראה לעיל סי' צו ולקמן סי' רד.\n<i>הרבה דברים נעשו מזה האות</i> – להעיר מלעיל סי' כב וראה בהערות שם.\n<i>שמעלה כו' שהיה כמה שנים בשביה</i> – להעיר מברכות ח, א כל העוסק בתורה כו' אמר הקב\"ה מעלה אני עליו כאלו פדאני ואת בני מבין או\"ה (הובא בתניא, אגה\"ק שלהי סי' כו עיי\"ש)."]]],[300010157,"קכח\n\n[<b>שמעתי</b> <i>ממורי</i><span data-k=\"sm\"> זלה\"ה]</span> ענין שחיטת יצה\"ר לעתיד לבוא, שמוציא ממנו הרע שהוא אות מ', ונשאר כו' והוא &lt;שם קדוש&gt; <span data-k=\"sm\">[שמו ית' וכו' ודפח\"ח]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י קדשים פט</b>,<b> ג (שלג</b>,<b> ב)</b>\n<i>שחיטת יצה\"ר לע\"ל</i> – סוכה נב, א.\n----- הערות וציונים -----\nראה לקמן סי' רסה, ועיין לעיל סוף סי' קטו בענין סא\"ל ומש\"כ בהערות שם. ולהעיר עוד ממש\"כ בתוי\"י פ' ויקהל סח, סע\"ב (רנג, א) בביאור ענין חד גדיא הבא בהמשך לסי' קטו: שישחוט הקב\"ה למלאך המות סמא\"ל וישאר רק סא\"ל יחוד הוי' אדנ\"י וביום ההוא יהי' ה' אחד ושמו אחד."]]],[300010158,"קכט\n\n<b>&lt;מבעש\"ט&gt;</b> <span data-k=\"sm\">[שמעתי </span><i>ממורי</i><span data-k=\"sm\">]</span> שכר מצוה מצוה, שאין לך שכר גדול <span data-k=\"sm\">[מזה]</span> ממה שיש לו תענוג ממצוה עצמה בעשותה בשמחה <span data-k=\"sm\">[שהוא גדול]</span> אף אם לא היה שכר יותר די. &lt;ובאמת&gt; <span data-k=\"sm\">[הגם שבאמת]</span> יש שכר עד אין תכלית על מצוה שעושין בשמחה.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י קדשים צ</b>,<b> ב (שלו</b>,<b> ב)</b>\n<i>שכר מצוה מצוה</i> – אבות פ\"ד מ\"ב.\n----- הערות וציונים -----\nראה תוי\"י פ' יתרו נה, א (רג, ב) והתענוג שיש לו ממצות שבת זהו שכרו שאין מבקש שום תענוג יותר מתענוג המצוה עצמו הגם שבאמת יש ויש כפלים לתושיה מ\"מ החכם בעבודת השי\"ת מצייר בדעתו אלו לא היה שכר על המצוה רק זאת התענוג של המצוה עצמו שהתענג בו. ועיין לקוטי שיחות חט\"ו, פ' וישב-ב אות ג."]]],[300010159,"קל\n\n<b>שמצות</b> היום בשופר, &lt;פי'&gt; <span data-k=\"sm\">[לפי מה שקבלתי מ]</span><i>מורי</i> מה שהזהירו חכמי הקבלה בכל מצוה ותורה ותפלה שיהי' בדחילו ורחימו, &lt;שיהיה&gt; <span data-k=\"sm\">[שהיא]</span> אהבה ויראה &lt;שוין&gt;, מכל מקום בראש השנה היפך שיהיה היראה יותר מן האהבה, משא\"כ בשבת וי\"ט יהיה אהבה יותר מיראה. <span data-k=\"sm\">[וזה שאמרו שופר של ר\"ה היו שני חצוצרות מהצדדים שופר באמצע, שהם שני בחינות כלים לעורר האהבה והיראה]</span> אך בר\"ה חצוצרות מקצרות ושופר מאריך שמצות היום בשופר &lt;המעורר יראה&gt; <span data-k=\"sm\">[ואתי שפיר]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י קדשים צב</b>,<b> ג (שדמ</b>,<b> ב)</b>\n<i>שמצות היום בשופר</i> – ר\"ה כו, ב. <i>בכל מצוה ותורה </i>. .<i> בדו\"ר</i> – זח\"א כד, א. תקו\"ז ת\"י כה, ב. שם ת\"ד קמא, א. <i>שופר של ר\"ה היו כו'</i> – ר\"ה כו, ב.\n----- הערות וציונים -----\n<i>שוין</i> – מילה זו אינה במקורו, וצע\"ק מהא דאיתא לקמן סי' רפו דצריך דחילו יותר כו' זולת בשבת.\n<i>משא\"כ בשבת ויו\"ט</i> – ראה לקמן סי' רפו זולת בשבת.\n<i>שמצות היום בשופר המעורר יראה</i> – ראה לעיל סי' פז-ב שופר שהוא חרדה כמ\"ש בעקידה בזה יעו\"ש."]]],[300010160,"קלא\n\n[<b>צריך</b> <span data-k=\"sm\">ליזהר בתוכחת מוסר שיאהב האדם אותם ומצד אהבה מוכיחם, כמו אב האוהב בנו שחרו מוסר, וכמ\"ש]</span> אשר יאהב ה' יוכיח <span data-k=\"sm\">[וכיו\"ב]</span>. אבל אלו שרוצין להתגדל ח\"ו עי\"ז &lt;או&gt; <span data-k=\"sm\">[וכיוצא בזה, כגון]</span> להנאת ממון וכדומה, שאינו לשם שמים ומעורר בקול &lt;בכי'&gt;, וכמו ששמעתי היתה לי דמעתי לחם, ושמעתי <i>ממורי</i> שח\"ו גורם עי\"ז <span data-k=\"sm\">[וכו'</span>, <span data-k=\"sm\">ח\"ו גורם]</span> מדנים בין ישראל לאביהם שבשמים.\n<b>&lt;כד\"א&gt;</b> <span data-k=\"sm\">[וכמו שזכרתי בביאור וידבר העם בה' ובמשה וגו']</span> וישלח ה' בעם את הנחשים השרפים, שהם ב' מיני מוכיחים, והוא ע\"פ משל ששמעתי <i>ממורי</i> ששלח המלך בנו יחידו מעל פניו, ושילח את ב' עבדיו, וחזר א' והלשין &lt;את&gt; הבן אל אביו <span data-k=\"sm\">[וכו']</span>, והשני אמר כדברים האלה רק שדיבר מצד שהי' צער <span data-k=\"sm\">[לו]</span> בצער המלך ובנו שנשלח מעל פניו זמן רב עד שנשכח ממנו נימוסי המלכות וכל מכבדו הזילוהו, ואז נתמלא המלך רחמים כו'. כך יש מוכיח בשער שמדבר בגנות ישראל, וח\"ו עי\"ז גורם קטרוג נחש הקדמוני כו'. וז\"ש וישלח ה' בעם את הנחשים ששורפים בארס שבפיהם, <span data-k=\"sm\">[וכו' יעו\"ש, ואם כן פיו ולבו אינן שוין, שמכוין להנאתו ואומר בפיו שעושה למען כבודו ית', וח\"ו גורם רעה כאמור, שנית שמלבין פני חבירו ולא את עצמו, שנאמר ולא תשא עלי\"ו חטא, שהוציא עצמו מהכלל]</span>, ובאמת שצריך לכלול עצמו עמהן וכמו שכתבתי הוכח לעצמך כשתוכיח את עמיתך ולא תשא עליו חטא <span data-k=\"sm\">[וכו']</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י קדשים צד</b>,<b> סע</b>\"<b>א (שנא</b>,<b> א)</b>\n<i>האוהב בנו שחרו מוסר</i> – ע\"פ משלי יג, כד. <i>אשר יאהב גו'</i> – משלי ג, יב. <i>היתה לי גו'</i> – תהלים מב, ד. <i>וידבר העם גו' וישלח ה' גו'</i> – חקת כא, ה-ו. <i>ולא תשא עליו חטא</i> – קדשים יט, יז. <i>הוכח גו'</i> – קדשים יט, יז.\n----- הערות וציונים -----\nהרישא נשנה לקמן סי' רסב-א.\n<i>ושמעתי ממורי שח\"ו גורם כו'</i> – ראה לעיל סי' צג-ב.\n<i>שצריך לכלול עצמו עמהן</i> – ראה לעיל סי' קיג-ב ולקמן סי' שפט. רג\"כ סי' שנח."]]],[300010161,"קלב\n\n[<b>דשמעתי</b> <i>ממורי</i><span data-k=\"sm\"> פירוש הפסוק]</span> כל מכה אשר לא כתובה בתורה, זו מיתת ת\"ח <span data-k=\"sm\">[(כך נוסחה במ\"ד)]</span>, וביאר &lt;הבעש\"ט&gt; ע\"פ משל שהיה למלך שרים ועבדים, ופעם א' חטאו למלך אחד מהשרים וא' מעבדיו, וציוה להכות להשר דרך כבוד &lt;כגון להלביש הרצועה בבגד משי&gt;, ולעבד שלא בכבוד. לימים שמע המלך שזה השר מתגאה בזה שנלקה דרך כבוד ואמר להעבד שאני חשוב ממך, אז ציוה המלך להלקותו כמו לעבד. ובזה יובן, דנודע כי ע\"י הכאתו בשפתיו במוסר ותוכחה נק' מיתה אל המדה רעה של הת\"ח שמצוי בהם הגאוה.\n<b>וז\"ש</b> מכה אשר לא כתובה בתורה, שיהיה הכאה בלא פסוקי התורה רק יאמר לו מפורש, דאם לא כן אלא יאמר לו דרך כבוד להלביש המוסר בפסוקי התורה והלכותיו א\"כ יהיה זה סיבה להתגאות יותר. לכך מכה אשר לא כתובה בתורה זו מיתת ת\"ח, שיורד ממדריגתו שהיה לו נק' מיתה, וזה ע\"י מכה אשר לא כתובה בתורה <span data-k=\"sm\">[ודפח\"ח]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י קדשים צה</b>,<b> סע</b>\"<b>ב (שנז</b>,<b> ב)</b>\n<i>כל מכה גו'</i> – תבוא כח, סא. <i>זו מיתת ת\"ח</i> – ראה איכ\"ר א, לז. <i>שיורד ממדריגתו </i>. .<i> מיתה</i> – זח\"ג קלה, ריש ע\"ב.\n----- הערות וציונים -----\n<i>שמצוי בהם הגאוה</i> – ראה לקמן סוף סי' רמט.\n<i>בלא פסוקי תורה</i> – להעיר מכריתות יא, רע\"א.\n<i>דאל\"כ כו' להתגאות יותר וכו'</i> – ראה בפ\"י, שלהי דרוש לש\"ת תקכ\"ג קיז, סע\"א, וראה שם ריש ע\"ב והוא ע\"ד ששמעתי פי' מכה אשר לא כתובה בתורה שיכה בשבט פיו ובלי לבוש וע\"פ משל וכו' יעו\"ש (ונראה שכונתו להמבואר כאן)."]]],[300010162,"קלג\n\n<b>אשרי</b> העם יודעי תרועה. &lt;פי' הבעש\"ט&gt; ע\"פ משל <span data-k=\"sm\">[ששמעתי </span><i>ממורי</i><span data-k=\"sm\">]</span> למדינה שהיה להם גבור <span data-k=\"sm\">[אחד]</span> ובטחו עליו כל בני המדינה, ולא למדו נימוסי המלחמה כי סמכו עצמם על הגבור שהיה ביניהם. ואח\"כ בעת המלחמה שרצה הגבור להכין כלי זיינו והשונא נתחכם וגנב ממנו כלי זיינו אחד לאחד עד שלא נשאר לו במה להלחם, וגם אנשי המדינה שסמכו עליו נלכדו עמו <span data-k=\"sm\">[וכו' ודפח\"ח]</span>.\n<b>וז\"ש</b> אשרי העם יודעי תרועה, ר\"ל כשהעם אינם סומכים על הגבור רק הם עצמם יודעי תרועת המלחמה, ואז באור פניך יהלכון לקראת המלך, <span data-k=\"sm\">[אין סומכין על הגדולים רק הם עצמן,]</span> וכמ\"ש הטור &lt;נהגו&gt; <span data-k=\"sm\">[נוהגין כולם]</span> להתענות בערב ראש השנה וכו', <span data-k=\"sm\">[ולכאורה סותר המשל וכו', ולדברינו א\"ש]</span> שאינן סומכין על <span data-k=\"sm\">[הגבורים שהם]</span> הגדולים <span data-k=\"sm\">[וכמ\"ש האלשיך הנ\"ל]</span>.\n<b>&lt;ואם</b> אמר זה בדורו, כל שכן עתה אפשר שהגבור בעצמו אינו יודע נמוסי המלחמה ואין לו כלי זיין&gt;.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י אמור קד</b>,<b> סע</b>\"<b>ב (שצג</b>,<b> א)</b>\n<i>אשרי העם גו' באור פניך גו'</i> – תהלים פט, טז. <i>וכמ\"ש הטור</i> – או\"ח סי' תקפ\"א. <i>וכמ\"ש האלשיך</i> – פירושו לישעי' נה, ו.\n----- הערות וציונים -----\nראה לעיל סי' לה והנסמן בהערות שם.\n<i>רק הם עצמם יודעי תרועת המלחמה</i> – להעיר מזח\"ג רלא, ב לא כתיב שמעי או תקעי תרועה אלא יודעי תרועה כו'. וראה לקמן בהוספות סי' סז."]]],[300010163,"קלד\n\n<b>&lt;מהבעש\"ט&gt;</b> <span data-k=\"sm\">[דשמעתי </span><i>ממורי</i><span data-k=\"sm\"> זלה\"ה]</span> ביאור <span data-k=\"sm\">[פסוק]</span> כי תצא למלחמה על אויביך ושבית שביו, כי ע\"י טענת היצה\"ר עצמו בזה כובש היצה\"ר. &lt;פי'&gt; שאם הוא &lt;היצה\"ר&gt; זריז במלאכתו לפתות את האדם בעבירה כדי לעשות שליחותו ית', כמ\"ש בזוהר משל הזונה, מזה יקח אדם מוסר לעצמו שיהיה זריז במלאכתו שלא לשמוע ליצה\"ר שהוא רצון קונו ית' <span data-k=\"sm\">[וכו' ודפח\"ח]</span>. &lt;וז\"ש ושבית שביו דייקא&gt;.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י בחקתי קטז</b>,<b> ב (תלד</b>,<b> ב)</b>\n<i>כי תצא גו'</i> – כי תצא כא, י. <i>כמ\"ש בזוהר</i> – זח\"ב קסג, א.\n----- הערות וציונים -----\nראה לקמן סי' רנד ושעב. ולהעיר מלקמן בהוספות סי' קיד וקטו."]]],[300010164,"קלה\n\n<b>&lt;מהבעש\"ט&gt;</b> <span data-k=\"sm\">[דשמעתי </span><i>ממורי</i><span data-k=\"sm\"> זלה\"ה]</span> ענין רומח, שכל המלחמות בעולם וכל המ\"ז שבאדם נמשך מחמת שהמלכות אינה ביחוד עם דודה. וכאשר יתן האדם דעת לזה, אז יראה ורעד יבוא בו ונעשה יחוד יראה עם נורא ויתפרדו כל פועלי און <span data-k=\"sm\">[וכו' ודפח\"ח]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י בחקתי קטז</b>,<b> ב (תלד</b>,<b> ב)</b>\n<i>רומח</i> – בלק כה, ז. <i>יתפרדו גו'</i> – תהלים צב, י.\n----- הערות וציונים -----\n<i>ענין רומח</i> – מבואר בר\"מ זח\"ג רלז, ב (ועיי\"ש עוד רלו, ב ואילך) דפנחס חזא מ\"ם מן מות טאס באוירא ושתף לה עם ר\"ח דאיהו יצחק ואיהו בחושבן פינחס ואשתלים בה רמ\"ח, לבתר חזא ו' מן מו\"ת טס ברקיעא וחטף ליה ושוי ליה ברמ\"ח ואשתלים רומח כו'. ועל זה אמר הבעש\"ט (דמ\"א ס\"פ בלק ד\"ה ויקח רומח) כי ראה והבין שמלכות היא בלא יחוד והבין זה מעצמו כי האדם עולם קטן ועשה יחוד וכו'. ובצ\"פ פ' וארא יח, סע\"ב (עד, ב) ששמעתי ממורי ענין פנחס ויקח רומח בידו דכתב בזוהר חמא אות מ' וגו' דכשמלכות בלי יחוד היא דין אש תכלא וע\"י יחוד נעשה רחמים וכו' יעו\"ש (ועיי\"ש ההמשך). ושם כב, ריש ע\"ב (פח, ב) והנה כל הצרות שבעולם נמשך מן מלכות כשאינו ביחוד עם דודה כמו ששמ\"מ זלה\"ה וכתבתי במ\"א כי ה' אלקיך אש אוכלה, וזה ענין רומח לייחד הוי' ואד' וכו'.\n<i>וכל המ\"ז שבאדם</i> – ראה לקמן סי' שסח-שסט.\n<i>ונעשה יחוד יראה עם נורא</i> – שהוא יחוד הוי' ואד', תפארת ומלכות, כמ\"ש לעיל בהערות לסוף סי' צג-ג עיי\"ש, ורג\"כ לקמן סי' שמב."]]],[300010165,"קלו\n\n<b>&lt;מהבעש\"ט</b> ז\"ל&gt; <span data-k=\"sm\">[ששמעתי </span><i>ממורי</i><span data-k=\"sm\"> זלה\"ה]</span> בפירוש <span data-k=\"sm\">[הפסוק]</span> תכין לבם תקשיב אזניך, ור\"ל כי סימן זה מסור ביד האדם שאם נזדמן שיוכל להכין לבו להתפלל לפניו בלי שום &lt;פניה ו&gt;מ\"ז על כל פנים, או בדחילו ורחימו, כל אחד לפי מדריגתו, אז ידוע כי נתקבלה תפלה ההיא. וז\"ש תכין לבם תקשיב אזניך, כי בעת שמתפלל יוכל לידע <span data-k=\"sm\">[שתקובל ותקשיב אזנו ית']</span> &lt;אם נתקבלה תפלה ההיא, כמרז\"ל ברחב\"ד אם שגורה תפלתי בפי כו'&gt;, <span data-k=\"sm\">[ודפח\"ח]</span>. ובחינה זו שהזמן ישר ומוכן להתפלל בשם עליה יכונה.\n<b>ויש</b> עוד בחי' שצריך האדם לעשות כמה וכמה הכנות ותחבולות כדי שיבוא בטורח גדול אולי יוכל להתפלל, כולי האי ואולי, ומ\"מ אל יאמר נואש, כי אף שיראה שהזמן הולך וסוער בכמה ביטולים וכמה קטיגורים בעבודת הש\"י, מ\"מ יתן לב <span data-k=\"sm\">[שיש]</span> בזה הבחינה הנקרא ירידה כמה מדריגות של כמה אנשים שהם במדה זו והם איברי השכינה, וזה אדם השלם ירד בעת ההיא כדי להתחבר עם כל אותן המדריגות להעלותן, כמו במשל השר הנ\"ל, <span data-k=\"sm\">[להשיבם אל אבינו שבשמים]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י נשא קכח</b>,<b> סע</b>\"<b>א (תעח</b>,<b> ב)</b>\n<i>תכין לבם גו'</i> – תהלים י, יז. <i>אם שגורה כו'</i> – ברכות לד, ב.\n----- הערות וציונים -----\n<i>סימן זה מסור כו'</i> – להעיר מברכות לא, א המתפלל צריך שיכוון כו' סימן לדבר תכין לבם גו', וברש\"י שם אם תכין לבם אז תקשיב אזנך. וכ\"ה מפורש בירושלמי ברכות סוף פ\"ה אם כוונת את לבך בתפלה תהא מבושר שנשמעה תפלתך ומה טעם תכין לבך גו'. ועיין פי' רבינו יונה ברכות רפ\"ה ד\"ה כדי שיכוונו, בביאור סימן לדבר דקאי על כוונת טהרת הלב יעו\"ש היטב.\n<i>אל יאמר נואש כו'</i> – ראה בתוי\"י שם קכז, סע\"ד (תעז, ב) לפעמים יורד הצדיק ממדריגתו בין בגשמי או ברוחני ולבל יהיה נואש ויאמר כי נתרחק מהש\"י לכך המשכיל ידע ויבין כי מה שהוא רחוק הוא לתכלית הקירוב והיינו כדי שיעלה עם המדריגות שהוא שם שהוא ג\"כ נצוצי ואיברי השכינה וכמו במשל הנ\"ל (ראה לקמן דקאי על המשל המובא בסי' קמד) שבידיעת המלך ירד השר ממדרגתו ושינה לבושו כדי שיתחבר בירידה ההיא עם בן המלך באשר הוא שם להשיבו אל אביו, הרי עושה בירידה זו רצון המלך ג\"כ, וזהו בכל דרכיך דעהו שידע לייחד מדות העליונות בין ברוחני בין בגשמי (ראה לקמן סי' רפב-א) בין בעלייתו בין בירידה כי הכל צורך גבוה (ראה לעיל סי' קב ולקמן סי' רכ-א). ועיין לקמן סי' קלט ובהערות שם.\n<i>כמו במשל השר הנ\"ל</i> – קאי על המשל שהובא שם קכז, ב (תעה, א), ולהעיר ששם הביאו בסתמא אבל במ\"א – לקמן סי' קמד (ובקיצור ושנוי קצת לקמן סי' רס) – בשם הבעש\"ט."]]],[300010166,"קלז\n\n<b>&lt;מבעש\"ט&gt;</b> <span data-k=\"sm\">[דשמעתי]</span> משל <span data-k=\"sm\">[</span><i>ממורי</i><span data-k=\"sm\">]</span> שפעם א' תעו סוחרים מן הדרך ונחו שם לישן עד שנזדמן להם איש &lt;א'&gt; להורות להם הדרך. ונזדמן א' שהוליכם למקום גדודי חיה ולסטים, ויש שהוליכם למקום ישר. והנמשל, כי אותיות התורה שבהם נברא העולם באו בעוה\"ז כדמות סוחרים ותעו מהדרך וישינים, ובא א' ולומד לשמה מוליך אותן לדרך הישר לדבקן בשרשן, משא\"כ כשאינו לומד לשמה מוליכן ללסטים, <span data-k=\"sm\">[ודפח\"ח]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י שלח קלד</b>,<b> א (תקו</b>,<b> א)</b>\n----- הערות וציונים -----\nראה לעיל סי' קכז-ב. להעיר שבעל תוי\"י הוסיף כאן אחרי דברי הבעש\"ט: וכן הוא בתפלה, ע\"י מ\"ז נפסל התפלה ומשליכן במקום פסולי המוקדשין, ואם מתפלל בר\"ה בכוונה מעלה כל התפלות של כל השנה שחרית לשחרית ומנחה למנחה עכ\"ל. ועיין לעיל בהערות לסי' קכז-ב."]]],[300010167,"קלח\n\n<b>&lt;מבעש\"ט&gt;</b> <span data-k=\"sm\">[וכן שמעתי פירש הש\"ס]</span> &lt;הגמ'&gt; <span data-k=\"sm\">[דברכות]</span> &lt;כרום זלות לבני אדם&gt;, דברים שעומדים ברומו של עולם ובני אדם מזלזלין בהן, והכוונה לפי שהפעולה של התפלה הוא <span data-k=\"sm\">[למעלה]</span> ברומו של עולם ולא למטה לפעמים, לכך בני אדם מזלזלין בהן בחשבם שתפלתם ח\"ו לריק, וזה אינו, <span data-k=\"sm\">[ודפח\"ח]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י שלח קלד</b>,<b> ריש ע</b>\"<b>ב (תקט</b>,<b> ב)</b>\n<i>הגמ'</i> – ברכות ו, ב. <i>כרם זלת גו'</i> – תהלים יב, ט.\n----- הערות וציונים -----\nראה לעיל סי' פ ובהערות שם."]]],[300010168,"קלט\n\n[<b>שמעתי</b> <i>ממורי</i><span data-k=\"sm\">]</span> ביאור פסוק אחור וקדם צרתני ותשת עלי כפך, &lt;ופי'&gt; כי החיות רצוא ושוב, וחיות האדם הוא בסוד קטנות וגדלות, וכאשר יתן דעתו לידע שהוא בקטנות, ע\"י דעת זה נמתקו הדינין בשרשן, כי ה' גבורות מנצפ\"ך בדעת זעיר אנפין <span data-k=\"sm\">[וכו', ודפח\"ח]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י חקת קמו</b>,<b> ג (תקמג</b>,<b> א)</b>\n<i>אחור וקדם גו'</i> – תהלים קלט, ה. <i>החיות רצו\"ש</i> – יחזקאל א, יד. <i>ה' גבורות מנצפ\"ך כו'</i> – ע\"ח ש\"ה פ\"ג. שם שכ\"ה פ\"ב.\n----- הערות וציונים -----\nנשנה לקמן סי' רעא. ראה לעיל סי' קג ולקמן סי' קפ, קפד ושפד. להעיר מדמ\"א ר\"פ ויצא: סוד גדלות וקטנות כידוע בשם אא\"ז נ\"ע זללה\"ה כי החיות רצוא ושוב וא\"א לעמוד על מדריגה אחת תמיד רק עולה ויורד, והירידה הוא צורך עליה כשנותן על לב ויודע ומרגיש זה שהוא בקטנות ומתפלל אל ה', ע\"ד ובקשתם משם את ה' אלקיך ומצאת (ואתחנן ד, כט), וזהו משם, ממקום שהוא שם כמ\"ש אא\"ז נ\"ע זללה\"ה. ועיי\"ע מזה לעיל סי' – וסוף סי' קלו."]]],[300010169,"קמ\n\n<b>&lt;מבעש\"ט</b> ז\"ל&gt; <span data-k=\"sm\">[שמעתי </span><i>ממורי</i><span data-k=\"sm\"> זלה\"ה מה שאמרו חז\"ל]</span> כל רב בבבל וכל רבי בארץ ישראל, כי בחינת חכמה ובינה נתפשט בכל העולם, והוא ר' ראשית חכמה, ב' הוא בינה, וכל עניני ומעשה עוה\"ז הכל הוא זווגים ויחודים, רק שלא יש שם נביע היא אות י', ועם נביע מאין סוף שהוא אות י' נקרא רבי והוא בא\"י, <span data-k=\"sm\">[ודפח\"ח]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י חקת קמו</b>,<b> ריש ע</b>\"<b>ד (תקמג</b>,<b> ב)</b>\n<i>כל רב בבבל כו'</i> – תקזו\"ח צח, א. ערוך, ערך אביי. <i>ר' ראשית חכמה</i> – תקו\"ז תס\"ט קיא, ב. שם קטז, א. <i>ב' הוא בינה</i> – תקו\"ז תי\"ח לא, סע\"ב. שם תס\"ט קטז, א. <i>נביע היא אות י</i> – תקו\"ז ת\"ל עג, ב. שם תכ\"א מד, א. <i>נביע מא\"ס כו'</i> – ר' זח\"ב מב, ב. תקו\"ז ת\"ע קלד, ריש ע\"ב.\n----- הערות וציונים -----\n<i>כל רב מבבל וכל רבי בא\"י</i> – מבואר בע\"ח שי\"ט ספ\"ג, ובריש ס' שער מאמרי רשב\"י, וכן בפירוש הרח\"ו לתקו\"ז אשר בסוף ס' תקו\"ז, בתחילתו. וראה דמ\"א, פ' צו ד\"ה ועתה נבוא."]]],[300010170,"קמא\n\n<b>&lt;מהבעש\"ט&gt;</b> <span data-k=\"sm\">[שמעתי </span><i>ממורי</i><span data-k=\"sm\">]</span> פירוש <span data-k=\"sm\">[הפסוק]</span> חשבתי דרכי ואשיבה רגלי אל עדותיך. והענין, כי אין צדיק בארץ אשר יעשה טוב ולא יחטא, ר\"ל שלא יהיה בטוב ההוא אשר יעשה מבלי שום פניה וחטא, זה אי אפשר. וביאר, כי כשיעשה טוב בלי שום דבר רע מתגרה בו היצה\"ר, משא\"כ כשרואה היצה\"ר שיש בו <span data-k=\"sm\">[תערובת]</span> חלק היצה\"ר מניחו והולך לו, ואז גומר הדבר ויעשה לשמה אח\"כ. וז\"ש ישראל גנבים הם, כי צריך לגנוב דעת היצה\"ר בכל דבר מצוה.\n<b>וז\"ש</b> חשבתי דרכי, ר\"ל בכל דבר מצוה או קדושה בהתחלה חשבתי דרכי להנאתי הגשמי, ואח\"כ ואשיבה רגלי אל עדותיך, ר\"ל רגלי ההרגל שהורגל אצלי שלא לשמה, אז עשיתי לשמה.\n<b>וז\"ש</b> חצות לילה אקום, ר\"ל לתועלתי הגשמי, כי מיד שיתעורר משנתו לשם שמים אי אפשר, אלא חצות לילה אקו\"ם לצרכי, ואז בדבר הטבע יכול לגבור על הטבע שינת חצות, <span data-k=\"sm\">[ודפח\"ח]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י חקת קנא</b>,<b> א (תקנח</b>,<b> ב)</b>\n<i>חשבתי גו'</i> – תהלים קיט, נט. <i>אין צדיק גו'</i> – קהלת ז, כ. <i>ישראל גנבים הם</i> – ע\"ז ע, א. <i>חצות לילה אקום</i> – תהלים קיט, סב.\n----- הערות וציונים -----\nראה לקמן סי' קפח. וראה או\"ת סי' רמו.\n<i>אין צדיק כו'</i> – לכאורה צ\"ע מתוס' שבת נה, ב ד\"ה ארבעה, וי\"ל ע\"פ תוס' ב\"ב יז, א ד\"ה שלשה לא שלט.\n<i>צריך לגנוב דעת היצה\"ר</i> – להעיר מפדר\"א פמ\"ו. זח\"ג סג, רע\"א ובר\"מ שם, ושם קא, ב. רמב\"ן ורב\"ח לאחרי טז, ז-ח.\n<i>בהתחלה </i>. .<i> להנאתי הגשמי ואח\"כ כו'</i> – ראה צ\"פ פ' בא לה, סע\"ג (קל, ב): ויש משל בזה כי מן המורגש יבא למושכל.\n<i>ר\"ל רגלי ההרגל שהורגל</i> – ראה לעיל סי' נז ובהערות שם.\n<i>בדבר הטבע יכול לגבור על הטבע</i> – להעיר מלעיל סי' כד."]]],[300010171,"קמב\n\n[<b>ששמעתי</b> <i>ממורי</i><span data-k=\"sm\">]</span> ענין לשמה לשם האות עצמו, <span data-k=\"sm\">[ודו\"ק ודפח\"ח]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י חקת קנא</b>,<b> ג (תקס</b>,<b> ב)</b>\n----- הערות וציונים -----\nהדרוש במילואו לקמן סי' תכו עיי\"ש. וראה לעיל סי' קכז-ב. להעיר ממש\"כ בהקדמת ס' תוי\"י ג, סע\"ג ואילך (יא, א): שאיתא בכתבים (שער המצות, פ' ואתחנן ענין מ\"ש רז\"ל רמ\"א כל העוסק בתורה לשמה. שער מאמרי רז\"ל, אבות. פע\"ח, שער הנהגת הלימוד) ענין לשמה לשם ה' להמשיך הארה מיסוד אבא אל לאה שכל ספירותיה ה' ונמתק עי\"ז כל דינין תקיפין יעו\"ש. ואני שמעתי בשם מורי כי לשמה הוא לשם התיבה והאות עצמה לדבקה בשרשה וכו', ולכאורה הוא כסותר הנ\"ל, איברא דבאמת למכוון אחד עולה, כי ע\"י המשכת יסוד אבא שהוא הנשמה וכח המחבר לדבק בשרשה וכמרומז באות ה' וכנ\"ל, ואתי שפיר ודי בזה."]]],[300010172,"קמג\n\n<b>אחיה</b> השילוני שקיבל ממשה רבינו ע\"ה והיה מיוצאי מצרים ואח\"כ מבית דינו של דוד המלך ע\"ה, והיה רבו של אליהו הנביא ז\"ל ורבו של <i>מורי</i> &lt;הבעש\"ט&gt; זללה\"ה.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י בלק קנו</b>,<b> רע</b>\"<b>א (תקעה</b>,<b> ב)</b>\n<i>אחי' השילוני </i>. .<i> אליהו הנביא ז\"ל</i> – ב\"ב קכא, ב. רמב\"ם, הקדמת יד החזקה.\n----- הערות וציונים -----\n<i>ורבו של מורי זלה\"ה</i> – ראה לקמן בהוספות סי' רפא ובהערות שם."]]],[300010173,"קמד\n\n<b>&lt;מהבעש\"ט&gt;</b> <span data-k=\"sm\">[ושמעתי]</span> משל <span data-k=\"sm\">[</span><i>ממורי</i><span data-k=\"sm\">]</span> למלך ששלח בנו &lt;יחידו&gt; <span data-k=\"sm\">[ידידו]</span> למרחקים כדי שיהיה לו אח\"כ יותר תענוג, וברבות הימים נשכח מבן המלך כל תענוגי המלך. ושלח אחריו ולא רצה לחזור לאביו, וכל מה ששלח המלך יותר שרים חשובים אחריו לא הועילו כלום, עד שהיה שם שר א' חכם שכסות ולשון שינה כדמות הבן ההוא, ונתקרב אליו במדריגתו והשיבו אל אביו, <span data-k=\"sm\">[ודפח\"ח]</span>. &lt;וזהו התלבשות התורה בסיפורים גשמיים&gt;.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י ואתחנן קסט</b>,<b> סע</b>\"<b>ב (תרכד</b>,<b> א)</b>\n----- הערות וציונים -----\nהנמשל לעיל סי' קלו.\n<i>וזה התלבשות התורה כו'</i> – להעיר מזח\"ג קמט, ב ושם קנב, א. וראה לעיל סי' פד (ד\"ה ותירץ) ולקמן סי' רמב. מדל\"י סי' פד (צה) ושם קעז (קפב). לקו\"י לב, א (סי' רנא, וכן באו\"ת סי' פא)."]]]]});
